package com.ascent.climb.data.i18n

/**
 * Quiz en français, deuxième partie (clés nouvelles du lot d'extension).
 * Clés identiques à PackEnQuiz.kt ; chiffres, posologies et échelles inchangés.
 */
internal val PACK_FR_QUIZ_B: Map<String, String> = mapOf(
    // ---------- l1 Comprendre le risque en montagne ----------
    "q.l1#10.p" to "Lequel des éléments suivants relève d'un danger subjectif ?",
    "q.l1#10.o0" to "La baisse du jugement causée par la fatigue",
    "q.l1#10.o1" to "Les chutes de pierres",
    "q.l1#10.o2" to "Les crevasses",
    "q.l1#10.o3" to "Les orages",
    "q.l1#10.e" to "Les dangers subjectifs viennent de l'état et des décisions des personnes : fatigue, course contre le temps, excès de confiance, pression du groupe. Ils sont plus difficiles à repérer que les dangers objectifs, et plus souvent encore au départ de l'accident.",
    "q.l1#11.p" to "Pourquoi un bon équipement ne remplace-t-il pas le jugement ?",
    "q.l1#11.o0" to "Parce que l'équipement réduit les conséquences, pas l'existence du danger",
    "q.l1#11.o1" to "Parce que l'équipement s'use",
    "q.l1#11.o2" to "Parce qu'il pèse lourd",
    "q.l1#11.o3" to "Parce que le bon matériel coûte cher",
    "q.l1#11.e" to "Casque, corde et encordement réduisent les dommages après coup ; ils ne font pas disparaître une avalanche ni une crevasse. Prendre le matériel pour un talisman est le biais cognitif le plus courant.",
    "q.l1#12.p" to "De quoi un accident en montagne est-il généralement fait ?",
    "q.l1#12.o0" to "De plusieurs petits écarts qui s'accumulent, puis d'un événement déclencheur",
    "q.l1#12.o1" to "D'une seule mauvaise décision",
    "q.l1#12.o2" to "De pure malchance",
    "q.l1#12.o3" to "D'une défaillance soudaine du matériel",
    "q.l1#12.e" to "La chaîne d'accident typique est : départ tardif, course contre le temps, contrôle sauté, changement imprévu, aucune marge. Casser un seul maillon suffit à l'éviter.",
    "q.l1#13.p" to "À propos de la montée en solitaire, quelle affirmation est la plus juste ?",
    "q.l1#13.o0" to "Le risque augmente nettement : plus de second freinage, plus de secours, plus de second regard sur le jugement",
    "q.l1#13.o1" to "Avec assez d'expérience, il n'y a pas de problème",
    "q.l1#13.o2" to "C'est plus sûr qu'en cordée",
    "q.l1#13.o3" to "Cela ne dépend que du matériel",
    "q.l1#13.e" to "Le risque du solitaire n'est pas technique : il est dans le fait que personne ne peut voir que vous êtes en train de vous tromper. C'est aussi pourquoi beaucoup d'itinéraires exigent d'être au moins deux.",
    "q.l1#14.p" to "Quel est l'intérêt de la formule « risque = exposition × probabilité × conséquence » pour préparer une course ?",
    "q.l1#14.o0" to "On peut réduire le risque par trois voies : réduire le temps d'exposition, réduire la probabilité, réduire la conséquence",
    "q.l1#14.o1" to "On ne peut compter que sur la chance",
    "q.l1#14.o2" to "Il suffit de réduire la probabilité",
    "q.l1#14.o3" to "Il suffit de prendre une assurance",
    "q.l1#14.e" to "Parmi les trois voies, « raccourcir le temps d'exposition » est la plus souvent oubliée et la plus efficace : ne pas s'arrêter en terrain d'avalanche, quitter la zone de séracs avant le début d'après-midi.",

    // ---------- l2 Matériel : piolet et crampons ----------
    "q.l2#10.p" to "Quelle est la tendance d'usage de la dragonne de piolet en escalade technique moderne ?",
    "q.l2#10.o0" to "La plupart des escalades techniques n'utilisent plus de dragonne, mais une longe de retenue ou rien du tout",
    "q.l2#10.o1" to "Elle est obligatoire en permanence",
    "q.l2#10.o2" to "Uniquement en cascade de glace",
    "q.l2#10.o3" to "Uniquement sur pente de neige",
    "q.l2#10.e" to "En cas de chute, la dragonne peut provoquer une entorse du poignet ou s'accrocher. La pratique moderne privilégie « pas de dragonne + prise fiable », mais la marche longue en neige garde des usages.",
    "q.l2#11.p" to "Quelle est la différence entre crampons à pointes verticales et à pointes horizontales ?",
    "q.l2#11.o0" to "L'orientation et la forme des pointes diffèrent : les verticales servent la technique des pointes avant, les horizontales la marche à plat",
    "q.l2#11.o1" to "Le nombre de pointes",
    "q.l2#11.o2" to "Le matériau",
    "q.l2#11.o3" to "Le poids",
    "q.l2#11.e" to "Les pointes verticales conviennent au plantage en glace dure ; les horizontales à la technique française sur pente de neige. Se tromper déforme le geste technique.",
    "q.l2#12.p" to "Une fois les crampons émoussés, quelle est la conséquence la plus directe ?",
    "q.l2#12.o0" to "Le plantage devient difficile, on glisse plus facilement et on se fatigue davantage",
    "q.l2#12.o1" to "Le poids augmente",
    "q.l2#12.o2" to "La couleur fonce",
    "q.l2#12.o3" to "Aucun effet sur l'usage",
    "q.l2#12.e" to "Des pointes émoussées demandent beaucoup plus de force pour mordre, et la fatigue arrive plus tôt. Affûter les pointes à la lime avant de partir fait partie de l'entretien courant.",
    "q.l2#13.p" to "Quand on loue ou emprunte des crampons, que faut-il vérifier en priorité ?",
    "q.l2#13.o0" to "La compatibilité avec ses propres chaussures (automatique / semi-automatique / à sangle) et la fiabilité des fermetures",
    "q.l2#13.o1" to "La couleur",
    "q.l2#13.o2" to "La marque",
    "q.l2#13.o3" to "L'âge",
    "q.l2#13.e" to "Des crampons automatiques (C3) sur une chaussure à tige souple se décrochent purement et simplement. La compatibilité compte plus que les caractéristiques techniques.",
    "q.l2#14.p" to "À propos de la longueur du piolet, quelle affirmation est correcte ?",
    "q.l2#14.o0" to "Un piolet long pour la marche sur neige (jusqu'au milieu du tibia), un piolet court pour l'escalade technique",
    "q.l2#14.o1" to "Plus il est long, plus c'est sûr",
    "q.l2#14.o2" to "Plus il est court, moins on se fatigue",
    "q.l2#14.o3" to "Cela n'a aucun rapport avec la taille",
    "q.l2#14.e" to "Le long sert de canne, le court à la technique de frappe. Faire une longue pente de neige avec un piolet technique court, c'est se pencher des centaines de fois dans la journée.",

    // ---------- l3 Chaussures d'alpinisme et système vestimentaire ----------
    "q.l3#10.p" to "La chaussette intérieure d'une chaussure double est mouillée. Que faire de plus raisonnable ?",
    "q.l3#10.o0" to "La sortir, la garder contre le corps ou la mettre dans le duvet pour la sécher, jamais au feu",
    "q.l3#10.o1" to "Garder la chaussette humide",
    "q.l3#10.o2" to "La sécher au feu",
    "q.l3#10.o3" to "La laisser geler dehors toute la nuit",
    "q.l3#10.e" to "Le séchage à la chaleur du corps est le plus sûr. Le feu abîme les mousses, et une nuit dehors laisse la chaussette dure le lendemain.",
    "q.l3#11.p" to "Quelle est la bonne combinaison de chaussettes ?",
    "q.l3#11.o0" to "Une fine couche respirante à l'intérieur, une épaisse en laine à l'extérieur",
    "q.l3#11.o1" to "Une seule grosse chaussette en coton",
    "q.l3#11.o2" to "Deux grosses chaussettes en coton",
    "q.l3#11.o3" to "Bas en soie et chaussette en coton",
    "q.l3#11.e" to "La structure à deux couches fait porter le frottement entre les chaussettes et non sur la peau. Le coton mouillé ne sèche pas : c'est la première cause d'ampoules.",
    "q.l3#12.p" to "À quoi servent principalement les guêtres ?",
    "q.l3#12.o0" to "Empêcher la neige d'entrer par le haut de la chaussure et protéger le bas du pantalon",
    "q.l3#12.o1" to "Tenir chaud",
    "q.l3#12.o2" to "Empêcher de glisser",
    "q.l3#12.o3" to "Gagner de la hauteur",
    "q.l3#12.e" to "Sans guêtres en neige profonde, la chaussure se remplit en dix minutes, puis viennent les pieds mouillés et le risque d'engelure.",
    "q.l3#13.p" to "Que faut-il faire des chaussures neuves avant de les utiliser ?",
    "q.l3#13.o0" to "Les roder à l'avance, avec de courtes sorties pour repérer les points de compression",
    "q.l3#13.o1" to "Partir directement sur une longue course",
    "q.l3#13.o2" to "Les tremper pour les assouplir",
    "q.l3#13.o3" to "Les prendre les plus serrées possible",
    "q.l3#13.e" to "Une chaussure d'alpinisme se rode très mal en montagne. Une courte sortie avant le départ révèle les points de frottement, et cela vaut mieux qu'une pile de pansements.",
    "q.l3#14.p" to "Quel est l'indice le plus fiable que les pieds sont trop froids ?",
    "q.l3#14.o0" to "Sensation émoussée, gestes ralentis, peau qui blanchit",
    "q.l3#14.o1" to "La personne dit qu'elle a froid",
    "q.l3#14.o2" to "Les chaussettes sont mouillées",
    "q.l3#14.o3" to "Les lacets sont desserrés",
    "q.l3#14.e" to "« Avoir froid » n'est pas encore dangereux ; « ne plus sentir le froid et bouger maladroitement » annonce l'engelure. Il faut aller vérifier activement les orteils et les doigts des partenaires.",

    // ---------- l4 Marche sur pente de neige ----------
    "q.l4#8.p" to "À quoi sert le pas de repos ?",
    "q.l4#8.o0" to "À reporter le poids sur la jambe tendue à chaque pas, pour que l'autre jambe se repose vraiment",
    "q.l4#8.o1" to "À s'arrêter pour souffler",
    "q.l4#8.o2" to "À ralentir",
    "q.l4#8.o3" to "À changer de main sur le piolet",
    "q.l4#8.e" to "Le pas de repos fait porter les jambes à tour de rôle pendant la marche, au lieu de garder les muscles contractés en permanence. Sur une longue pente de neige, c'est ce qui décide si l'on tient jusqu'au bout.",
    "q.l4#9.p" to "En traversée sur neige dure, quelle est la bonne façon de faire ?",
    "q.l4#9.o0" to "Pied amont en bas, pied aval en haut, piolet tenu du côté amont",
    "q.l4#9.o1" to "Les deux pieds parallèles",
    "q.l4#9.o2" to "Piolet tenu du côté aval",
    "q.l4#9.o3" to "Le corps tourné vers le bas de la pente",
    "q.l4#9.e" to "Le piolet du côté amont permet de le planter aussitôt en cas de glissade. Avec les pieds inversés, le premier réflexe vous fait trébucher.",
    "q.l4#10.p" to "Pour monter une pente raide continue, quelle est la manière la moins fatigante ?",
    "q.l4#10.o0" to "En zigzag, pour réduire la pente",
    "q.l4#10.o1" to "En ligne droite",
    "q.l4#10.o2" to "En courant",
    "q.l4#10.o3" to "De côté, par bonds",
    "q.l4#10.e" to "Le zigzag échange de la pente contre de la distance et réduit nettement la hauteur de chaque pas. En contrepartie le trajet s'allonge : il faut le prévoir dans les horaires.",
    "q.l4#11.p" to "Une douleur vive au genou en descente vient le plus probablement de…",
    "q.l4#11.o0" to "Des foulées trop longues, avec le genou qui se verrouille à l'atterrissage",
    "q.l4#11.o1" to "Des chaussures trop souples",
    "q.l4#11.o2" to "Des chaussettes trop épaisses",
    "q.l4#11.o3" to "D'un sac trop léger",
    "q.l4#11.e" to "L'impact en descente est plusieurs fois celui de la montée. Raccourcir la foulée et garder le genou légèrement fléchi est la protection la plus efficace.",
    "q.l4#12.p" to "En « frappant les marches » sur une pente de neige, comment le pied doit-il se poser ?",
    "q.l4#12.o0" to "Avec l'avant de la semelle ou le pied entier, en tassant une marche horizontale, la pointe légèrement relevée",
    "q.l4#12.o1" to "Pointe plantée droit",
    "q.l4#12.o2" to "Sur le talon",
    "q.l4#12.o3" to "Sur le côté du pied",
    "q.l4#12.e" to "La marche doit être plate pour tenir. La pointe relevée permet à la semelle de tasser un plan horizontal au lieu de creuser un trou oblique.",

    // ---------- l21 Système vestimentaire et les couches ----------
    "q.l21#10.p" to "Dans le système à trois couches, quel est le rôle central de la couche intermédiaire ?",
    "q.l21#10.o0" to "Retenir la chaleur tout en évacuant la vapeur de transpiration",
    "q.l21#10.o1" to "Couper le vent",
    "q.l21#10.o2" to "Évacuer la sueur",
    "q.l21#10.o3" to "Protéger de la pluie",
    "q.l21#10.e" to "La couche intermédiaire (polaire ou duvet léger) assure « chaleur + respirabilité ». Trop épaisse, elle fait transpirer à la montée ; trop fine, elle laisse refroidir dès l'arrêt.",
    "q.l21#11.p" to "Quelle est la différence principale entre softshell et hardshell ?",
    "q.l21#11.o0" to "Le softshell respire mieux et résiste à l'abrasion, le hardshell protège mieux du vent et de l'eau",
    "q.l21#11.o1" to "Le softshell est plus cher",
    "q.l21#11.o2" to "Le hardshell est plus léger",
    "q.l21#11.o3" to "Aucune différence",
    "q.l21#11.e" to "Par temps sec et froid, on privilégie le softshell (respirabilité) ; sous la pluie, la neige et le vent, le hardshell (protection). Se tromper, c'est choisir entre transpirer ou être trempé.",
    "q.l21#12.p" to "Quel est le bon ordre pour réguler sa température en marche ?",
    "q.l21#12.o0" to "Ouvrir d'abord le col et les aisselles, puis retirer la couche externe, et seulement ensuite la couche intermédiaire",
    "q.l21#12.o1" to "Tout enlever jusqu'à la seule couche respirante",
    "q.l21#12.o2" to "Retirer d'abord la couche intermédiaire",
    "q.l21#12.o3" to "S'arrêter et se déshabiller dès qu'on transpire",
    "q.l21#12.e" to "Le réglage fin vaut mieux que le changement complet : une fermeture ouverte fait perdre deux ou trois degrés. Enlever et remettre sans cesse fait perdre du temps et refroidit à l'arrêt.",
    "q.l21#13.p" to "Pourquoi la couche de rechange doit-elle rester absolument sèche ?",
    "q.l21#13.o0" to "Parce qu'une couche mouillée n'isole presque plus, et qu'elle sert justement quand on est bloqué",
    "q.l21#13.o1" to "Parce qu'elle moisit",
    "q.l21#13.o2" to "Parce qu'elle devient lourde",
    "q.l21#13.o3" to "Parce qu'elle sent mauvais",
    "q.l21#13.e" to "La couche de rechange est l'assurance de l'arrêt. Si elle est mouillée, elle est inutile au moment précis où on en a le plus besoin.",
    "q.l21#14.p" to "Quel est l'avantage d'une veste synthétique par rapport au duvet ?",
    "q.l21#14.o0" to "Elle conserve une partie de son pouvoir isolant une fois humide",
    "q.l21#14.o1" to "Elle est plus légère",
    "q.l21#14.o2" to "Elle est plus chaude",
    "q.l21#14.o3" to "Elle est moins chère",
    "q.l21#14.e" to "Le duvet mouillé n'isole presque plus, le synthétique tient encore. En milieu humide, le synthétique est le choix le plus sûr.",

    // ---------- m01 Sciences de l'environnement alpin ----------
    "q.m01#13.p" to "Comment le point d'ébullition de l'eau évolue-t-il avec l'altitude, et quel effet cela a-t-il sur la cuisine ?",
    "q.m01#13.o0" to "Il baisse : les aliments cuisent plus difficilement, avec plus d'eau et plus de combustible",
    "q.m01#13.o1" to "Il monte : tout cuit plus vite",
    "q.m01#13.o2" to "Il ne change pas",
    "q.m01#13.o3" to "L'eau gèle",
    "q.m01#13.e" to "Vers 5 000 m, il est d'environ 83 °C. Le riz et les légumineuses demandent plus de temps ou un trempage préalable : c'est l'une des raisons pour lesquelles la haute altitude préfère les plats déshydratés.",
    "q.m01#14.p" to "Par nuit claire, pourquoi l'intérieur de la tente est-il plus froid que la température de l'air ?",
    "q.m01#14.o0" to "Le sol et la tente rayonnent vers l'extérieur et produisent du givre",
    "q.m01#14.o1" to "Parce qu'il y a plus de vent",
    "q.m01#14.o2" to "Parce qu'il y a moins d'oxygène",
    "q.m01#14.o3" to "Parce que l'humidité est plus élevée",
    "q.m01#14.e" to "Le refroidissement radiatif nocturne fait descendre la température de surface sous celle de l'air : c'est l'origine du givre sur la paroi. Et c'est pourquoi on range le sac de couchage en premier le matin.",

    // ---------- m02 Préparation physique et nutrition ----------
    "q.m02#10.p" to "Quelle structure d'entraînement est la plus raisonnable avant une course ?",
    "q.m02#10.o0" to "Surtout de l'endurance aérobie, avec de la force et des montées chargées, en augmentant la charge semaine après semaine",
    "q.m02#10.o1" to "Fractionné intense tous les jours",
    "q.m02#10.o2" to "Uniquement de la force",
    "q.m02#10.o3" to "Uniquement des étirements",
    "q.m02#10.e" to "L'alpinisme est un effort long et peu intense : la base aérobie compte le plus. La charge doit être progressive, et les deux semaines avant le départ servent à réduire.",
    "q.m02#11.p" to "Sur quoi faut-il insister dans les deux semaines qui précèdent le départ ?",
    "q.m02#11.o0" to "Réduire la charge, entretenir la forme, garantir le sommeil",
    "q.m02#11.o1" to "Augmenter l'intensité",
    "q.m02#11.o2" to "Essayer de nouvelles activités",
    "q.m02#11.o3" to "Tout arrêter",
    "q.m02#11.e" to "Partir fatigué, c'est réserver son plus mauvais état au moment où l'on en a le plus besoin. La période d'affûtage fait partie de l'entraînement, ce n'est pas de la paresse.",
    "q.m02#12.p" to "À propos de la caféine en altitude, quelle affirmation est correcte ?",
    "q.m02#12.o0" to "Elle peut être utilisée avec modération, mais ne remplace ni le sommeil ni l'hydratation",
    "q.m02#12.o1" to "Plus on en prend, plus on est alerte",
    "q.m02#12.o2" to "Elle est totalement interdite",
    "q.m02#12.o3" to "Elle soigne le mal des montagnes",
    "q.m02#12.e" to "La caféine améliore temporairement la sensation de fatigue, sans changer l'hypoxie. S'en servir pour tenir pousse le problème à plus tard, et plus dangereusement.",

    // ---------- m03 Environnement et savoir-vivre en pleine nature ----------
    "q.m03#10.p" to "Quelle distance est recommandée entre le camp et un point d'eau ?",
    "q.m03#10.o0" to "Plus de 60 m",
    "q.m03#10.o1" to "5 m",
    "q.m03#10.o2" to "10 m",
    "q.m03#10.o3" to "Le plus près possible",
    "q.m03#10.e" to "60 m (environ 70 pas) est la distance sanitaire courante, pour les besoins, la toilette et la vaisselle.",
    "q.m03#11.p" to "Quelle est la bonne attitude vis-à-vis du feu en pleine nature ?",
    "q.m03#11.o0" to "Privilégier le réchaud ; si un feu est vraiment nécessaire, utiliser un cercle existant et l'éteindre complètement",
    "q.m03#11.o1" to "Un feu, c'est plus convivial",
    "q.m03#11.o2" to "Tant qu'on ne déclenche pas d'incendie, ça va",
    "q.m03#11.o3" to "Le feu éloigne les animaux",
    "q.m03#11.e" to "Les traces de feu restent des années et incitent les suivants à faire du feu au même endroit. Une étincelle en saison sèche peut provoquer une vraie catastrophe.",
    "q.m03#12.p" to "Quelle est la bonne conduite face à un animal sauvage ?",
    "q.m03#12.o0" to "Garder ses distances, ne pas nourrir, reculer doucement, ne pas le poursuivre pour une photo",
    "q.m03#12.o1" to "S'approcher pour photographier",
    "q.m03#12.o2" to "Nourrir pour le calmer",
    "q.m03#12.o3" to "Le chasser en criant",
    "q.m03#12.e" to "Nourrir modifie le comportement des animaux et augmente le risque de conflit. Garder ses distances protège à la fois soi-même et eux.",

    // ---------- m04 Météo et navigation : les bases ----------
    "q.m04#10.p" to "Dans un bulletin météo, qu'est-ce qui compte plus que la « probabilité de précipitation » ?",
    "q.m04#10.o0" to "La vitesse du vent, la température et la forme des précipitations (pluie ou neige) selon l'altitude",
    "q.m04#10.o1" to "Uniquement la probabilité de précipitation",
    "q.m04#10.o2" to "Uniquement la température maximale",
    "q.m04#10.o3" to "Uniquement l'humidité",
    "q.m04#10.e" to "À quantité égale, la pluie ou la neige ne change pas du tout la course. Le vent décide de la sensation et de la possibilité d'avancer, la température décide du matériel.",
    "q.m04#11.p" to "Quel schéma météo est courant l'après-midi en montagne ?",
    "q.m04#11.o0" to "La nébulosité augmente, la convection se développe, le risque d'orage et d'averses monte",
    "q.m04#11.o1" to "Un ciel clair persistant",
    "q.m04#11.o2" to "Un vent qui faiblit",
    "q.m04#11.o3" to "Une baisse de température très rapide",
    "q.m04#11.e" to "C'est l'origine de la règle « partir le matin, quitter le terrain exposé l'après-midi ». La course se conçoit en suivant ce rythme.",
    "q.m04#12.p" to "Avec le gradient thermique, de combien la température baisse-t-elle environ par 1 000 m ?",
    "q.m04#12.o0" to "6,5 °C",
    "q.m04#12.o1" to "2 °C",
    "q.m04#12.o2" to "10 °C",
    "q.m04#12.o3" to "15 °C",
    "q.m04#12.e" to "6,5 °C par 1 000 m est le gradient moyen. Il permet d'estimer l'altitude de l'isotherme zéro et donc de savoir s'il pleuvra ou s'il neigera.",

    // ---------- m05 Sommets objectifs : première neige ----------
    "q.m05#10.p" to "Pourquoi la « fenêtre saisonnière » compte-t-elle pour une première course sur neige ?",
    "q.m05#10.o0" to "Parce que l'enneigement, le vent et la politique de permis varient beaucoup selon la saison, et que rater la fenêtre double la difficulté",
    "q.m05#10.o1" to "À cause du prix du billet",
    "q.m05#10.o2" to "À cause de la foule",
    "q.m05#10.o3" to "À cause de l'ensoleillement",
    "q.m05#10.e" to "La même montagne avant et après la mousson, ce sont deux niveaux de difficulté. On choisit d'abord la saison, ensuite l'itinéraire.",
    "q.m05#11.p" to "Au moment de choisir un premier sommet, que signifie « faut-il des manœuvres techniques » ?",
    "q.m05#11.o0" to "S'il faut s'encorder, assurer, progresser sur glacier, etc.",
    "q.m05#11.o1" to "S'il faut un billet d'entrée",
    "q.m05#11.o2" to "S'il faut un guide",
    "q.m05#11.o3" to "S'il faut une tente",
    "q.m05#11.e" to "C'est là que se joue la différence entre itinéraire de randonnée et itinéraire technique. Pour une première course sur neige, on privilégie un itinéraire sans manœuvres techniques.",
    "q.m05#12.p" to "À propos du « taux de réussite », quelle lecture est correcte ?",
    "q.m05#12.o0" to "Il reflète la fenêtre météo et la difficulté de l'itinéraire, mais les méthodes de calcul varient beaucoup d'une année à l'autre",
    "q.m05#12.o1" to "Plus il est élevé, mieux c'est",
    "q.m05#12.o2" to "Plus il est bas, plus c'est sûr",
    "q.m05#12.o3" to "Il n'a aucune valeur indicative",
    "q.m05#12.e" to "Le taux de réussite est une information, pas une garantie. Il faut regarder l'année, la saison et si l'assistance des équipes commerciales est incluse.",
    // ---------- l5 Technique des crampons : française / allemande / mixte ----------
    "q.l5#10.p" to "Quand la neige s'accumule sous les crampons (balling), quelle est la réaction la plus efficace ?",
    "q.l5#10.o0" to "Décoller la neige avec la pointe du piolet et appliquer une cire anti-neige, ou passer à des crampons à plaques anti-ballonnement",
    "q.l5#10.o1" to "Continuer à marcher, ça fondra",
    "q.l5#10.o2" to "Frapper les crampons contre un arbre",
    "q.l5#10.o3" to "Retirer les crampons",
    "q.l5#10.e" to "La neige accumulée empêche les pointes de mordre : c'est comme marcher pieds nus sur une pente de glace. Il faut traiter vite, sans attendre le prochain replat.",
    "q.l5#11.p" to "Au plantage des pointes avant, dans quel état doit être la cheville ?",
    "q.l5#11.o0" to "Relâchée, pour laisser les pointes entrer verticalement, sans pousser avec la cheville verrouillée",
    "q.l5#11.o1" to "Verrouillée",
    "q.l5#11.o2" to "Pointe de pied relevée",
    "q.l5#11.o3" to "Talon en premier",
    "q.l5#11.e" to "Une cheville verrouillée fatigue très vite le mollet et fait entrer les pointes en biais. Cheville relâchée, les pointes mordent verticalement.",
    "q.l5#12.p" to "Sur glace dure (glace bleue), pourquoi la technique française à plat n'est-elle pas fiable ?",
    "q.l5#12.o0" to "Les pointes horizontales ne peuvent pas mordre la glace dure : on glisse d'un bloc",
    "q.l5#12.o1" to "Parce que c'est trop lent",
    "q.l5#12.o2" to "Parce que c'est trop fatigant",
    "q.l5#12.o3" to "Parce que c'est laid",
    "q.l5#12.e" to "La technique française repose sur toute une rangée de pointes appuyée sur la neige. Sur glace dure, il n'y a pas de couche de neige à comprimer : il faut passer aux pointes avant.",
    "q.l5#13.p" to "Sur une pente de neige molle, quel est l'avantage de la technique française ?",
    "q.l5#13.o0" to "Moins d'effort et plus de vitesse, donc adaptée aux longues pentes douces",
    "q.l5#13.o1" to "C'est plus sûr",
    "q.l5#13.o2" to "C'est mieux sur glace dure",
    "q.l5#13.o3" to "Cela évite le piolet",
    "q.l5#13.e" to "La neige molle offre une surface de contact suffisante : marcher à plat fatigue bien moins que de replanter les pointes sans cesse. Le choix technique suit la qualité de la neige.",
    "q.l5#14.p" to "En descente avec la technique française, quelle est la bonne posture ?",
    "q.l5#14.o0" to "Pointe de pied vers le bas, talon en premier, toute la semelle appuyée dans la neige",
    "q.l5#14.o1" to "Pointe de pied vers le haut",
    "q.l5#14.o2" to "De côté, en travers",
    "q.l5#14.o3" to "Uniquement sur les pointes avant",
    "q.l5#14.e" to "En descente, la clé de la technique française est de faire mordre toute la rangée de pointes en gardant le centre de gravité au-dessus de la plante. Le talon en premier permet de tasser une marche.",
    "q.l5#15.p" to "En traversée, que doit faire le pied du côté de la pente ?",
    "q.l5#15.o0" to "Mordre avec les pointes intérieures, cheville inclinée vers la pente",
    "q.l5#15.o1" to "Rester à plat",
    "q.l5#15.o2" to "Pointe de pied vers le bas",
    "q.l5#15.o3" to "Rester décollé",
    "q.l5#15.e" to "En traversée, les deux pieds doivent « mordre » la pente pour former un appui stable. Une cheville rigide fait seulement effleurer la surface aux pointes.",

    // ---------- l6 Usage du piolet et auto-assurage ----------
    "q.l6#10.p" to "En auto-assurage, sur quelle partie du corps le piolet doit-il être appuyé ?",
    "q.l6#10.o0" to "Entre l'épaule et la poitrine, en écrasant la tête du piolet de tout son poids",
    "q.l6#10.o1" to "Sur la hanche",
    "q.l6#10.o2" to "Sur le sommet du crâne",
    "q.l6#10.o3" to "Sur le côté de la jambe",
    "q.l6#10.e" to "Plus l'appui est haut, plus le poids se transforme en force de freinage. Appuyer sur la hanche fait relever la pointe : c'est presque inutile.",
    "q.l6#11.p" to "Que désigne la « prise d'auto-assurage » ?",
    "q.l6#11.o0" to "Le pouce d'un côté de la tête, la paume par-dessus, de façon à pouvoir basculer en freinage à tout instant",
    "q.l6#11.o1" to "Les deux mains au bout du manche",
    "q.l6#11.o2" to "Le piolet tenu d'une seule main",
    "q.l6#11.o3" to "La main dans la dragonne",
    "q.l6#11.e" to "Cette prise permet d'écraser le piolet sans changer de main au moment où l'on perd l'équilibre. Ce demi-seconde passé à changer de main, c'est souvent la distance de la glissade.",
    "q.l6#12.p" to "Quel est l'effet de la qualité de la neige sur le freinage ?",
    "q.l6#12.o0" to "La neige molle freine facilement, la neige dure et la glace ne freinent presque pas",
    "q.l6#12.o1" to "Plus c'est dur, mieux ça freine",
    "q.l6#12.o2" to "Cela ne dépend pas de la neige",
    "q.l6#12.o3" to "La neige humide glisse le plus",
    "q.l6#12.e" to "Le freinage repose sur la morsure de la pointe. Sur neige dure, elle ne fait qu'une rayure ; sur glace, elle est sans effet. C'est pourquoi une pente de glace se protège par une corde fixe, pas par le freinage.",
    "q.l6#13.p" to "Lors d'une glissade avec dragonne, quel est le risque principal ?",
    "q.l6#13.o0" to "Le piolet accroché tord le poignet, ou vous tire hors de contrôle",
    "q.l6#13.o1" to "La dragonne casse",
    "q.l6#13.o2" to "On perd le piolet",
    "q.l6#13.o3" to "C'est moins joli",
    "q.l6#13.e" to "La dragonne peut devenir un point d'accroche et mettre le poignet dans un angle anormal. En terrain technique, on la remplace le plus souvent par une longe de retenue.",
    "q.l6#14.p" to "Une fois le freinage réussi et l'arrêt obtenu, quelle est la première chose à faire ?",
    "q.l6#14.o0" to "Vérifier sa position et celle des partenaires, puis contrôler les blessures et le matériel",
    "q.l6#14.o1" to "Se relever tout de suite",
    "q.l6#14.o2" to "Continuer la descente",
    "q.l6#14.o3" to "Récupérer d'abord le piolet",
    "q.l6#14.e" to "S'arrêter ne veut pas dire être en sécurité : on peut être encore suspendu sur la pente, ou avoir entraîné un partenaire. Évaluer d'abord, agir ensuite.",
    "q.l6#15.p" to "Pourquoi « frapper violemment la glace avec la pointe » n'est-il pas un geste de freinage efficace ?",
    "q.l6#15.o0" to "Le freinage demande une pression continue, pas un choc : le piolet rebondit",
    "q.l6#15.o1" to "Parce que c'est trop bruyant",
    "q.l6#15.o2" to "Parce que le piolet s'abîme",
    "q.l6#15.o3" to "Parce que la glace est trop dure",
    "q.l6#15.e" to "Freiner, c'est « appuyer et glisser en ralentissant ». Un choc ne fait que faire sauter des éclats pendant que le corps continue à glisser.",

    // ---------- l22 Matériel technique, navigation et communication ----------
    "q.l22#10.p" to "Quelle est la différence fondamentale entre demi-cordes et corde simple ?",
    "q.l22#10.o0" to "Les demi-cordes s'assurent alternativement sur les points, ce qui réduit le tirage et le choc, mais la manœuvre est plus complexe",
    "q.l22#10.o1" to "Les demi-cordes sont moins chères",
    "q.l22#10.o2" to "Les demi-cordes sont plus légères",
    "q.l22#10.o3" to "Aucune différence",
    "q.l22#10.e" to "Les demi-cordes conviennent aux itinéraires sinueux où il faut réduire le tirage ; la corde simple est plus simple et plus directe. Le choix dépend de la forme de l'itinéraire, pas du « plus professionnel ».",
    "q.l22#11.p" to "Après un choc net, que faut-il faire du casque ?",
    "q.l22#11.o0" to "Le réformer et le remplacer, même s'il paraît intact",
    "q.l22#11.o1" to "Continuer à l'utiliser",
    "q.l22#11.o2" to "Le recoller",
    "q.l22#11.o3" to "Ne changer que la mousse",
    "q.l22#11.e" to "Le casque absorbe l'énergie par sa mousse : après un choc, la structure interne est atteinte sans que cela se voie. La protection au choc suivant chute fortement.",
    "q.l22#12.p" to "Dans l'usage des talkies-walkies au sein de l'équipe, qu'est-ce qui compte le plus ?",
    "q.l22#12.o0" to "Un canal fixe et des règles d'appel, des messages courts de position, pas de conversation pour occuper le canal",
    "q.l22#12.o1" to "Le volume au maximum",
    "q.l22#12.o2" to "Rester en communication permanente",
    "q.l22#12.o3" to "Que seul le chef en porte un",
    "q.l22#12.e" to "Le canal est une ressource partagée. Une conversation longue empêche l'appel d'urgence d'entrer et vide vite la batterie.",
    "q.l22#13.p" to "Quelle est la différence entre un communicateur satellite (type inReach) et un PLB ?",
    "q.l22#13.o0" to "Le satellite permet une communication bidirectionnelle, le PLB n'envoie qu'une alerte, réservée aux urgences",
    "q.l22#13.o1" to "Le PLB peut envoyer des SMS",
    "q.l22#13.o2" to "Les deux sont identiques",
    "q.l22#13.o3" to "Le satellite n'a pas besoin de piles",
    "q.l22#13.e" to "Le PLB, une fois enregistré, déclenche une réponse des secours et une fausse alerte coûte cher ; le satellite sert au contraire aux nouvelles rassurantes et à la coordination. Les deux ont des rôles différents.",
    "q.l22#14.p" to "Par grand froid, l'autonomie des batteries s'effondre. Quelle est la parade la plus utile ?",
    "q.l22#14.o0" to "Garder les batteries de rechange contre le corps et ranger l'appareil dans une poche intérieure quand on ne l'utilise pas",
    "q.l22#14.o1" to "En emporter plusieurs dans la poche extérieure du sac",
    "q.l22#14.o2" to "Couper toutes les fonctions",
    "q.l22#14.o3" to "Le chauffer avec une bouillotte",
    "q.l22#14.e" to "À −20 °C, une batterie lithium peut ne garder que la moitié de sa capacité. L'isoler vaut mieux qu'en emporter plus, car les rechanges se déchargent aussi.",
    "q.l22#15.p" to "Avant de partir, quelle est la bonne pratique pour la carte hors ligne ?",
    "q.l22#15.o0" to "Télécharger le paquet hors ligne de tout l'itinéraire et tester une fois la localisation en mode avion, à la maison",
    "q.l22#15.o1" to "Faire une capture d'écran de l'itinéraire",
    "q.l22#15.o2" to "Compter sur la carte en ligne en temps réel",
    "q.l22#15.o3" to "Imprimer une petite carte",
    "q.l22#15.e" to "« Téléchargé » et « utilisable hors ligne » sont deux choses différentes. Un essai à la maison révèle un téléchargement incomplet ou un problème de permissions.",

    // ---------- l23 Liste de matériel et système de portage ----------
    "q.l23#0.p" to "En construisant la liste de matériel, quelle catégorie faut-il valider en premier ?",
    "q.l23#0.o0" to "L'isolation et la protection, ainsi que le matériel technique",
    "q.l23#0.o1" to "L'appareil photo et la batterie externe",
    "q.l23#0.o2" to "Les encas et les condiments",
    "q.l23#0.o3" to "Des vêtements de rechange propres",
    "q.l23#0.e" to "L'ordre de la liste décide de ce qui manquera par mauvais temps. Isolation, protection et matériel technique sont du domaine du « s'il manque, il arrive quelque chose » ; le confort manquant n'est qu'un désagrément.",
    "q.l23#1.p" to "Quels volumes choisit-on habituellement pour le sac d'assaut et le sac de voyage ?",
    "q.l23#1.o0" to "35–50 litres / 90–120 litres",
    "q.l23#1.o1" to "20–30 litres / 50–60 litres",
    "q.l23#1.o2" to "60–70 litres / 60 litres",
    "q.l23#1.o3" to "Le plus gros possible",
    "q.l23#1.e" to "Le sac d'assaut porte la journée : couche chaude, vivres de course, eau, frontale, petite trousse de secours. Les gros bagages voyagent en portage, ils ne montent pas au camp d'altitude.",
    "q.l23#2.p" to "Où placer les objets lourds dans le sac ?",
    "q.l23#2.o0" to "Contre le dos, entre les omoplates (partie haute du dos)",
    "q.l23#2.o1" to "Tout en bas",
    "q.l23#2.o2" to "À l'extérieur",
    "q.l23#2.o3" to "À portée de main immédiate",
    "q.l23#2.e" to "Les charges lourdes contre le dos et assez haut gardent le centre de gravité près du corps, au-dessus des hanches : la marche est stable. En bas, le sac tire vers l'arrière et la ceinture est mal chargée, ce qui fait mal aux lombaires au bout de quelques heures.",
    "q.l23#3.p" to "Par quoi passe principalement le poids du sac ?",
    "q.l23#3.o0" to "Par la ceinture (environ 60 à 70 %), les bretelles servant surtout à plaquer le sac",
    "q.l23#3.o1" to "Par les bretelles",
    "q.l23#3.o2" to "Par la poitrine",
    "q.l23#3.o3" to "Par la sangle en bandoulière du cou",
    "q.l23#3.e" to "La ceinture transmet le poids au bassin, la partie du corps qui porte le mieux. Si les épaules tirent après un moment, c'est en général que la ceinture est mal serrée ou trop haute.",
    "q.l23#4.p" to "Quel poids de sac conseille-t-on le jour du sommet, en pourcentage du poids du corps ?",
    "q.l23#4.o0" to "15–20 %",
    "q.l23#4.o1" to "30–35 %",
    "q.l23#4.o2" to "40 %",
    "q.l23#4.o3" to "Sans limite",
    "q.l23#4.e" to "Pour 60 kg, cela fait environ 9 à 12 kg dans le sac d'assaut. Au-delà, la consommation d'oxygène et le risque de déséquilibre augmentent nettement à la montée.",
    "q.l23#5.p" to "À propos de l'étanchéité, quelle pratique est correcte ?",
    "q.l23#5.o0" to "Sac de couchage et doudoune chacun dans un sac étanche, l'électronique et les médicaments dans une couche supplémentaire",
    "q.l23#5.o1" to "Le sac est étanche, pas besoin de sacs intérieurs",
    "q.l23#5.o2" to "Un seul grand sac pour tout",
    "q.l23#5.o3" to "Envelopper le sac dans un sac-poubelle",
    "q.l23#5.e" to "Les coutures laissent passer l'eau. L'étanchéité en couches a un avantage : même si l'extérieur prend l'eau, le matériel essentiel reste sec, et la rupture d'un sac ne fait pas tout perdre.",
    "q.l23#6.p" to "Quels sont les trois objets qu'on oublie le plus et dont l'absence est la plus dangereuse ?",
    "q.l23#6.o0" to "La frontale avec piles de rechange, les gants de rechange, la trousse de secours",
    "q.l23#6.o1" to "Les lunettes de soleil, la crème solaire, le stick à lèvres",
    "q.l23#6.o2" to "La gourde, la boîte repas, les couverts",
    "q.l23#6.o3" to "L'appareil photo, le trépied, la carte mémoire de rechange",
    "q.l23#6.e" to "Les deux premiers renvoient à deux situations très fréquentes : ne pas être rentré avant la nuit et avoir les gants mouillés. Le dernier est ce que tout le monde croit que quelqu'un d'autre a pris.",
    "q.l23#7.p" to "Quels poids peut-on raisonnablement supprimer pour un camp d'altitude ?",
    "q.l23#7.o0" to "L'appareil photo de rechange et le trépied",
    "q.l23#7.o1" to "La troisième tenue de rechange",
    "q.l23#7.o2" to "La frontale et les piles de rechange",
    "q.l23#7.o3" to "La trousse de secours",
    "q.l23#7.e" to "On allège là où cela ne touche pas la sécurité. Frontale, trousse de secours et couche chaude sont intouchables ; l'appareil photo et les vêtements de rechange relèvent du confort.",
    "q.l23#8.p" to "Quelles qualités doit avoir une bonne liste de matériel ?",
    "q.l23#8.o0" to "Être groupée par situation d'usage, et non par ordre d'achat",
    "q.l23#8.o1" to "Distinguer l'indispensable de l'optionnel",
    "q.l23#8.o2" to "Varier selon la saison et l'étage d'altitude",
    "q.l23#8.o3" to "Être la plus longue possible",
    "q.l23#8.e" to "La valeur d'une liste, c'est de pouvoir être suivie même sous pression. Grouper par situation, marquer l'indispensable, ajuster selon l'altitude : voilà ce qui la rend utilisable. Trop longue, elle décourage et on ne l'utilise plus.",
    "q.l23#9.p" to "Remettez dans l'ordre les étapes du rangement du sac.",
    "q.l23#9.o0" to "Sac de couchage et doudoune en sac étanche, au fond du sac",
    "q.l23#9.o1" to "Les objets lourds (eau, réchaud, matériel technique) contre le dos, dans la partie haute",
    "q.l23#9.o2" to "La couche chaude et les vivres de la journée en haut",
    "q.l23#9.o3" to "Frontale et trousse de secours dans le rabat ou une poche latérale, accessibles à tout moment",
    "q.l23#9.e" to "On met d'abord ce qui ne sert pas mais doit être là, puis le lourd, enfin ce qui se prend à tout moment. Frontale et trousse doivent être accessibles sans vider le sac.",
    "q.l23#10.p" to "Une fois le sac sur le dos, quel est le bon ordre de réglage ?",
    "q.l23#10.o0" to "Attacher et serrer la ceinture",
    "q.l23#10.o1" to "Ajuster les bretelles pour qu'elles plaquent le sac",
    "q.l23#10.o2" to "Fermer la sangle de poitrine",
    "q.l23#10.o3" to "Se lever, marcher quelques pas et vérifier que le sac ne ballotte pas",
    "q.l23#10.e" to "Dans l'ordre inverse, le poids finit sur les épaules : d'abord la ceinture pour positionner, puis les bretelles, la sangle de poitrine servant seulement à empêcher les bretelles de glisser. Et il faut finir par une vérification en marchant.",
    "q.l23#11.p" to "Le sac d'assaut fait couramment 35–50 litres, le sac de voyage ______ litres.",
    "q.l23#11.a0" to "90–120",
    "q.l23#11.a1" to "90-120",
    "q.l23#11.a2" to "90~120",
    "q.l23#11.e" to "Le sac de voyage transporte le gros matériel de la route jusqu'au camp : il doit contenir sac de couchage, doudoune, chaussures et matériel technique, d'où 90–120 litres en général.",
    "q.l23#12.p" to "La ceinture supporte environ ______ % du poids du sac (donnez un nombre).",
    "q.l23#12.a0" to "60",
    "q.l23#12.a1" to "65",
    "q.l23#12.a2" to "70",
    "q.l23#12.a3" to "60–70",
    "q.l23#12.e" to "Environ 60 à 70 %. C'est aussi le critère pour savoir si le portage est correct : si les épaules peinent nettement, le problème vient presque toujours de la ceinture.",
    "q.l23#13.p" to "Associez chaque partie du sac à ce qu'elle doit contenir.",
    "q.l23#13.l0" to "Contre le dos, partie haute",
    "q.l23#13.l1" to "Fond du sac",
    "q.l23#13.l2" to "Rabat",
    "q.l23#13.l3" to "Poche latérale",
    "q.l23#13.r0" to "Eau, réchaud, matériel technique : les charges lourdes",
    "q.l23#13.r1" to "Sac de couchage et doudoune (en sac étanche)",
    "q.l23#13.r2" to "Couche chaude et vivres de la journée",
    "q.l23#13.r3" to "Frontale, petite trousse de secours, crème solaire",
    "q.l23#13.e" to "La place décide de l'accès et du centre de gravité. La frontale en poche latérale évite de fouiller à la nuit tombée ; le sac de couchage au fond parce qu'on ne l'utilise qu'une fois, au camp.",
    "q.l23#14.p" to "Le sac d'un partenaire est nettement plus lourd que le vôtre. Que faire de plus raisonnable ?",
    "q.l23#14.o0" to "Tout étaler sur place et redistribuer, en répartissant le matériel commun",
    "q.l23#14.o1" to "Le laisser porter, c'est son choix",
    "q.l23#14.o2" to "Lui en prendre la moitié, même si vous êtes alors en surcharge",
    "q.l23#14.o3" to "Se débarrasser du matériel commun",
    "q.l23#14.e" to "La vitesse du groupe est celle du plus lent, et la surcharge ralentit encore le plus lent. Le matériel commun (réchaud, cordes, trousse de secours) doit être réparti, et cela se règle avant le départ.",
    // ---------- l24 Système de couchage et matériel de camp ----------
    "q.l24#0.p" to "Quelle température faut-il regarder en choisissant un sac de couchage ?",
    "q.l24#0.o0" to "La température de confort",
    "q.l24#0.o1" to "La température limite",
    "q.l24#0.o2" to "La température minimale annoncée par la marque",
    "q.l24#0.o3" to "Le poids",
    "q.l24#0.e" to "La température de confort est celle à laquelle on dort toute la nuit sans avoir froid avec une couche de base ; la température limite n'est qu'une frontière de survie, « ne pas tomber en hypothermie ». Les deux diffèrent souvent de plus de 10 °C.",
    "q.l24#1.p" to "En altitude, comment fixer la température de confort du sac ?",
    "q.l24#1.o0" to "Au moins 5 °C en dessous de la température minimale attendue",
    "q.l24#1.o1" to "Égale à la température minimale attendue",
    "q.l24#1.o2" to "5 °C au-dessus de la température minimale attendue",
    "q.l24#1.o3" to "Peu importe",
    "q.l24#1.e" to "La marge se justifie : le métabolisme baisse la nuit, on mange moins, la tente peut givrer à l'intérieur. La sensation réelle est plus froide que la prévision.",
    "q.l24#2.p" to "De quoi un sac en duvet doit-il surtout être protégé ?",
    "q.l24#2.o0" to "De l'humidité : mouillé, il n'isole presque plus",
    "q.l24#2.o1" to "De l'écrasement",
    "q.l24#2.o2" to "Du soleil",
    "q.l24#2.o3" to "Du frottement",
    "q.l24#2.e" to "Le duvet mouillé perd son gonflant et donc une grande partie de son isolation, et il est très difficile à sécher vraiment sur le terrain. Un sac étanche est l'assurance la moins chère et la plus efficace.",
    "q.l24#3.p" to "Quel est l'usage courant des tapis de sol en camp d'altitude ?",
    "q.l24#3.o0" to "Superposer un tapis en mousse à cellules fermées et un matelas gonflable, en additionnant les valeurs isolantes",
    "q.l24#3.o1" to "Uniquement un matelas gonflable",
    "q.l24#3.o2" to "Uniquement un tapis aluminisé",
    "q.l24#3.o3" to "Dormir directement sur le sol de la tente",
    "q.l24#3.e" to "La mousse coupe la conduction avec le sol, le gonflable apporte le plan et le confort. La superposition sert aussi de secours : si le gonflable fuit, la mousse est encore là.",
    "q.l24#4.p" to "Le matelas gonflable fuit au camp. Que faire en premier ?",
    "q.l24#4.o0" to "Trouver la fuite et poser une rustine, en compensant avec le tapis en mousse",
    "q.l24#4.o1" to "Continuer à dormir, on verra demain",
    "q.l24#4.o2" to "Le dégonfler complètement",
    "q.l24#4.o3" to "Changer de tente",
    "q.l24#4.e" to "Une fuite ne fait qu'empirer, et la nuit sera plus froide. Rustine plus tapis en mousse comme secours, c'est le traitement standard : ne pariez pas qu'il tiendra jusqu'au matin.",
    "q.l24#5.p" to "Quelle est la bonne façon de stocker un sac de couchage entre deux sorties ?",
    "q.l24#5.o0" to "À plat ou suspendu, sans serrer, dans un endroit sec",
    "q.l24#5.o1" to "Toujours comprimé dans sa housse",
    "q.l24#5.o2" to "Sous vide",
    "q.l24#5.o3" to "Fermé dans un sac plastique",
    "q.l24#5.e" to "Une compression permanente fatigue la structure gonflante du duvet, et après quelques saisons l'isolation baisse nettement. Le stockage doit être lâche et sec.",
    "q.l24#6.p" to "Quelles pratiques améliorent réellement le sommeil en altitude ?",
    "q.l24#6.o0" to "Boire peu juste avant de dormir, mais assez sur l'ensemble de la journée",
    "q.l24#6.o1" to "Des bouchons d'oreille contre les bruits de la tente",
    "q.l24#6.o2" to "Mettre les vêtements mouillés dans le sac pour les sécher",
    "q.l24#6.o3" to "Manger très copieusement avant de dormir",
    "q.l24#6.e" to "Glisser des vêtements mouillés dans le sac retire beaucoup de chaleur et mouille le duvet : c'est l'erreur classique. Un repas trop lourd juste avant de dormir aggrave aussi l'inconfort nocturne.",
    "q.l24#7.p" to "De quoi se compose habituellement le système de couchage ?",
    "q.l24#7.o0" to "Le sac de couchage (avec sa chaussette intérieure)",
    "q.l24#7.o1" to "Le tapis de sol (mousse + gonflable)",
    "q.l24#7.o2" to "L'oreiller",
    "q.l24#7.o3" to "Le tapis de sol de la tente",
    "q.l24#7.e" to "Ces quatre éléments décident ensemble de la conduction avec le sol, de la convection d'air et du confort. S'il en manque un, on perd de la chaleur par ce côté toute la nuit.",
    "q.l24#8.p" to "Dans quel ordre installe-t-on la zone de couchage ?",
    "q.l24#8.o0" to "Nettoyer et aplanir le sol, retirer cailloux et objets pointus",
    "q.l24#8.o1" to "Poser le tapis de sol de la tente et le tapis en mousse",
    "q.l24#8.o2" to "Gonfler le matelas et le vérifier",
    "q.l24#8.o3" to "Déployer le sac de couchage en laissant la place de se retourner",
    "q.l24#8.e" to "Un ordre inversé oblige à recommencer : si le sol n'est pas propre, le matelas gonflable peut être percé dès la première nuit.",
    "q.l24#9.p" to "La température de confort du sac doit être au moins ______ °C en dessous de la minimale attendue.",
    "q.l24#9.a0" to "5",
    "q.l24#9.e" to "Une marge de 5 °C est la pratique courante. La nuit en altitude est plus froide que prévu, cette marge n'est pas excessive.",
    "q.l24#10.p" to "Un sac en duvet mouillé n'isole presque plus, il faut donc le ranger dans un sac ______.",
    "q.l24#10.a0" to "étanche",
    "q.l24#10.a1" to "de type dry bag",
    "q.l24#10.a2" to "imperméable",
    "q.l24#10.e" to "L'intérêt d'un sac étanche séparé, c'est l'isolement : même si l'extérieur prend l'eau, l'essentiel reste sec.",
    "q.l24#11.p" to "Associez chaque élément du couchage à son rôle principal.",
    "q.l24#11.l0" to "Tapis en mousse à cellules fermées",
    "q.l24#11.l1" to "Matelas gonflable",
    "q.l24#11.l2" to "Chaussette intérieure de sac",
    "q.l24#11.l3" to "Bouchons d'oreille",
    "q.l24#11.r0" to "Couper la conduction avec le sol, sans craindre les perforations",
    "q.l24#11.r1" to "Apporter un plan et du confort, superposable pour isoler davantage",
    "q.l24#11.r2" to "Limiter la salissure et l'humidité du sac",
    "q.l24#11.r3" to "Réduire la gêne sonore et faciliter l'endormissement",
    "q.l24#11.e" to "Quatre équipements pour quatre problèmes différents : conduction, plan, humidité, bruit. S'il en manque un, le problème revient par ce côté.",
    "q.l24#12.p" to "La tente est très givrée à l'intérieur. Que faire le matin ?",
    "q.l24#12.o0" to "Ranger d'abord le sac de couchage dans son sac étanche, puis secouer le givre de la paroi, pour ne pas mouiller le sac",
    "q.l24#12.o1" to "Plier d'abord la tente, en laissant le sac dehors",
    "q.l24#12.o2" to "Faire fondre le givre avec la chaleur du corps",
    "q.l24#12.o3" to "Ne rien faire, le soleil s'en occupe",
    "q.l24#12.e" to "Une tente givrée lâche des éclats de glace au moindre contact. Fermer d'abord le sac, c'est l'action clé pour éviter qu'une course entière se gâche en dix minutes le matin.",
    "q.l24#13.p" to "Pourquoi la qualité du sommeil se dégrade-t-elle en altitude ?",
    "q.l24#13.o0" to "L'hypoxie provoque une respiration périodique qui réveille sans cesse d'un sommeil léger",
    "q.l24#13.o1" to "La tente est trop dure",
    "q.l24#13.o2" to "Parce qu'on a trop peu marché dans la journée",
    "q.l24#13.o3" to "Parce que le temps ralentit avec l'altitude",
    "q.l24#13.e" to "C'est physiologique. On ne peut qu'améliorer les conditions (chaleur, silence, hydratation), pas s'imposer « huit heures de sommeil ».",
    "q.l24#14.p" to "L'équipe n'a qu'une tente de secours. À qui la donner en priorité ?",
    "q.l24#14.o0" to "À la personne la plus exposée à l'hypothermie ou présentant déjà des signes de mal des montagnes",
    "q.l24#14.o1" to "Au chef de cordée",
    "q.l24#14.o2" to "À la personne la plus en forme",
    "q.l24#14.o3" to "Tirer au sort",
    "q.l24#14.e" to "Les ressources de secours se répartissent selon le risque, pas selon l'ancienneté ni la forme. Cela doit être dit avant le départ, pour éviter une dispute nocturne.",

    // ---------- l7 Réagir à une chute et au freinage ----------
    "q.l7#10.p" to "Au moment où l'on perd l'équilibre, qu'est-ce qu'il faut protéger en premier ?",
    "q.l7#10.o0" to "La tête, tout en tournant le corps vers une position de freinage, sur le ventre ou sur le dos",
    "q.l7#10.o1" to "Le sac",
    "q.l7#10.o2" to "Le piolet",
    "q.l7#10.o3" to "Le téléphone",
    "q.l7#10.e" to "Le choc à la tête est l'une des principales causes de décès en glissade. La rotation, la protection de la tête et l'appui sur le piolet doivent commencer ensemble.",
    "q.l7#11.p" to "Quel cri est de règle quand on voit une chute de pierres ou une chute ?",
    "q.l7#11.o0" to "Crier « Pierre ! » ou « Chute ! », de façon brève et répétée",
    "q.l7#11.o1" to "Observer en silence",
    "q.l7#11.o2" to "Faire seulement un geste de la main",
    "q.l7#11.o3" to "Siffler",
    "q.l7#11.e" to "Le cri sert à faire lever la tête et à faire esquiver ceux d'en dessous. Le son compte plus que l'explication, et la brièveté répétée plus qu'un long discours.",
    "q.l7#12.p" to "En cordée, si l'un chute, que doivent faire les autres ?",
    "q.l7#12.o0" to "Frener immédiatement et maintenir la corde tendue, sans bouger en même temps",
    "q.l7#12.o1" to "Courir tous vers lui",
    "q.l7#12.o2" to "Lâcher la corde",
    "q.l7#12.o3" to "S'asseoir sur place",
    "q.l7#12.e" to "Bouger tous ensemble fait perdre la tension de la corde et le chuteur continue à glisser. La première étape du freinage, c'est de se stabiliser soi-même.",
    "q.l7#13.p" to "La chute s'est arrêtée et la corde reste tendue. Que faire ?",
    "q.l7#13.o0" to "Maintenir la tension, monter une protection d'abord, puis s'approcher pour voir",
    "q.l7#13.o1" to "Détendre la corde tout de suite",
    "q.l7#13.o2" to "Lui dire de remonter seul",
    "q.l7#13.o3" to "Couper la corde",
    "q.l7#13.e" to "Détendre la corde peut le faire glisser à nouveau. Il faut d'abord s'assurer soi-même, avant même de parler de secours.",
    "q.l7#14.p" to "Pourquoi les crampons peuvent-ils aggraver une chute ?",
    "q.l7#14.o0" to "Les pointes accrochent la neige ou les vêtements, ce qui provoque une torsion ou un arrêt brutal",
    "q.l7#14.o1" to "Parce qu'ils sont trop lourds",
    "q.l7#14.o2" to "Parce qu'ils se décrochent",
    "q.l7#14.o3" to "Parce qu'ils s'usent",
    "q.l7#14.e" to "Si un pied s'accroche brutalement, le corps pivote autour de l'articulation. C'est aussi pourquoi la position « pieds en bas, genoux fléchis » est importante.",
    "q.l7#15.p" to "Les accidents sont fréquents à la descente. Quelle en est la cause principale ?",
    "q.l7#15.o0" to "La fatigue, la baisse de vigilance et le relâchement mental du « c'est fait »",
    "q.l7#15.o1" to "La nuit",
    "q.l7#15.o2" to "L'usure du matériel",
    "q.l7#15.o3" to "Un itinéraire plus difficile",
    "q.l7#15.e" to "Le terrain de descente est souvent plus exposé, alors que la vigilance est au plus bas. Planifier la descente comme « l'autre moitié de la course » est indispensable.",

    // ---------- l8 Descente sur neige et glissades contrôlées ----------
    "q.l8#10.p" to "Quelle position est recommandée pour descendre une pente de neige dure assez raide ?",
    "q.l8#10.o0" to "Face à la pente, trois points d'appui, en descendant progressivement",
    "q.l8#10.o1" to "Face à l'extérieur, en marchant vite",
    "q.l8#10.o2" to "En glissade",
    "q.l8#10.o3" to "En sautant",
    "q.l8#10.e" to "Face à la pente, on peut freiner à tout instant avec le piolet. Face à l'extérieur ne convient qu'aux pentes douces ou à la neige molle.",
    "q.l8#11.p" to "En glissade contrôlée, comment préparer le freinage ?",
    "q.l8#11.o0" to "Garder le piolet en position de pouvoir être planté, prêt à s'arrêter",
    "q.l8#11.o1" to "Ranger le piolet dans le sac",
    "q.l8#11.o2" to "Écarter les deux mains",
    "q.l8#11.o3" to "Fermer les yeux",
    "q.l8#11.e" to "Le plaisir de la glissade repose sur « pouvoir s'arrêter à tout moment ». Avec une mauvaise position ou une neige trop dure, la glissade devient une chute.",
    "q.l8#12.p" to "Quels contrôles faut-il avoir faits avant de descendre en rappel ?",
    "q.l8#12.o0" to "Ancrage, nœuds, extrémités de corde, sens d'enfilage du descendeur, backup",
    "q.l8#12.o1" to "Seulement l'ancrage",
    "q.l8#12.o2" to "Seulement la longueur de corde",
    "q.l8#12.o3" to "Seulement les partenaires",
    "q.l8#12.e" to "Les accidents de rappel viennent presque tous de l'un de ces cinq points. Les énumérer à voix haute est plus fiable que « ça me paraît bon ».",
    "q.l8#13.p" to "En descente, où risque-t-on le plus d'être touché par une chute de pierres venue d'en haut ?",
    "q.l8#13.o0" to "Juste sous la corde",
    "q.l8#13.o1" to "À trois mètres sur le côté",
    "q.l8#13.o2" to "À côté de l'ancrage",
    "q.l8#13.o3" to "Derrière le replat",
    "q.l8#13.e" to "La verticale est le passage obligé des pierres. En descendant, on décale la trajectoire sur un côté et on traverse vite le bord du replat.",
    "q.l8#14.p" to "Après un rappel sur double, quelle est la cause la plus fréquente d'échec de récupération de la corde ?",
    "q.l8#14.o0" to "Un nœud en bout de corde, un coincement dans une fissure, ou deux brins de longueur inégale",
    "q.l8#14.o1" to "Une corde trop vieille",
    "q.l8#14.o2" to "Un descendeur trop petit",
    "q.l8#14.o3" to "Un ancrage trop haut",
    "q.l8#14.e" to "Avant de tirer, il faut vérifier qu'il n'y a pas de nœud en bout, pas d'accroche, et que les deux brins ont la même longueur. Si ça coince, changer l'angle avant de tirer fort.",
    "q.l8#15.p" to "À quoi sert le nœud en bout de corde en descente ?",
    "q.l8#15.o0" to "À empêcher le bout de sortir du descendeur et de provoquer une chute incontrôlée",
    "q.l8#15.o1" to "À faciliter le rangement de la corde",
    "q.l8#15.o2" to "À marquer la longueur",
    "q.l8#15.o3" to "À réduire l'usure",
    "q.l8#15.e" to "Si la corde est trop courte, le bout qui sort du descendeur signifie perdre le freinage instantanément. Ce nœud ne coûte presque rien et sépare pourtant beaucoup d'accidents de la banalité.",
    // ---------- l13 Mal aigu des montagnes (MAM) ----------
    "q.l13#14.p" to "Après combien de temps les symptômes du MAM apparaissent-ils en général après l'arrivée en altitude ?",
    "q.l13#14.o0" to "6–12 heures",
    "q.l13#14.o1" to "Immédiatement",
    "q.l13#14.o2" to "3 jours plus tard",
    "q.l13#14.o3" to "Une semaine plus tard",
    "q.l13#14.e" to "Cette fenêtre compte beaucoup : de l'après-midi du jour de montée jusqu'à la nuit, c'est la période d'observation, et c'est pourquoi on ne continue pas à monter.",
    "q.l13#15.p" to "Quel est le point qui distingue le mieux le MAM de l'HACE ?",
    "q.l13#15.o0" to "La présence d'une ataxie ou d'un trouble de la conscience",
    "q.l13#15.o1" to "L'intensité du mal de tête",
    "q.l13#15.o2" to "La présence de nausées",
    "q.l13#15.o3" to "La fréquence cardiaque",
    "q.l13#15.e" to "Mal de tête et nausées sont fréquents dans le MAM ; dès que la marche devient instable ou la conscience trouble, il faut traiter comme un HACE et descendre immédiatement.",
    "q.l13#16.p" to "Les symptômes du MAM ont disparu depuis 24 heures : peut-on continuer à monter ?",
    "q.l13#16.o0" to "Oui, mais en ralentissant le rythme et en surveillant de près",
    "q.l13#16.o1" to "Oui, sans restriction",
    "q.l13#16.o2" to "Non, plus jamais",
    "q.l13#16.o3" to "Il faut descendre de 1 000 m",
    "q.l13#16.e" to "La disparition complète des symptômes signale que l'acclimatation progresse. Mais le rythme doit être plus prudent, et toute récidive impose l'arrêt de la montée.",
    "q.l13#17.p" to "Quelle situation est facilement confondue avec un MAM ?",
    "q.l13#17.o0" to "La déshydratation, le rhume et le manque de sommeil",
    "q.l13#17.o1" to "Une fracture",
    "q.l13#17.o2" to "Une engelure",
    "q.l13#17.o3" to "La cécité des neiges",
    "q.l13#17.e" to "Les trois ont des symptômes qui recouvrent ceux du MAM. Ce qui s'améliore nettement après hydratation et repos n'est probablement pas un MAM ; ce qui ne s'améliore pas, ou s'aggrave, se traite comme un MAM.",
    "q.l13#18.p" to "Que faut-il savoir sur les antalgiques en cas de MAM ?",
    "q.l13#18.o0" to "Ils ne font que masquer les symptômes et ne justifient jamais de continuer à monter",
    "q.l13#18.o1" to "Une fois pris, on peut monter",
    "q.l13#18.o2" to "On peut augmenter la dose",
    "q.l13#18.o3" to "Ils sont totalement interdits",
    "q.l13#18.e" to "L'antalgique fait disparaître le signal, pas la maladie. Continuer à monter après avoir masqué les symptômes est la voie d'aggravation la plus courante.",
    "q.l13#19.p" to "Pourquoi le mal des montagnes est-il plus souvent manqué chez l'enfant et la personne âgée ?",
    "q.l13#19.o0" to "Parce qu'ils expriment mal leurs symptômes, et qu'un changement de comportement précède souvent la plainte",
    "q.l13#19.o1" to "Parce qu'ils sont moins sensibles",
    "q.l13#19.o2" to "Parce qu'ils s'acclimatent vite",
    "q.l13#19.o3" to "Parce qu'ils montent rarement",
    "q.l13#19.e" to "L'enfant se montre somnolent, pleure, ne mange plus ; la personne âgée peut seulement paraître « sans énergie ». Observer le comportement est plus fiable qu'attendre qu'ils en parlent.",

    // ---------- l14 Urgences : HACE et HAPE ----------
    "q.l14#12.p" to "Quel est le test le plus simple pour l'ataxie de l'HACE, sur place ?",
    "q.l14#12.o0" to "Marcher en ligne droite, talon contre pointe",
    "q.l14#12.o1" to "Tenir sur un pied",
    "q.l14#12.o2" to "Faire des squats",
    "q.l14#12.o3" to "Sauter sur place",
    "q.l14#12.e" to "L'incapacité à suivre une ligne droite, la démarche titubante, est un signe positif. Ce test ne demande aucun matériel, tout le monde peut le faire, et il convient au dépistage quotidien.",
    "q.l14#13.p" to "Comment la toux de l'HAPE évolue-t-elle en général ?",
    "q.l14#13.o0" to "D'une toux sèche vers des expectorations mousseuses, avec une chute brutale de la capacité d'effort",
    "q.l14#13.o1" to "D'une toux grasse vers une toux sèche",
    "q.l14#13.o2" to "Elle ne change pas",
    "q.l14#13.o3" to "Elle n'apparaît que la nuit",
    "q.l14#13.e" to "Expectorations mousseuses et dyspnée de repos forment le tableau typique de l'HAPE. Quand les crachats deviennent rose mousseux, l'état est souvent déjà sévère.",
    "q.l14#14.p" to "À quel moment de la course l'HAPE survient-il le plus souvent ?",
    "q.l14#14.o0" to "La première ou la deuxième nuit suivant la montée",
    "q.l14#14.o1" to "Avant le départ",
    "q.l14#14.o2" to "Pendant la descente",
    "q.l14#14.o3" to "Après le retour en plaine",
    "q.l14#14.e" to "C'est la nuit que l'hypoxie est la plus forte, et l'HAPE apparaît souvent la deuxième nuit. D'où la consigne d'être particulièrement attentif la première nuit.",
    "q.l14#15.p" to "En cas de suspicion d'HACE ou d'HAPE, quel est l'ordre des priorités ?",
    "q.l14#15.o0" to "Descendre immédiatement et donner de l'oxygène ; les médicaments viennent en complément",
    "q.l14#15.o1" to "Donner un médicament et observer",
    "q.l14#15.o2" to "Attendre une nuit de repos",
    "q.l14#15.o3" to "Attendre les secours",
    "q.l14#15.e" to "La descente est la seule mesure qui inverse la maladie de façon certaine. L'oxygène et les médicaments servent à « gagner le temps de la descente ».",
    "q.l14#16.p" to "Quel est le rôle du caisson hyperbare (sac Gamow) et quelle est sa limite ?",
    "q.l14#16.o0" to "Il simule une descente et fait gagner du temps, mais ne remplace pas une vraie descente",
    "q.l14#16.o1" to "Il guérit",
    "q.l14#16.o2" to "Il peut servir durablement",
    "q.l14#16.o3" to "Il ne sert qu'aux personnes conscientes",
    "q.l14#16.e" to "Le caisson est une « basse altitude mobile » : il faut quelqu'un pour le manœuvrer, cela consomme de l'énergie et la capacité est limitée. C'est une transition, pas un aboutissement.",
    "q.l14#17.p" to "Après un HAPE survenu pendant une course, que faire une fois la personne rétablie ?",
    "q.l14#17.o0" to "Arrêter toute montée pour cette course et organiser la descente",
    "q.l14#17.o1" to "Se reposer deux jours et remonter",
    "q.l14#17.o2" to "Changer d'itinéraire et continuer",
    "q.l14#17.o3" to "Continuer à demi-dose",
    "q.l14#17.e" to "Le risque de récidive de l'HAPE est élevé, et la nouvelle crise peut être plus rapide et plus grave. L'ascension s'arrête là.",
    "q.l14#18.p" to "Quelles manifestations concrètes couvre le « trouble de la conscience » de l'HACE ?",
    "q.l14#18.o0" to "Somnolence, réponses à côté, comportement anormal, hallucinations",
    "q.l14#18.o1" to "Uniquement le coma",
    "q.l14#18.o2" to "Uniquement le mal de tête",
    "q.l14#18.o3" to "Uniquement les nausées",
    "q.l14#18.e" to "Au début, cela peut n'être que « plus silencieux que d'habitude » ou « répéter les mêmes phrases ». Les partenaires le repèrent souvent avant la personne elle-même : d'où l'observation mutuelle.",
    "q.l14#19.p" to "Pourquoi HAPE et HACE peuvent-ils apparaître en même temps ?",
    "q.l14#19.o0" to "Parce que les deux sont des manifestations du mal d'altitude sévère et peuvent coexister sur le plan physiopathologique",
    "q.l14#19.o1" to "Parce qu'ils se traitent avec les mêmes médicaments",
    "q.l14#19.o2" to "Parce que les symptômes se ressemblent",
    "q.l14#19.o3" to "Ils n'apparaissent jamais ensemble",
    "q.l14#19.e" to "Les cas d'HACE associé à un HAPE sont fréquents en clinique. Le principe de traitement est le même : descendre, donner de l'oxygène, et médicaments si nécessaire.",

    // ---------- l15 Stratégies d'acclimatation ----------
    "q.l15#12.p" to "Pendant l'acclimatation, quel est le premier changement de l'organisme ?",
    "q.l15#12.o0" to "L'augmentation de la ventilation (respiration plus profonde et plus rapide)",
    "q.l15#12.o1" to "L'augmentation des globules rouges",
    "q.l15#12.o2" to "Le renforcement des muscles",
    "q.l15#12.o3" to "La baisse de la fréquence cardiaque",
    "q.l15#12.e" to "La ventilation augmente en quelques heures, alors que les globules rouges demandent des jours ou des semaines. C'est pourquoi « la première nuit » est la plus dure.",
    "q.l15#13.p" to "Pourquoi l'alcool et les sédatifs aggravent-ils le mal des montagnes ?",
    "q.l15#13.o0" to "Ils dépriment le drive respiratoire et accentuent l'hypoxie nocturne",
    "q.l15#13.o1" to "Parce qu'ils déshydratent",
    "q.l15#13.o2" to "Parce qu'ils irritent l'estomac",
    "q.l15#13.o3" to "Parce qu'ils perturbent le sommeil",
    "q.l15#13.e" to "En altitude, le drive respiratoire est déjà affaibli ; ces substances le dépriment encore. Et l'allure d'une personne ivre se confond facilement avec un début d'HACE.",
    "q.l15#14.p" to "La respiration périodique est fréquente la nuit en altitude. Quel en est le mécanisme ?",
    "q.l15#14.o0" to "L'hypoxie provoque une hyperventilation, puis une baisse du CO2 entraîne une apnée, et le cycle se répète",
    "q.l15#14.o1" to "Une obstruction des voies aériennes",
    "q.l15#14.o2" to "Un problème cardiaque",
    "q.l15#14.o3" to "Un effet psychologique",
    "q.l15#14.e" to "C'est physiologique, il n'y a pas à s'alarmer. Mais cela casse le sommeil, et c'est l'une des raisons de « dormir plus bas ».",
    "q.l15#15.p" to "Lequel de ces signes n'est PAS un signe précoce de mauvaise acclimatation ?",
    "q.l15#15.o0" to "Un appétit qui revient et un sommeil qui s'améliore",
    "q.l15#15.o1" to "Un mal de tête persistant",
    "q.l15#15.o2" to "Des réveils nocturnes répétés en apnée",
    "q.l15#15.o3" to "Une baisse de la capacité d'effort",
    "q.l15#15.e" to "« Manger, dormir, marcher » sont les trois signes d'une bonne acclimatation. Quand c'est l'inverse, il faut ralentir le rythme.",
    "q.l15#16.p" to "Quelle est la force des preuves concernant l'entraînement intermittent à l'hypoxie (préacclimatation) ?",
    "q.l15#16.o0" to "Il a un effet physiologique réel, mais ne remplace pas l'acclimatation sur place",
    "q.l15#16.o1" to "Il peut totalement remplacer l'acclimatation",
    "q.l15#16.o2" to "Il est totalement inefficace",
    "q.l15#16.o3" to "Il n'agit que chez les sportifs",
    "q.l15#16.e" to "La préacclimatation peut raccourcir un peu le temps d'acclimatation, mais la vitesse de montée et l'altitude de sommeil restent déterminantes. Ce n'est pas un raccourci.",
    "q.l15#17.p" to "Monter en altitude avec un rhume non guéri expose surtout à quoi ?",
    "q.l15#17.o0" to "Une inflammation des voies respiratoires qui augmente le risque d'HAPE",
    "q.l15#17.o1" to "Contaminer les partenaires",
    "q.l15#17.o2" to "Aggraver le rhume",
    "q.l15#17.o3" to "Rien du tout",
    "q.l15#17.e" to "C'est le point le plus souvent négligé. Prendre un rhume pour « un petit rien » et monter quand même est un facteur déclenchant classique d'HAPE.",
    "q.l15#18.p" to "Comment utiliser les « jours de repos » d'une période d'acclimatation ?",
    "q.l15#18.o0" to "Rester actif à la même altitude, rattraper du sommeil et de la nourriture, plutôt que rester allongé",
    "q.l15#18.o1" to "Rester totalement alité",
    "q.l15#18.o2" to "Continuer à monter",
    "q.l15#18.o3" to "Descendre pour se reposer",
    "q.l15#18.e" to "Une activité légère favorise la ventilation et la circulation. Rester allongé ralentit l'acclimatation et coupe l'appétit.",
    "q.l15#19.p" to "Pourquoi dit-on que « concevoir l'itinéraire est déjà de la prévention » ?",
    "q.l15#19.o0" to "Parce que la vitesse de montée et l'altitude de sommeil déterminent l'essentiel du risque : modifier l'itinéraire agit plus profondément que les médicaments",
    "q.l15#19.o1" to "Parce qu'un itinéraire est facile à écrire",
    "q.l15#19.o2" to "Parce que les médicaments coûtent cher",
    "q.l15#19.o3" to "Parce que le guide l'exige",
    "q.l15#19.e" to "Ceux qui inscrivent les jours d'acclimatation dans le plan ont rarement besoin de médicaments ; ceux qui remplissent le programme comptent souvent sur eux pour tenir.",

    // ---------- l16 Hypothermie et engelures ----------
    "q.l16#12.p" to "À quelle température centrale correspond à peu près une hypothermie « légère » ?",
    "q.l16#12.o0" to "35–32 °C, personne consciente avec frissons marqués",
    "q.l16#12.o1" to "38 °C",
    "q.l16#12.o2" to "Moins de 30 °C",
    "q.l16#12.o3" to "Moins de 28 °C",
    "q.l16#12.e" to "L'hypothermie légère se caractérise par les frissons et la conscience intacte. Les frissons signifient que le corps produit encore de la chaleur : c'est un signe qu'il y a encore de l'espoir.",
    "q.l16#13.p" to "Pourquoi l'arrêt des frissons est-il un signe dangereux ?",
    "q.l16#13.o0" to "Parce qu'il indique que le corps ne peut plus produire de chaleur pour se maintenir : on est passé en hypothermie modérée ou au-delà",
    "q.l16#13.o1" to "Parce que la personne est guérie",
    "q.l16#13.o2" to "Parce qu'elle s'est endormie",
    "q.l16#13.o3" to "Parce qu'elle est trop fatiguée",
    "q.l16#13.e" to "Passer de « frissons incontrôlables » à « plus de frissons » n'est pas une amélioration, c'est l'échec de la compensation. Il faut réchauffer et évacuer sans attendre.",
    "q.l16#14.p" to "Que faire face à une personne hypotherme et inconsciente ?",
    "q.l16#14.o0" to "Ne pas donner de boisson chaude : couvrir, isoler du sol et manipuler avec douceur",
    "q.l16#14.o1" to "Faire boire de l'eau sucrée chaude",
    "q.l16#14.o2" to "Frictionner les mains et les pieds",
    "q.l16#14.o3" to "La faire marcher",
    "q.l16#14.e" to "Quand la conscience est altérée, le réflexe de déglutition n'est pas fiable et faire boire provoque une fausse route. Une manipulation brutale peut déclencher un trouble du rythme cardiaque.",
    "q.l16#15.p" to "Pour réchauffer un membre gelé sur place, quelle température d'eau faut-il ?",
    "q.l16#15.o0" to "37–40 °C",
    "q.l16#15.o1" to "50–60 °C",
    "q.l16#15.o2" to "De l'eau glacée",
    "q.l16#15.o3" to "Le plus chaud possible",
    "q.l16#15.e" to "Cette température est proche de celle du corps : elle réchauffe sans brûler. Trop chaud provoque une lésion secondaire, trop froid ne sert à rien.",
    "q.l16#16.p" to "Pourquoi faut-il éviter un nouveau gel après le réchauffement d'une engelure ?",
    "q.l16#16.o0" to "Parce que les cycles gel-dégel répétés abîment les tissus bien plus qu'une seule engelure",
    "q.l16#16.o1" to "Parce que cela fait mal",
    "q.l16#16.o2" to "Parce que cela gonfle",
    "q.l16#16.o3" to "Parce que cela laisse des cicatrices",
    "q.l16#16.e" to "« Réchauffer puis regeler » est pire que « rester gelé ». Le réchauffement ne doit donc se faire que si l'on est sûr de ne plus avoir froid ensuite.",
    "q.l16#17.p" to "Que ne faut-il PAS faire sur une engelure, sur place ?",
    "q.l16#17.o0" to "Frictionner avec de la neige, exposer au feu, frotter à l'alcool",
    "q.l16#17.o1" to "Réchauffer à l'eau tiède",
    "q.l16#17.o2" to "Envelopper dans un pansement stérile",
    "q.l16#17.o3" to "Surélever le membre",
    "q.l16#17.e" to "Le frottement et la chaleur sèche aggravent les lésions. Sur place, on se limite à « eau tiède + protection + antalgique ».",
    "q.l16#18.p" to "Après une engelure des pieds, peut-on continuer à marcher ?",
    "q.l16#18.o0" to "Plutôt pas : la marche aggrave les lésions ; s'il est possible d'attendre les secours, on attend",
    "q.l16#18.o1" to "Oui, on peut marcher",
    "q.l16#18.o2" to "En courant, ça va plus vite",
    "q.l16#18.o3" to "Tant que ça ne fait pas mal, oui",
    "q.l16#18.e" to "Remettre en charge un pied réchauffé après engelure aggrave nettement les lésions. C'est pourquoi « quand réchauffer » demande un arbitrage.",
    "q.l16#19.p" to "Quelles sont les trois choses les plus importantes pour prévenir l'hypothermie ?",
    "q.l16#19.o0" to "Rester sec, couper le vent, manger et boire à intervalles réguliers",
    "q.l16#19.o1" to "Mettre beaucoup de vêtements",
    "q.l16#19.o2" to "Boire beaucoup d'eau chaude",
    "q.l16#19.o3" to "Marcher beaucoup",
    "q.l16#19.e" to "L'humidité, le vent et le manque d'énergie sont les trois portes d'entrée de l'hypothermie. La réponse est « couche respirante + couche coupe-vent + prises alimentaires régulières ».",

    // ---------- m09 Médicaments d'altitude et pharmacie d'urgence ----------
    "q.m09#12.p" to "Quelle est la posologie adulte habituelle de l'acétazolamide en prévention ?",
    "q.m09#12.o0" to "125 mg, deux fois par jour",
    "q.m09#12.o1" to "500 mg, une fois par jour",
    "q.m09#12.o2" to "1 000 mg, une fois par jour",
    "q.m09#12.o3" to "À la demande",
    "q.m09#12.e" to "125 mg deux fois par jour est la posologie retenue dans le manuel. C'est un médicament sur ordonnance : contre-indications et effets indésirables demandent une évaluation médicale.",
    "q.m09#13.p" to "Quels sont les effets indésirables fréquents de l'acétazolamide ?",
    "q.m09#13.o0" to "Fourmillements aux extrémités, altération du goût (surtout des boissons gazeuses), diurèse augmentée",
    "q.m09#13.o1" to "Somnolence",
    "q.m09#13.o2" to "Accélération du cœur",
    "q.m09#13.o3" to "Augmentation de la tension",
    "q.m09#13.e" to "Ces effets sont en général supportables, mais ils influent sur l'hydratation et le sommeil. Contre-indiqué en cas d'allergie aux sulfamides.",
    "q.m09#14.p" to "Quelle est la posologie habituelle de la dexaméthasone dans l'HACE ?",
    "q.m09#14.o0" to "4 mg toutes les 6 heures",
    "q.m09#14.o1" to "1 mg une fois par jour",
    "q.m09#14.o2" to "20 mg toutes les 12 heures",
    "q.m09#14.o3" to "Une prise unique à la demande",
    "q.m09#14.e" to "4 mg toutes les 6 heures est la posologie du manuel. C'est un traitement, il ne remplace pas la descente.",
    "q.m09#15.p" to "À quoi sert principalement la nifédipine ?",
    "q.m09#15.o0" to "À la prévention et au traitement de l'HAPE",
    "q.m09#15.o1" to "Au MAM",
    "q.m09#15.o2" to "Aux engelures",
    "q.m09#15.o3" to "À la déshydratation",
    "q.m09#15.e" to "La nifédipine agit en réduisant les résistances vasculaires pulmonaires, à raison de 20–30 mg toutes les 12 heures. Elle ne traite pas le MAM.",
    "q.m09#16.p" to "Les symptômes s'améliorent nettement après dexaméthasone. Que faire alors ?",
    "q.m09#16.o0" to "Descendre quand même : le médicament ne fait que gagner du temps",
    "q.m09#16.o1" to "Annuler la descente",
    "q.m09#16.o2" to "Continuer à monter",
    "q.m09#16.o3" to "Arrêter le traitement et observer",
    "q.m09#16.e" to "Le corticoïde masque les symptômes alors que la maladie continue d'évoluer. Continuer à monter après une amélioration est l'erreur d'appréciation la plus dangereuse.",
    "q.m09#17.p" to "Pourquoi « avoir les médicaments » ne veut-il pas dire « savoir les utiliser » ?",
    "q.m09#17.o0" to "Parce que posologie, indication et contre-indications demandent un avis médical, et qu'on ne se recommande pas des médicaments entre partenaires",
    "q.m09#17.o1" to "Parce que les médicaments périment",
    "q.m09#17.o2" to "Parce qu'ils pèsent lourd",
    "q.m09#17.o3" to "Parce que la notice est difficile à lire",
    "q.m09#17.e" to "Les pièges sont nombreux en altitude : allergie aux sulfamides, asthme, interactions. Prendre un médicament sans évaluation peut être plus risqué que bénéfique.",
    "q.m09#18.p" to "Quel est le rôle de l'aspirine en altitude ?",
    "q.m09#18.o0" to "Soulager le mal de tête : c'est un traitement symptomatique, sans effet sur l'évolution",
    "q.m09#18.o1" to "Prévenir l'HAPE",
    "q.m09#18.o2" to "Traiter l'HACE",
    "q.m09#18.o3" to "Augmenter la saturation",
    "q.m09#18.e" to "La place du traitement symptomatique doit être claire : il apporte du confort, mais n'autorise pas à continuer à monter.",
    "q.m09#19.p" to "Dans quel cas « aucun médicament, descendre au plus vite » est-il le choix le plus sûr ?",
    "q.m09#19.o0" to "Quand les symptômes sont sévères, que la cause est incertaine ou qu'il n'y a pas d'avis médical",
    "q.m09#19.o1" to "Dans tous les cas",
    "q.m09#19.o2" to "Uniquement en cas de symptômes légers",
    "q.m09#19.o3" to "Uniquement si la descente est facile",
    "q.m09#19.e" to "La descente est la seule mesure dont l'efficacité est certaine. Quand le médicament devient une devinette, descendre reste toujours la voie la plus sûre.",
    // ---------- l9 Nœuds de base ----------
    "q.l9#10.p" to "Quel est l'avantage du nœud de huit par rapport au nœud simple ?",
    "q.l9#10.o0" to "Il reste relativement facile à défaire après avoir été chargé, et sa structure est claire à vérifier",
    "q.l9#10.o1" to "Il est plus petit",
    "q.l9#10.o2" to "Il consomme moins de corde",
    "q.l9#10.o3" to "Il n'a pas besoin d'être terminé",
    "q.l9#10.e" to "Un nœud simple se bloque après avoir été chargé et devient très difficile à défaire sur le terrain. Le huit reste démontable sous charge, et c'est pourquoi il est devenu le nœud d'attache standard.",
    "q.l9#11.p" to "Où met-on habituellement un nœud d'arrêt ?",
    "q.l9#11.o0" to "À l'extrémité de la corde, pour empêcher le bout de sortir du matériel",
    "q.l9#11.o1" to "Au milieu de la corde",
    "q.l9#11.o2" to "Sur l'ancrage",
    "q.l9#11.o3" to "Sur le pontet du harnais",
    "q.l9#11.e" to "En descente, en rappel ou en second, le bout de corde peut sortir du matériel. Le nœud d'arrêt est la dernière sécurité mécanique.",
    "q.l9#12.p" to "À quoi sert principalement le nœud de pêcheur double ?",
    "q.l9#12.o0" to "À relier deux cordes de diamètre voisin",
    "q.l9#12.o1" to "À relier la corde au harnais",
    "q.l9#12.o2" to "À faire un nœud autobloquant",
    "q.l9#12.o3" to "À fixer un ancrage",
    "q.l9#12.e" to "Le pêcheur double est compact et passe bien, ce qui le rend adapté au cordage auxiliaire et aux sangles. Mais il est difficile à défaire après charge : il faut laisser des bouts suffisants.",
    "q.l9#13.p" to "Que faut-il faire après avoir terminé n'importe quel nœud ?",
    "q.l9#13.o0" to "Vérifier le cheminement et la longueur des bouts, puis le repasser point par point à voix haute",
    "q.l9#13.o1" to "Tirer une fois dessus",
    "q.l9#13.o2" to "Le photographier comme preuve",
    "q.l9#13.o3" to "Le cirer",
    "q.l9#13.e" to "« Bien fait » et « terminé » sont deux choses différentes. Un bout trop court glisse après mise en tension : la vérification doit devenir un geste systématique.",
    "q.l9#14.p" to "Pourquoi un nœud devient-il un point faible du système ?",
    "q.l9#14.o0" to "Parce que la corde s'y courbe, ce qui réduit nettement sa résistance",
    "q.l9#14.o1" to "Parce que le nœud est trop lourd",
    "q.l9#14.o2" to "À cause de la couleur",
    "q.l9#14.o3" to "Parce que le frottement chauffe",
    "q.l9#14.e" to "Dans un nœud, la corde se courbe et les efforts ne sont pas répartis. Il faut donc placer les nœuds en position peu chargée, et non sur les points porteurs critiques.",
    "q.l9#15.p" to "Quelle est la caractéristique la plus importante d'un nœud autobloquant (type prusik) ?",
    "q.l9#15.o0" to "Il mord la corde quand il est chargé et peut coulisser à vide : il sert de backup unidirectionnel",
    "q.l9#15.o1" to "Il se bloque définitivement",
    "q.l9#15.o2" to "Plus il est gros, mieux c'est",
    "q.l9#15.o3" to "Il ne sert qu'en descente",
    "q.l9#15.e" to "La valeur d'un autobloquant tient à son caractère unidirectionnel : il bloque sous charge et coulisse à vide. C'est ce qui permet de l'utiliser comme backup et pour remonter.",

    // ---------- l10 Harnais et système de cordée ----------
    "q.l10#10.p" to "Que désigne le « retournement des boucles » à vérifier après avoir mis le harnais ?",
    "q.l10#10.o0" to "Si les sangles de ceinture et de cuisses sont bien repassées dans les deux boucles, avec un bout suffisamment long",
    "q.l10#10.o1" to "Si le mousqueton est verrouillé",
    "q.l10#10.o2" to "Si le nœud est serré",
    "q.l10#10.o3" to "Si le casque est attaché",
    "q.l10#10.e" to "Un retournement incomplet est l'erreur de harnais la plus fréquente chez les débutants : ça « paraît » bien mis, et pourtant ça se desserre sous charge.",
    "q.l10#11.p" to "En progression encordée, que faire du bout de corde restant ?",
    "q.l10#11.o0" to "Le fixer dans le sac à corde ou sur soi, pour éviter qu'il traîne",
    "q.l10#11.o1" to "Le laisser traîner sur la neige",
    "q.l10#11.o2" to "Le déployer entièrement",
    "q.l10#11.o3" to "L'enrouler autour de la main",
    "q.l10#11.e" to "Un bout qui traîne accroche les crampons, les rochers et les ponts de neige, et devient un fil de croche-pied en cas de chute. Le ranger est une discipline de base.",
    "q.l10#12.p" to "Pourquoi la distance entre les membres d'une cordée ne doit-elle pas être trop courte ?",
    "q.l10#12.o0" to "Parce qu'un membre qui tombe dans une crevasse tire directement son partenaire, et qu'il n'y a plus d'espace pour le secours",
    "q.l10#12.o1" to "Parce qu'il n'y a pas assez de corde",
    "q.l10#12.o2" to "Parce qu'on avance moins vite",
    "q.l10#12.o3" to "Parce que c'est moins joli",
    "q.l10#12.e" to "La distance, c'est la distance de réaction. Trop courte, on lie deux personnes en un seul poids ; trop longue, le freinage et la communication deviennent difficiles.",
    "q.l10#13.p" to "En passant de la progression encordée à l'assurage en tête, qu'est-ce qu'il faut établir en premier ?",
    "q.l10#13.o0" to "Une relais fiable et son propre assurage",
    "q.l10#13.o1" to "La corde",
    "q.l10#13.o2" to "La communication",
    "q.l10#13.o3" to "La photo",
    "q.l10#13.e" to "La phase de transition est un point noir : on peut se retrouver « ni encordé ni assuré ». D'abord le relais, ensuite on défait la corde.",
    "q.l10#14.p" to "Dans quel cas l'encordement augmente-t-il le risque ?",
    "q.l10#14.o0" to "Sur une pente douce sans risque de chute, où nœuds et distance ajoutent des croche-pieds et des complications de communication",
    "q.l10#14.o1" to "Dans tous les cas",
    "q.l10#14.o2" to "Quand il y a des crevasses",
    "q.l10#14.o3" to "En descente",
    "q.l10#14.e" to "L'encordement est un outil contre les chutes et les crevasses. Employé hors de son domaine, il apporte plus de gêne que de bénéfice.",
    "q.l10#15.p" to "Que doit-on mettre au point avec toute l'équipe avant de s'encorder ?",
    "q.l10#15.o0" to "La distance, les consignes, l'ordre de passage en zone de crevasses et les signaux d'arrêt",
    "q.l10#15.o1" to "La marque du matériel",
    "q.l10#15.o2" to "La vitesse de progression",
    "q.l10#15.o3" to "Qui prend les photos",
    "q.l10#15.e" to "La fiabilité d'une cordée vient de la cohérence des réactions. Sans consignes communes, le premier imprévu devient une confusion.",

    // ---------- m06 Initiation à l'escalade technique ----------
    "q.m06#10.p" to "Dans les trois grands systèmes de l'escalade technique, que désigne « protection » ?",
    "q.m06#10.o0" to "Retenir la personne en cas de chute à l'aide d'ancrages et de cordes",
    "q.m06#10.o1" to "Marcher",
    "q.m06#10.o2" to "Les gestes d'escalade",
    "q.m06#10.o3" to "L'achat de matériel",
    "q.m06#10.e" to "Déplacement, protection et assurage forment une boucle : savoir marcher, savoir se protéger et savoir protéger les autres. S'il en manque un, ce n'est pas encore de l'escalade technique.",
    "q.m06#11.p" to "Pourquoi l'apprentissage technique commence-t-il souvent par le freinage, avant l'escalade ?",
    "q.m06#11.o0" to "Parce que la glissade est le danger le plus fréquent et que le freinage est la capacité de dernier recours",
    "q.m06#11.o1" to "Parce que grimper est plus difficile",
    "q.m06#11.o2" to "À cause de l'ordre du matériel",
    "q.m06#11.o3" to "Parce que le manuel est écrit ainsi",
    "q.m06#11.e" to "Savoir grimper sans savoir s'arrêter, c'est agrandir le risque. Freinage, encordement et protection sont des compétences « inutiles quand tout va bien » : elles doivent d'abord devenir des réflexes.",
    "q.m06#12.p" to "Quelle est la valeur de répéter des simulations en terrain sûr ?",
    "q.m06#12.o0" to "Transformer le geste en réflexe, pour qu'il reste du jugement disponible dans une situation réelle",
    "q.m06#12.o1" to "Pour passer le temps",
    "q.m06#12.o2" to "Pour les photos",
    "q.m06#12.o3" to "Pour connaître les prix du matériel",
    "q.m06#12.e" to "Sur le terrain, l'attention est accaparée par la météo, la fatigue et la peur. Seuls les gestes automatiques peuvent encore sortir au moment critique.",

    // ---------- m07 Relais : les bases ----------
    "q.m07#12.p" to "Dans quelle direction doit pointer le doigt du mousqueton ?",
    "q.m07#12.o0" to "Vers l'extérieur de la paroi, à l'écart du frottement et de l'axe de charge, pour éviter qu'une corde ou une arête ne l'ouvre",
    "q.m07#12.o1" to "Vers le haut",
    "q.m07#12.o2" to "Vers le bas",
    "q.m07#12.o3" to "Peu importe",
    "q.m07#12.e" to "Qu'un doigt soit ouvert par une force extérieure est un mode de défaillance réel. Mal orienté, c'est confier la fiabilité au hasard.",
    "q.m07#13.p" to "Quand une sangle relie deux ancrages, pourquoi ne doit-elle pas passer sur une arête vive ?",
    "q.m07#13.o0" to "Parce que l'arête coupe la sangle, dont la résistance chute fortement sous charge",
    "q.m07#13.o1" to "Parce que c'est laid",
    "q.m07#13.o2" to "Parce que ça glisse",
    "q.m07#13.o3" to "Parce que c'est trop court",
    "q.m07#13.e" to "Une petite entaille peut faire perdre la moitié de la résistance. Si le passage est inévitable, on ajoute une protection ou on prolonge par une chaîne.",
    "q.m07#14.p" to "Quel est l'angle habituel d'un broche à glace ?",
    "q.m07#14.o0" to "Légèrement vers le haut (environ 10–15 degrés), à l'opposé de la direction de charge",
    "q.m07#14.o1" to "Parfaitement horizontal",
    "q.m07#14.o2" to "Incliné vers le bas",
    "q.m07#14.o3" to "Peu importe",
    "q.m07#14.e" to "Une légère inclinaison vers le haut suit l'axe de charge et plaque le corps dans la glace au lieu de l'arracher. Si la glace est mauvaise, il faut une broche plus longue et plus inclinée.",
    "q.m07#15.p" to "Quand le relais ne dispose que d'un seul ancrage, que faut-il faire ?",
    "q.m07#15.o0" to "Ajouter un backup indépendant, ou choisir un terrain plus fiable",
    "q.m07#15.o1" to "L'utiliser tel quel",
    "q.m07#15.o2" to "Ajouter plusieurs mousquetons",
    "q.m07#15.o3" to "Raccourcir la corde",
    "q.m07#15.e" to "Le nombre de mousquetons ne fait pas la redondance. La redondance suppose que les causes de défaillance soient différentes.",

    // ---------- m08 Sommets objectifs : Gangshka et Haba ----------
    "q.m08#12.p" to "Pour des sommets de 5 000 m comme le Gangshka ou le Haba, qu'est-ce qu'il faut organiser en priorité ?",
    "q.m08#12.o0" to "Le rythme d'acclimatation et la fenêtre météo, plutôt que la difficulté technique",
    "q.m08#12.o1" to "L'achat du matériel",
    "q.m08#12.o2" to "Les points de vue pour les photos",
    "q.m08#12.o3" to "La répartition des rôles",
    "q.m08#12.e" to "En 5 000 m, la difficulté vient en général de l'altitude et de la météo, pas de la technique. Donner du temps à l'acclimatation rapporte plus que d'ajouter un geste technique.",
    "q.m08#13.p" to "À propos des permis et de l'obligation de guide, quelle est la bonne pratique ?",
    "q.m08#13.o0" to "Vérifier à l'avance la réglementation locale et respecter strictement l'obligation de guide ou de déclaration",
    "q.m08#13.o1" to "Demander sur place",
    "q.m08#13.o2" to "Contourner le poste de contrôle",
    "q.m08#13.o3" to "Demander à une connaissance d'arrondir les angles",
    "q.m08#13.e" to "Beaucoup de sommets de 5 000 m exigent une déclaration ou un guide. Une ascension sans permis annule à la fois le secours et l'assurance.",
    "q.m08#14.p" to "Quelle est la logique d'une progression du type « trois sommets, puis le principal » ?",
    "q.m08#14.o0" to "Valider d'abord l'acclimatation et la condition physique sur des itinéraires plus faciles, avant d'ajouter la difficulté technique",
    "q.m08#14.o1" to "Parce que c'est moins cher",
    "q.m08#14.o2" to "Parce que c'est plus proche",
    "q.m08#14.o3" to "Parce qu'il y a plus de monde",
    "q.m08#14.e" to "Progresser, c'est « n'ajouter qu'une variable à la fois ». Augmenter en même temps l'altitude et la difficulté technique rend impossible de comprendre ce qui a échoué.",
    "q.m08#15.p" to "Quelles informations sur l'itinéraire de retrait faut-il avoir vérifiées avant de partir ?",
    "q.m08#15.o0" to "Le chemin de descente, l'emplacement des camps de secours, le point médical le plus proche et les contacts",
    "q.m08#15.o1" to "Uniquement le chemin de descente",
    "q.m08#15.o2" to "Uniquement le point médical",
    "q.m08#15.o3" to "Aucune",
    "q.m08#15.e" to "Se retirer, ce n'est pas simplement « revenir en arrière ». Quand le temps se dégrade, le camp de secours le plus proche peut être la seule option viable.",
    // ---------- l11 Principes du relais : SRENE / EARNEST ----------
    "q.l11#12.p" to "Quand deux points de protection font un angle de 0° (parfaitement parallèles), quelle charge chacun supporte-t-il à peu près ?",
    "q.l11#12.o0" to "50 % chacun",
    "q.l11#12.o1" to "71 % chacun",
    "q.l11#12.o2" to "100 % chacun",
    "q.l11#12.o3" to "25 % chacun",
    "q.l11#12.e" to "Plus l'angle est petit, plus la charge se répartit également. C'est l'origine de la règle « garder l'angle des sangles sous 60° ».",
    "q.l11#13.p" to "Avec un angle de 60°, quelle charge chaque point supporte-t-il environ ?",
    "q.l11#13.o0" to "58 %",
    "q.l11#13.o1" to "50 %",
    "q.l11#13.o2" to "71 %",
    "q.l11#13.o3" to "100 %",
    "q.l11#13.e" to "De 50 % à 0°, à 58 % à 60°, puis 71 % à 90° : la charge grimpe vite avec l'angle.",
    "q.l11#14.p" to "Pourquoi faut-il « prétendre » le relais ?",
    "q.l11#14.o0" to "Pour qu'en cas de défaillance d'un point, il n'y ait pas d'allongement sous choc et que les autres restent en place",
    "q.l11#14.o1" to "Pour faire joli",
    "q.l11#14.o2" to "Pour économiser de la corde",
    "q.l11#14.o3" to "Pour faciliter le démontage",
    "q.l11#14.e" to "Un système mou produit un effort de choc au moment de la mise en tension, très supérieur à la charge statique. C'est tout le sens du principe « no extension ».",
    "q.l11#15.p" to "Trois points valent mieux que deux, à condition que…",
    "q.l11#15.o0" to "Les trois points soient indépendants, aient des causes de défaillance différentes et soient chargés équitablement",
    "q.l11#15.o1" to "Le nombre soit le plus grand possible",
    "q.l11#15.o2" to "Il suffise de les accrocher",
    "q.l11#15.o3" to "Ils soient reliés par une seule sangle",
    "q.l11#15.e" to "Relier trois points en chaîne avec une seule sangle fait qu'une défaillance entraîne tout le reste. Le nombre ne fait pas la redondance.",
    "q.l11#16.p" to "Dans quel axe un mousqueton de relais doit-il travailler ?",
    "q.l11#16.o0" to "Dans l'axe du grand côté, en évitant tout effort latéral sur le doigt",
    "q.l11#16.o1" to "En travers",
    "q.l11#16.o2" to "Dans n'importe quel axe",
    "q.l11#16.o3" to "Uniquement du côté du doigt",
    "q.l11#16.e" to "La résistance annoncée d'un mousqueton est celle du grand axe. En travers, elle peut tomber au tiers, et le risque d'ouverture du doigt augmente.",
    "q.l11#17.p" to "Sur un point naturel (gros arbre, bloc), qu'est-ce qu'il faut vérifier avant tout ?",
    "q.l11#17.o0" to "La stabilité de l'ensemble et l'état des racines, pas l'impression que « c'est gros »",
    "q.l11#17.o1" to "La couleur de l'écorce",
    "q.l11#17.o2" to "La hauteur",
    "q.l11#17.o3" to "Si la position est jolie",
    "q.l11#17.e" to "Des racines mortes, un tronc creux, un bloc descellé par le gel et le dégel peuvent paraître parfaitement normaux. Frapper avec le manche du piolet pour écouter le son est une vérification courante.",
    "q.l11#18.p" to "De quoi dépend surtout la fiabilité d'un point de protection dans la neige (piquet, ancre enfouie) ?",
    "q.l11#18.o0" to "De la résistance du manteau, de la qualité de l'enfouissement et des variations de température",
    "q.l11#18.o1" to "De la couleur de la corde",
    "q.l11#18.o2" to "De la profondeur d'enfouissement",
    "q.l11#18.o3" to "De la marque du piquet",
    "q.l11#18.e" to "Avec la fonte, tout le dispositif peut céder : c'est pourquoi on ne s'attarde pas sur un système d'ancrages de neige l'après-midi.",
    "q.l11#19.p" to "Quel risque concret y a-t-il à monter un relais lentement ?",
    "q.l11#19.o0" to "Le temps d'exposition s'allonge, et les risques de chute de pierres, de météo et d'hypothermie augmentent ensemble",
    "q.l11#19.o1" to "Aucun",
    "q.l11#19.o2" to "C'est juste une question d'efficacité",
    "q.l11#19.o3" to "Cela joue sur le moral",
    "q.l11#19.e" to "Un relais est un endroit exposé. Maîtriser la procédure ne sert pas seulement à aller vite : cela réduit le temps passé dans le danger.",

    // ---------- l12 Crevasses et progression encordée ----------
    "q.l12#12.p" to "Pour traverser une zone de crevasses dense, quelle organisation est correcte ?",
    "q.l12#12.o0" to "Passer un par un, avec une seule personne à la fois dans le tronçon à risque",
    "q.l12#12.o1" to "Toute l'équipe de front",
    "q.l12#12.o2" to "Traverser ensemble, rapidement",
    "q.l12#12.o3" to "Par deux, côte à côte",
    "q.l12#12.e" to "« Un à la fois » réduit la charge sur le système au minimum et laisse de l'espace de réaction pour le freinage et le secours.",
    "q.l12#13.p" to "Quel est l'espacement habituel des nœuds sur la corde ?",
    "q.l12#13.o0" to "Un nœud tous les 2–3 mètres",
    "q.l12#13.o1" to "Un nœud tous les 20 mètres",
    "q.l12#13.o2" to "Uniquement aux deux extrémités",
    "q.l12#13.o3" to "Aucun nœud",
    "q.l12#13.e" to "Des nœuds rapprochés ajoutent du frottement et des points de blocage en cas de chute, et réduisent la profondeur. En contrepartie, récupérer la corde est un peu plus pénible.",
    "q.l12#14.p" to "Un partenaire est tombé dans une crevasse et vous freinez. Quelle posture adopter ?",
    "q.l12#14.o0" to "Sur le ventre, centre de gravité abaissé, piolet planté dans la neige",
    "q.l12#14.o1" to "Debout",
    "q.l12#14.o2" to "Assis",
    "q.l12#14.o3" to "Sur le dos",
    "q.l12#14.e" to "La position ventrale transforme le poids du corps en frottement, et le piolet planté apporte un point d'appui supplémentaire. Debout, on est tiré au sol immédiatement.",
    "q.l12#15.p" to "Dans un sauvetage en système Z (3:1), quel ensemble de matériel est le plus critique ?",
    "q.l12#15.o0" to "Un nœud autobloquant + une poulie (ou un mousqueton) + un autobloquant de secours",
    "q.l12#15.o1" to "Deux piolets",
    "q.l12#15.o2" to "Un bloqueur + une échelle de corde",
    "q.l12#15.o3" to "Une pelle + une sonde",
    "q.l12#15.e" to "Le 3:1 repose sur « un palan + un autobloquant unidirectionnel ». Sans autobloquant, la corde tirée repart aussitôt.",
    "q.l12#16.p" to "Une fois la personne retenue, quelle est la première chose à faire ?",
    "q.l12#16.o0" to "Vérifier sa conscience et ses blessures, et lui faire établir son propre point fixe (nœud ou piolet)",
    "q.l12#16.o1" to "Commencer tout de suite à la remonter",
    "q.l12#16.o2" to "Lui dire de remonter seul",
    "q.l12#16.o3" to "Détendre la corde",
    "q.l12#16.e" to "Il faut d'abord que la personne « ne dépende plus de la corde », pour que le sauveteur ait les mains libres afin de monter le système. La remontée vient après.",
    "q.l12#17.p" to "Pourquoi la communication est-elle si importante dans un sauvetage en crevasse ?",
    "q.l12#17.o0" to "Parce que la longueur de corde et le bruit rendent la parole inaudible : il faut convenir à l'avance de signaux sur la corde",
    "q.l12#17.o1" to "Parce qu'on a envie de discuter",
    "q.l12#17.o2" to "Parce que les talkies-walkies coûtent cher",
    "q.l12#17.o3" to "Parce que les partenaires ont peur",
    "q.l12#17.e" to "La convention courante est : un coup « stop », deux coups « tire », trois coups « donne du mou ». Convenue à l'avance, elle évite la panique sur place.",
    "q.l12#18.p" to "En progression en zone de crevasses, dans quel état doit être la corde ?",
    "q.l12#18.o0" to "Légèrement tendue : ni traînante, ni trop molle",
    "q.l12#18.o1" to "Complètement au sol",
    "q.l12#18.o2" to "Parfaitement tendue",
    "q.l12#18.o3" to "Enroulée",
    "q.l12#18.e" to "Une corde qui traîne s'accroche dans les pointes ou les rochers ; trop tendue, elle tire le partenaire. Une tension modérée est la condition d'un freinage immédiat.",
    "q.l12#19.p" to "Pourquoi passe-t-on généralement le bas du glacier et la zone de séracs tôt le matin ?",
    "q.l12#19.o0" to "Parce que le froid rend les ponts de neige et la glace plus stables, et les chutes de glace plus rares",
    "q.l12#19.o1" to "Parce qu'il y a moins de monde",
    "q.l12#19.o2" to "Parce qu'il n'y a pas de soleil",
    "q.l12#19.o3" to "Par habitude des guides",
    "q.l12#19.e" to "La température est la variable clé de la stabilité. L'eau de fonte et les chutes de glace de l'après-midi augmentent nettement le risque.",

    // ---------- l18 Avalanches : bases et identification ----------
    "q.l18#13.p" to "Pourquoi les pentes sous le vent forment-elles plus facilement des couches dangereuses ?",
    "q.l18#13.o0" to "Parce que le vent y transporte la neige et l'accumule en corniches et en alternances de couches dures et molles",
    "q.l18#13.o1" to "Parce qu'il y fait plus froid",
    "q.l18#13.o2" to "Parce que la neige y est plus humide",
    "q.l18#13.o3" to "Parce qu'il y a moins de monde",
    "q.l18#13.e" to "Le transport par le vent crée sur la pente sous le vent une structure « neige molle sur couche dure » : une fois déclenchée, elle part souvent en plaque entière.",
    "q.l18#14.p" to "Sur l'échelle de risque d'avalanche de 1 à 5, que signifie le niveau 5 ?",
    "q.l18#14.o0" to "Risque extrême : de nombreuses avalanches naturelles se produisent, il faut éviter le terrain d'avalanche",
    "q.l18#14.o1" to "Risque faible",
    "q.l18#14.o2" to "Risque marqué",
    "q.l18#14.o3" to "Impossible à évaluer",
    "q.l18#14.e" to "Le niveau combine probabilité et ampleur. Le 5 ne veut pas dire « plus difficile à gravir » mais « il ne faut pas y aller ».",
    "q.l18#15.p" to "Avant de partir, quelles sont les trois informations à retenir en priorité du bulletin d'avalanche ?",
    "q.l18#15.o0" to "Le niveau de risque, le type de problème (plaque de vent, neige humide…) et les orientations et altitudes concernées",
    "q.l18#15.o1" to "La température, l'humidité, la pression",
    "q.l18#15.o2" to "Le vent, la nébulosité, la visibilité",
    "q.l18#15.o3" to "La longueur de l'itinéraire, le dénivelé, la durée",
    "q.l18#15.e" to "Le cœur du bulletin, c'est « où, quel problème, et à quel point c'est facile à déclencher ». Retenir le niveau sans l'orientation ne sert à rien.",
    "q.l18#16.p" to "Quand plusieurs personnes traversent un terrain d'avalanche, que faire ?",
    "q.l18#16.o0" to "Passer un par un, les autres restant en observation à un point sûr",
    "q.l18#16.o1" to "Traverser tous ensemble",
    "q.l18#16.o2" to "Traverser de front",
    "q.l18#16.o3" to "Traverser en courant",
    "q.l18#16.e" to "Un par un, c'est réduire au minimum le nombre de personnes potentiellement ensevelies. Traverser tous ensemble est la façon classique d'agrandir l'accident.",
    "q.l18#17.p" to "Dans quel ordre utilise-t-on le trépied de l'avalanche ?",
    "q.l18#17.o0" to "Recherche ARVA, puis localisation à la sonde, puis pelletage",
    "q.l18#17.o1" to "Pelleter, sonder, chercher",
    "q.l18#17.o2" to "Les trois en même temps",
    "q.l18#17.o3" to "Sonder, chercher, pelleter",
    "q.l18#17.e" to "Se tromper d'ordre fait perdre les minutes les plus précieuses. La recherche sert à « trouver », le pelletage à « atteindre ».",
    "q.l18#18.p" to "Quelle est la différence principale entre une avalanche de neige humide de printemps et une avalanche de neige sèche d'hiver ?",
    "q.l18#18.o0" to "L'avalanche humide est plus lente mais plus dense et plus puissante, et survient souvent l'après-midi",
    "q.l18#18.o1" to "L'avalanche humide est plus rapide",
    "q.l18#18.o2" to "L'avalanche humide n'ensevelit personne",
    "q.l18#18.o3" to "Aucune différence",
    "q.l18#18.e" to "Le déclenchement d'une avalanche humide est souvent lié à l'eau de fonte et au soleil, avec une fenêtre concentrée l'après-midi. La planification doit éviter cette plage.",
    "q.l18#19.p" to "Quelle est la valeur et quelle est la limite d'un test de manteau neigeux (fosse d'observation) ?",
    "q.l18#19.o0" to "Il donne une information locale, mais ne représente pas la pente entière",
    "q.l18#19.o1" to "Il permet de prévoir totalement les avalanches",
    "q.l18#19.o2" to "Il n'a aucune valeur",
    "q.l18#19.o3" to "Il ne sert qu'au printemps",
    "q.l18#19.e" to "Une fosse, c'est l'information d'un seul point. L'influence du terrain, de l'orientation et du vent porte sur une surface bien plus grande.",
    // ---------- m10 Météo de montagne et fenêtres météo ----------
    "q.m10#12.p" to "Quand l'humidité relative approche de la saturation, quelle en est la conséquence météo la plus directe ?",
    "q.m10#12.o0" to "La base des nuages descend, avec brouillard et précipitations probables",
    "q.m10#12.o1" to "La température monte",
    "q.m10#12.o2" to "Le vent faiblit",
    "q.m10#12.o3" to "La pression monte",
    "q.m10#12.e" to "Saturer, c'est le début de la condensation. En montagne, « la base des nuages qui descend vite » arrive souvent avant « la pluie qui commence ».",
    "q.m10#13.p" to "Qu'observe-t-on généralement après le passage d'un front froid ?",
    "q.m10#13.o0" to "Baisse de température, rotation du vent, amélioration de la visibilité",
    "q.m10#13.o1" to "Une hausse de température",
    "q.m10#13.o2" to "Une pluie continue",
    "q.m10#13.o3" to "Un vent qui faiblit",
    "q.m10#13.e" to "Après le front, c'est souvent « beau temps mais très froid et venteux ». C'est là que beaucoup d'équipes sous-estiment le refroidissement éolien parce que « le temps s'améliore ».",
    "q.m10#14.p" to "Quelle est la signification, pour l'alpiniste, des nuages orographiques collés au flanc ?",
    "q.m10#14.o0" to "Ils signalent un vent fort et une forte humidité : la crête est peut-être déjà infranchissable",
    "q.m10#14.o1" to "Ils sont juste jolis",
    "q.m10#14.o2" to "Ils indiquent un temps stable",
    "q.m10#14.o3" to "Ils n'ont aucun rapport avec le vent",
    "q.m10#14.e" to "Ces nuages rendent visibles le vent et l'humidité. Si on les voit défiler vite, on peut considérer que le vent sur la crête dépasse les limites.",
    "q.m10#15.p" to "Pourquoi les prévisions perdent-elles en fiabilité à mesure que l'échéance s'allonge ?",
    "q.m10#15.o0" to "Parce que l'atmosphère est un système chaotique et que l'erreur croît de façon exponentielle avec le temps",
    "q.m10#15.o1" to "Parce que les modèles sont mauvais",
    "q.m10#15.o2" to "Parce que les données sont incomplètes",
    "q.m10#15.o3" to "À cause de l'altitude",
    "q.m10#15.e" to "La tendance à trois jours est assez fiable, au-delà de sept jours ce n'est qu'une indication. L'itinéraire doit prévoir le temps d'« attendre la fenêtre ».",
    "q.m10#16.p" to "D'où vient principalement l'écart entre les données d'une station de montagne et l'altitude que vous visez ?",
    "q.m10#16.o0" to "Du dénivelé : température, vent et forme des précipitations diffèrent",
    "q.m10#16.o1" to "De l'erreur des instruments",
    "q.m10#16.o2" to "Du fuseau horaire",
    "q.m10#16.o3" to "De la latitude",
    "q.m10#16.e" to "La « petite pluie » d'une station de vallée peut être « grosse neige et grand vent » à 5 000 m. Lire une prévision, c'est toujours convertir l'altitude.",
    "q.m10#17.p" to "Vous voyez un éclair et entendez le tonnerre moins de 30 secondes après. Qu'est-ce que cela signifie ?",
    "q.m10#17.o0" to "L'orage est déjà tout proche : il faut quitter immédiatement le terrain exposé",
    "q.m10#17.o1" to "L'orage est loin",
    "q.m10#17.o2" to "On est en sécurité",
    "q.m10#17.o3" to "C'est une coïncidence",
    "q.m10#17.e" to "La différence entre vitesse de la lumière et du son permet d'estimer la distance. Plus l'intervalle est court, plus c'est proche ; « 30 secondes » est le seuil d'action courant.",
    "q.m10#18.p" to "Pourquoi programme-t-on souvent l'ascension au sommet au petit matin ?",
    "q.m10#18.o0" to "Parce que la neige regelée est plus stable et que les nuages et le vent sont généralement plus forts l'après-midi",
    "q.m10#18.o1" to "Pour les photos",
    "q.m10#18.o2" to "Parce qu'il y a moins de monde",
    "q.m10#18.o3" to "Par habitude des guides",
    "q.m10#18.e" to "La neige dure du petit matin et la fenêtre météo stable sont les raisons principales. En contrepartie, le froid et le manque de sommeil demandent une préparation.",
    "q.m10#19.p" to "Quand la fenêtre météo se rétrécit, qu'est-ce qu'il faut abandonner en premier ?",
    "q.m10#19.o0" to "L'objectif du sommet, pas la marge de sécurité",
    "q.m10#19.o1" to "La couche d'isolation",
    "q.m10#19.o2" to "Le matériel de rechange",
    "q.m10#19.o3" to "Les moyens de communication",
    "q.m10#19.e" to "Quand la fenêtre manque, ce qui se comprime, c'est la marge — et c'est précisément le début de l'accident. Le bon arbitrage est d'abandonner d'abord l'objectif.",

    // ---------- m11 Sommets objectifs : quatre 6 000 ----------
    "q.m11#12.p" to "Pourquoi le versant sud du Yuzhu Feng convient-il comme première marche vers 6 000 m ?",
    "q.m11#12.o0" to "Pente de neige relativement douce, accès possible, itinéraire classique",
    "q.m11#12.o1" to "Parce qu'il est le plus haut",
    "q.m11#12.o2" to "Parce que c'est le plus technique",
    "q.m11#12.o3" to "Parce qu'il y a peu de monde",
    "q.m11#12.e" to "L'objectif d'un « premier 6 000 » est de valider l'acclimatation et la condition physique, pas d'affronter la technique. Un itinéraire classique réduit les inconnues.",
    "q.m11#13.p" to "À quelle chaîne appartient le Qizi Feng ?",
    "q.m11#13.o0" to "La chaîne du Nyainqêntanglha",
    "q.m11#13.o1" to "Le Kunlun",
    "q.m11#13.o2" to "L'Himalaya",
    "q.m11#13.o3" to "Le Karakoram",
    "q.m11#13.e" to "Le Qizi se trouve à Damxung, au Tibet, dans le Nyainqêntanglha. La chaîne détermine le climat et la fenêtre saisonnière : c'est un critère de choix important.",
    "q.m11#14.p" to "À quoi sert le plus typiquement le Lobuche Est ?",
    "q.m11#14.o0" to "De transition et d'entraînement technique entre les 6 000 et les 8 000",
    "q.m11#14.o1" to "D'itinéraire touristique",
    "q.m11#14.o2" to "De domaine skiable",
    "q.m11#14.o3" to "De belvédère",
    "q.m11#14.e" to "Il est juste à côté du trek de l'Everest, avec une pente de neige assez raide et un accès facile : c'est un sommet de transition courant.",
    "q.m11#15.p" to "Quelle est la caractéristique technique de l'Island Peak (Imja Tse) ?",
    "q.m11#15.o0" to "Il demande de s'encorder et de progresser sur glacier : c'est le 6 000 technique classique",
    "q.m11#15.o1" to "Randonnée pure",
    "q.m11#15.o2" to "Simple marche sur neige",
    "q.m11#15.o3" to "Sans neige toute l'année",
    "q.m11#15.e" to "La « technique » de l'Island Peak tient au glacier et aux crevasses, pas aux parois rocheuses. Encordement et sauvetage en crevasse sont des compétences indispensables.",
    "q.m11#16.p" to "Pour choisir un 6 000, qu'est-ce qui compte plus que l'altitude ?",
    "q.m11#16.o0" to "La forme de l'itinéraire (neige, glacier, paroi) et la difficulté du retrait",
    "q.m11#16.o1" to "La beauté du nom",
    "q.m11#16.o2" to "La distance",
    "q.m11#16.o3" to "Le coût",
    "q.m11#16.e" to "À 6 100 m, une pente de neige et un itinéraire glaciaire ne demandent pas du tout la même chose : un ordre de grandeur d'écart. D'abord la forme, ensuite l'altitude.",
    "q.m11#17.p" to "Les exigences de permis et de guide pour un 6 000 sont en général, par rapport à un 5 000…",
    "q.m11#17.o0" to "Plus strictes : souvent une déclaration ou un guide obligatoire",
    "q.m11#17.o1" to "Plus souples",
    "q.m11#17.o2" to "Identiques",
    "q.m11#17.o3" to "Sans exigence",
    "q.m11#17.e" to "Plus l'altitude est élevée et l'itinéraire isolé, plus la réglementation est stricte. Vérifier les règles avant de partir évite bien des soucis au pied de la montagne.",
    "q.m11#18.p" to "Pourquoi faut-il « supposer la présence de crevasses » sur un 6 000 ?",
    "q.m11#18.o0" to "Parce qu'une fois couvertes de neige, on ne peut pas les voir : il faut s'encorder comme s'il y en avait",
    "q.m11#18.o1" to "Parce qu'il y en a forcément",
    "q.m11#18.o2" to "Parce que le guide l'exige",
    "q.m11#18.o3" to "Parce que l'assurance l'impose",
    "q.m11#18.e" to "« Invisible » ne veut pas dire « absent ». L'encordement coûte peu, une chute en crevasse coûte très cher.",
    "q.m11#19.p" to "L'acclimatation sur un 6 000 demande en général, par rapport à un 5 000…",
    "q.m11#19.o0" to "Plus de temps, parce que l'altitude de sommeil est plus haute et la récupération plus lente",
    "q.m11#19.o1" to "Moins de temps",
    "q.m11#19.o2" to "Le même temps",
    "q.m11#19.o3" to "Aucune acclimatation",
    "q.m11#19.e" to "À chaque palier d'altitude, il faut ajouter du temps d'acclimatation. Transposer directement le rythme d'un 5 000 à un 6 000 est une sous-estimation fréquente.",
    // ---------- l42 Principes de sécurité et gestion du risque ----------
    "q.l42#0.p" to "À quoi correspond le principe « quatre, trois, trois » ?",
    "q.l42#0.o0" to "Garder un tiers de marge en énergie, en temps et en matériel",
    "q.l42#0.o1" to "Trois personnes, trois heures, trois itinéraires",
    "q.l42#0.o2" to "Trois types de matériel, trois types de temps",
    "q.l42#0.o3" to "Trois contrôles, trois confirmations",
    "q.l42#0.e" to "Garder de la marge n'est pas de la prudence excessive : c'est inscrire l'imprévu au budget dès le départ. Tout consommer, c'est ne plus rien avoir quand quelque chose change.",
    "q.l42#1.p" to "Que désignent les « trois nouveautés » de la règle « trois nouveautés, on ne part pas » ?",
    "q.l42#1.o0" to "Itinéraire nouveau, partenaires nouveaux, matériel nouveau",
    "q.l42#1.o1" to "Saison nouvelle, météo nouvelle, altitude nouvelle",
    "q.l42#1.o2" to "Plan nouveau, budget nouveau, objectif nouveau",
    "q.l42#1.o3" to "Guide nouveau, voiture neuve, chaussures neuves",
    "q.l42#1.e" to "Chaque « nouveau » représente une inconnue. En empiler trois, c'est porter l'incertitude au maximum d'un coup.",
    "q.l42#2.p" to "Pourquoi « réduire d'abord les conséquences, ensuite la probabilité » ?",
    "q.l42#2.o0" to "Parce qu'une conséquence, une fois survenue, ne se rattrape pas, alors que la probabilité ne peut qu'être réduite, jamais supprimée",
    "q.l42#2.o1" to "Parce que réduire les conséquences coûte moins cher",
    "q.l42#2.o2" to "Parce que la probabilité n'est pas calculable",
    "q.l42#2.o3" to "Parce que l'ordre n'a pas d'importance",
    "q.l42#2.e" to "S'encorder, porter un casque, garder une voie de retrait : tout cela relève du « même si ça arrive, ce ne sera pas mortel ». C'est bien plus efficace que « faire attention ».",
    "q.l42#3.p" to "Quel est le bon ordre du principe STOP ?",
    "q.l42#3.o0" to "S'arrêter, réfléchir, observer, planifier",
    "q.l42#3.o1" to "Observer, s'arrêter, réfléchir, planifier",
    "q.l42#3.o2" to "Réfléchir, observer, s'arrêter, planifier",
    "q.l42#3.o3" to "S'arrêter, observer, réfléchir, planifier",
    "q.l42#3.e" to "Il faut d'abord s'arrêter pour pouvoir réfléchir et observer. Sous pression, le premier réflexe est souvent de continuer à marcher : c'est le réflexe par défaut le plus dangereux.",
    "q.l42#4.p" to "À quoi sert la rubrique « dans quels cas on renonce » dans un plan ?",
    "q.l42#4.o0" to "À sortir la décision de l'émotion et de la pression de l'objectif",
    "q.l42#4.o1" to "À faire un plan complet",
    "q.l42#4.o2" to "À passer un contrôle",
    "q.l42#4.o3" to "À rien de concret",
    "q.l42#4.e" to "En montagne, avec la fatigue et l'objectif en tête, décider d'abandonner sur le moment est presque impossible. Seules des conditions écrites à l'avance ont un vrai pouvoir.",
    "q.l42#5.p" to "Que ne comprend PAS les « trois clés d'un campement sûr » ?",
    "q.l42#5.o0" to "Camper le plus près possible de l'eau",
    "q.l42#5.o1" to "Éviter les pièges du terrain",
    "q.l42#5.o2" to "Garder une voie d'évacuation",
    "q.l42#5.o3" to "Regrouper le matériel critique",
    "q.l42#5.e" to "Camper collé à l'eau est le scénario typique d'une crue. Le cœur des trois clés, c'est « garantir d'abord de pouvoir sortir » ; le paysage et la commodité viennent après.",
    "q.l42#6.p" to "L'équipe vient de changer de matériel et part sur un itinéraire nouveau. Que dit la règle des trois nouveautés ?",
    "q.l42#6.o0" to "En retirer au moins une, ou baisser la difficulté jusqu'à pouvoir valider le matériel",
    "q.l42#6.o1" to "Ce n'est pas grave, du matériel neuf est plus sûr",
    "q.l42#6.o2" to "Accélérer le rythme",
    "q.l42#6.o3" to "Partir séparément",
    "q.l42#6.e" to "Le matériel neuf demande à être validé, l'itinéraire nouveau demande une adaptation. Les deux à la fois, et en cas de problème on ne sait pas d'où il vient.",
    "q.l42#7.p" to "À propos de « risque = conséquence × probabilité », quelle affirmation est juste ?",
    "q.l42#7.o0" to "Quand la conséquence est très grave, il faut la traiter même si la probabilité est faible",
    "q.l42#7.o1" to "Une probabilité faible permet d'ignorer",
    "q.l42#7.o2" to "Il suffit de regarder la probabilité",
    "q.l42#7.o3" to "Il suffit de regarder la conséquence",
    "q.l42#7.e" to "Tout l'intérêt du produit est là : quand la conséquence est assez grave, un événement très improbable doit quand même être couvert par le plan.",
    "q.l42#8.p" to "Quelles mesures réduisent la conséquence ?",
    "q.l42#8.o0" to "Progresser encordé, poser des points de protection",
    "q.l42#8.o1" to "Porter un casque",
    "q.l42#8.o2" to "Garder une voie d'évacuation",
    "q.l42#8.o3" to "Améliorer sa condition physique",
    "q.l42#8.e" to "Les trois premières réduisent le dommage « quand c'est arrivé ». Améliorer sa forme physique réduit la probabilité, pas la conséquence.",
    "q.l42#9.p" to "Quelles mesures réduisent la probabilité ?",
    "q.l42#9.o0" to "Consulter la météo et le bulletin d'avalanche",
    "q.l42#9.o1" to "S'acclimater à l'avance",
    "q.l42#9.o2" to "Choisir un itinéraire classique",
    "q.l42#9.o3" to "N'emporter qu'un seul talkie-walkie",
    "q.l42#9.e" to "Les trois premières réduisent les occasions de rencontrer le danger. La dernière n'a aucun rapport avec le risque, et affaiblit même la redondance.",
    "q.l42#10.p" to "Dans quelles situations faut-il déclencher STOP ?",
    "q.l42#10.o0" to "L'itinéraire ne correspond plus à la carte",
    "q.l42#10.o1" to "Le temps change nettement en peu de temps",
    "q.l42#10.o2" to "Quelqu'un est bizarre sans savoir l'expliquer",
    "q.l42#10.o3" to "Le programme a une demi-heure de retard",
    "q.l42#10.e" to "Les trois premières sont des signaux « l'information ne colle pas avec ce qu'on attendait ». Une demi-heure de retard est une fluctuation normale : on vérifie l'heure avant de décider.",
    "q.l42#11.p" to "Remettez dans l'ordre le traitement d'un risque.",
    "q.l42#11.o0" to "Identifier les facteurs de danger (terrain, météo, état des personnes)",
    "q.l42#11.o1" to "Évaluer la conséquence et la probabilité",
    "q.l42#11.o2" to "Choisir en priorité des mesures qui réduisent la conséquence",
    "q.l42#11.o3" to "Appliquer et fixer un moment de réexamen",
    "q.l42#11.e" to "La dernière étape est la plus oubliée : sans moment de réexamen, les mesures cessent d'agir sans que personne ne s'en aperçoive.",
    "q.l42#12.p" to "Remettez dans l'ordre le contrôle des trois nouveautés, avant le départ.",
    "q.l42#12.o0" to "Lister l'itinéraire, les partenaires et le matériel nouveaux de cette sortie",
    "q.l42#12.o1" to "Évaluer l'inconnue que chacun apporte",
    "q.l42#12.o2" to "Décider ce qu'on retire ou de combien on baisse la difficulté",
    "q.l42#12.o3" to "Inscrire la décision dans le plan et la communiquer à l'équipe",
    "q.l42#12.e" to "L'étape clé est la troisième : retirer quelque chose est une décision active, pas un « on fera attention ».",
    "q.l42#13.p" to "Le principe « quatre, trois, trois » garde ______ de marge en énergie, en temps et en matériel.",
    "q.l42#13.a0" to "un tiers",
    "q.l42#13.a1" to "1/3",
    "q.l42#13.a2" to "le tiers",
    "q.l42#13.e" to "Un tiers est une valeur empirique. Plus on consomme, moins il reste de marge quand quelque chose change.",
    "q.l42#14.p" to "Le risque est égal à la conséquence multipliée par la ______.",
    "q.l42#14.a0" to "probabilité",
    "q.l42#14.a1" to "possibilité",
    "q.l42#14.e" to "Décomposer le risque en deux facteurs permet de décider lequel réduire — en général la conséquence d'abord.",
    "q.l42#15.p" to "Dans « trois nouveautés, on ne part pas », on recommande de n'accumuler pas plus de ______ nouveauté(s) sur une même sortie.",
    "q.l42#15.a0" to "1",
    "q.l42#15.a1" to "une",
    "q.l42#15.a2" to "2",
    "q.l42#15.a3" to "deux",
    "q.l42#15.e" to "Une au maximum ; deux est déjà le plafond. Avec les trois, le plan repose sur trois inconnues.",
    "q.l42#16.p" to "Associez chaque mesure à son effet.",
    "q.l42#16.l0" to "Progresser encordé",
    "q.l42#16.l1" to "Consulter le bulletin d'avalanche",
    "q.l42#16.l2" to "Garder une voie d'évacuation",
    "q.l42#16.l3" to "S'acclimater à l'avance",
    "q.l42#16.r0" to "Réduit la conséquence (la chute n'est plus portée par un seul)",
    "q.l42#16.r1" to "Réduit la probabilité (éviter les jours à haut risque)",
    "q.l42#16.r2" to "Réduit la conséquence (on peut sortir si ça se dégrade)",
    "q.l42#16.r3" to "Réduit la probabilité (moins de mal d'altitude)",
    "q.l42#16.e" to "La différence entre les quatre tient à « changer le résultat » ou « changer la probabilité ». Une fois qu'on l'a clair, on sait où investir.",
    "q.l42#17.p" to "Associez chaque principe à son domaine d'application.",
    "q.l42#17.l0" to "Quatre, trois, trois",
    "q.l42#17.l1" to "Trois nouveautés, on ne part pas",
    "q.l42#17.l2" to "STOP",
    "q.l42#17.l3" to "Conséquence × probabilité",
    "q.l42#17.r0" to "Répartition du temps et des ressources",
    "q.l42#17.r1" to "Choix et coupes avant le départ",
    "q.l42#17.r2" to "Sur le terrain, quand on découvre soudain que ça ne colle pas",
    "q.l42#17.r3" to "Arbitrage entre plusieurs options",
    "q.l42#17.e" to "Les quatre outils servent à « planifier, préparer le départ, agir sur le terrain, arbitrer ». Ils ne se remplacent pas : ils interviennent à des étapes différentes.",

    // ---------- l26 Cartes, boussole et orientation en pleine nature ----------
    "q.l26#0.p" to "Sur une carte au 1:50 000, que représente 1 cm sur le terrain ?",
    "q.l26#0.o0" to "500 m",
    "q.l26#0.o1" to "50 m",
    "q.l26#0.o2" to "5 000 m",
    "q.l26#0.o3" to "5 m",
    "q.l26#0.e" to "On enlève deux zéros au dénominateur et on obtient « combien de mètres pour 1 cm » : 50 000 → 500 m. C'est le point de départ de tout calcul de lecture de carte.",
    "q.l26#1.p" to "Qu'appelle-t-on l'équidistance ?",
    "q.l26#1.o0" to "L'écart d'altitude entre deux courbes de niveau voisines",
    "q.l26#1.o1" to "La distance horizontale entre deux courbes de niveau",
    "q.l26#1.o2" to "L'écart d'altitude entre deux points de la carte",
    "q.l26#1.o3" to "La hauteur relative d'un sommet",
    "q.l26#1.e" to "Plus l'équidistance est grande, plus la carte est schématique. La pente se juge à la densité des courbes, le dénivelé à l'équidistance.",
    "q.l26#2.p" to "Comment définit-on la déclinaison magnétique ?",
    "q.l26#2.o0" to "L'angle entre le nord magnétique et le nord géographique",
    "q.l26#2.o1" to "L'angle entre la carte et le terrain",
    "q.l26#2.o2" to "L'inclinaison de la pente",
    "q.l26#2.o3" to "L'erreur de l'aiguille",
    "q.l26#2.e" to "La déclinaison varie selon la région et d'année en année. Les cartes indiquent en général la valeur de l'année d'édition et la variation annuelle : il faut la corriger avant d'utiliser la boussole.",
    "q.l26#3.p" to "Après avoir tracé l'azimut vers l'objectif sur la carte, comment progresse-t-on ?",
    "q.l26#3.o0" to "En suivant l'azimut tout en corrigeant sans cesse avec les courbes de niveau et les détails du terrain",
    "q.l26#3.o1" to "En marchant droit, les yeux rivés sur la boussole",
    "q.l26#3.o2" to "En ne suivant que la flèche du GPS",
    "q.l26#3.o3" to "En suivant le sentier le plus marqué, quel que soit l'azimut",
    "q.l26#3.e" to "L'azimut donne la direction générale, le terrain donne la position précise. En ne regardant que l'aiguille, on se retrouve sur la crête d'à côté, et cela coûte des heures.",
    "q.l26#4.p" to "Que signifie une densité plus forte des courbes de niveau ?",
    "q.l26#4.o0" to "Que la pente est plus raide",
    "q.l26#4.o1" to "Que la pente est plus douce",
    "q.l26#4.o2" to "Que l'altitude est plus élevée",
    "q.l26#4.o3" to "Que le terrain est plus plat",
    "q.l26#4.e" to "Courbes serrées signifie plus de dénivelé sur la même distance horizontale, donc plus de pente. C'est le plus utile pour voir « quelle montée fatigue le moins ».",
    "q.l26#5.p" to "Comment faut-il considérer le GPS en pleine nature ?",
    "q.l26#5.o0" to "Comme un accélérateur et une solution de secours, jamais comme le seul moyen de navigation",
    "q.l26#5.o1" to "Comme le seul moyen de navigation",
    "q.l26#5.o2" to "Comme un appareil de loisir",
    "q.l26#5.o3" to "Comme un moyen de secours",
    "q.l26#5.e" to "La batterie s'épuise, le froid la vide, l'eau entre, l'appareil tombe. La carte papier et la boussole sont la seule solution qui ne dépend pas d'une pile.",
    "q.l26#6.p" to "Que veut dire « orienter la carte » ?",
    "q.l26#6.o0" to "Faire coïncider le nord de la carte avec le nord réel",
    "q.l26#6.o1" to "Plier la carte sur la zone actuelle",
    "q.l26#6.o2" to "Mettre la carte dans une pochette étanche",
    "q.l26#6.o3" to "Repasser l'itinéraire au feutre épais",
    "q.l26#6.e" to "C'est seulement une fois la carte orientée que les crêtes et les vallées du dessin correspondent à ce qu'on a devant soi. Beaucoup de gens ne comprennent pas la carte parce qu'ils échouent dès cette première étape.",
    "q.l26#7.p" to "Sans visibilité, sur une pente de neige ou dans le brouillard, quelle est la méthode de localisation la plus fiable ?",
    "q.l26#7.o0" to "Azimut à la boussole plus estimation de la distance au temps ou au nombre de pas",
    "q.l26#7.o1" to "L'intuition",
    "q.l26#7.o2" to "Attendre que le ciel se lève",
    "q.l26#7.o3" to "Suivre les traces de quelqu'un d'autre",
    "q.l26#7.e" to "Avec une mauvaise visibilité, les repères du terrain disparaissent et il ne reste que « l'angle plus la distance ». Compter les pas exige d'avoir étalonné sa longueur de pas, sinon l'erreur est énorme.",
    "q.l26#8.p" to "Que comprend au minimum un équipement de navigation indépendant de l'électronique ?",
    "q.l26#8.o0" to "Une carte topographique papier de la zone",
    "q.l26#8.o1" to "Une boussole",
    "q.l26#8.o2" to "Un altimètre ou une montre",
    "q.l26#8.o3" to "Des piles de rechange",
    "q.l26#8.e" to "Le quatrième élément sert aux appareils électroniques et ne fait pas partie de l'ensemble « sans électronique ». Carte, boussole et altimètre suffisent pour se situer et progresser.",
    "q.l26#9.p" to "Quelles situations rendent la trace GPS peu fiable ?",
    "q.l26#9.o0" to "Les gorges et les parois qui masquent le signal",
    "q.l26#9.o1" to "Le froid qui fait chuter la batterie d'un coup",
    "q.l26#9.o2" to "S'arrêter sous une corniche",
    "q.l26#9.o3" to "Un itinéraire très rectiligne",
    "q.l26#9.e" to "Les trois premières provoquent une dérive de la position ou une coupure d'alimentation. Que la trace soit droite n'a aucun rapport avec le signal, mais un tracé rectiligne pousse souvent à dépendre de l'appareil et à regarder moins le terrain.",
    "q.l26#10.p" to "Quels indices utilise-t-on en lisant la carte pour confirmer sa position ?",
    "q.l26#10.o0" to "L'orientation de la pente sur laquelle on se trouve",
    "q.l26#10.o1" to "La forme des courbes de niveau sous ses pieds (crête, vallée, col)",
    "q.l26#10.o2" to "La relation d'azimut avec des repères évidents",
    "q.l26#10.o3" to "La forme des nuages",
    "q.l26#10.e" to "Orientation de la pente, forme des courbes et azimut par rapport à des repères nets : en croisant les trois, on se situe. La forme des nuages sert à la météo, pas à l'orientation.",
    "q.l26#11.p" to "Remettez dans l'ordre une orientation complète à l'azimut.",
    "q.l26#11.o0" to "Orienter la carte en alignant son nord sur le nord réel",
    "q.l26#11.o1" to "Confirmer la position actuelle",
    "q.l26#11.o2" to "Mesurer l'azimut vers le point visé",
    "q.l26#11.o3" to "Progresser sur cet azimut en vérifiant le terrain",
    "q.l26#11.e" to "L'ordre ne se saute pas : avec une position douteuse, l'azimut mesuré ne veut rien dire ; sans vérifier le terrain, on suit une « droite théorique ».",
    "q.l26#12.p" to "Sur un terrain sans repères nets, quel est l'ordre pour suivre un azimut ?",
    "q.l26#12.o0" to "Choisir un point intermédiaire éloigné",
    "q.l26#12.o1" to "Aller jusqu'à ce point et reconfirmer la position",
    "q.l26#12.o2" to "Choisir le point intermédiaire suivant",
    "q.l26#12.o3" to "À l'approche de l'objectif, le confirmer avec des détails du terrain",
    "q.l26#12.e" to "Une longue ligne droite est presque impossible à tenir en terrain ondulé. Découper en points intermédiaires est la seule façon de faire atterrir « l'angle » dans le terrain réel.",
    "q.l26#13.p" to "L'angle entre le nord magnétique et le nord géographique s'appelle la ______ magnétique.",
    "q.l26#13.a0" to "déclinaison",
    "q.l26#13.a1" to "déclinaison magnétique",
    "q.l26#13.a2" to "declination",
    "q.l26#13.e" to "La déclinaison doit être corrigée avec la valeur de l'année indiquée sur la carte ; sinon, on peut dériver de plusieurs dizaines de mètres par kilomètre.",
    "q.l26#14.p" to "Sur une carte au 1:25 000, 1 cm représente ______ m sur le terrain.",
    "q.l26#14.a0" to "250",
    "q.l26#14.e" to "On enlève deux zéros au dénominateur : 25 000 → 250 m. Plus l'échelle est grande, plus il y a de détail et moins la feuille couvre de surface.",
    "q.l26#15.p" to "Avec une équidistance de 10 m, pour aller de la courbe 3 200 m à la courbe 3 280 m, il faut franchir ______ courbes de niveau (sans compter celle du départ).",
    "q.l26#15.a0" to "8",
    "q.l26#15.e" to "(3 280 − 3 200) ÷ 10 = 8. Ce calcul sert tous les jours à estimer le dénivelé et la durée.",
    "q.l26#16.p" to "Associez chaque forme de terrain à sa représentation sur la carte.",
    "q.l26#16.l0" to "Crête",
    "q.l26#16.l1" to "Vallée",
    "q.l26#16.l2" to "Col",
    "q.l26#16.l3" to "Falaise",
    "q.l26#16.r0" to "Les courbes de niveau pointent vers le bas",
    "q.l26#16.r1" to "Les courbes de niveau pointent vers le haut",
    "q.l26#16.r2" to "Point bas entre deux ensembles de courbes, avec de la hauteur des deux côtés",
    "q.l26#16.r3" to "Plusieurs courbes superposées ou très serrées",
    "q.l26#16.e" to "« Ça pointe vers le bas, c'est une crête ; ça pointe vers le haut, c'est une vallée » est la règle la plus utile. Le col est un terrain clé pour le choix d'itinéraire : c'est souvent le passage le plus bas.",
    "q.l26#17.p" to "Associez chaque outil de navigation à sa limite.",
    "q.l26#17.l0" to "GPS",
    "q.l26#17.l1" to "Boussole",
    "q.l26#17.l2" to "Altimètre",
    "q.l26#17.l3" to "Carte papier",
    "q.l26#17.r0" to "Dépend de la batterie et du signal ; défaille en gorge et par grand froid",
    "q.l26#17.r1" to "Sensible aux objets ferromagnétiques proches, et exige de corriger la déclinaison",
    "q.l26#17.r2" to "Ne donne que l'altitude, pas la position dans le plan",
    "q.l26#17.r3" to "Demande une mise à jour et peut ne pas couvrir les itinéraires récents",
    "q.l26#17.e" to "Chaque outil a son mode de défaillance : la navigation se fait donc en combinant. Quand l'un lâche, l'autre apporte encore une contrainte utile.",
    // ---------- l27 Choix et aménagement du camp ----------
    "q.l27#0.p" to "En choisissant l'emplacement du camp, quelle est la priorité absolue ?",
    "q.l27#0.o0" to "Éviter les chutes de pierres, les couloirs d'avalanche et la ligne de crue",
    "q.l27#0.o1" to "La beauté du paysage",
    "q.l27#0.o2" to "La proximité de l'itinéraire",
    "q.l27#0.o3" to "Un sol le plus plat possible",
    "q.l27#0.e" to "Sécurité, eau, plat, confort : dans cet ordre. Inverser cet ordre, c'est planter la tente dans une zone de dépôt d'avalanche.",
    "q.l27#1.p" to "Sur une pente de neige, quelle est la première chose à faire avant de monter la tente ?",
    "q.l27#1.o0" to "Tasser la neige et creuser une plateforme horizontale",
    "q.l27#1.o1" to "Déplier la tente directement",
    "q.l27#1.o2" to "Mettre l'eau à chauffer",
    "q.l27#1.o3" to "Tendre d'abord les haubans",
    "q.l27#1.e" to "Une surface irrégulière fait glisser toute la nuit ; sans plateforme, la tente subit des efforts inégaux et se déforme au premier coup de vent.",
    "q.l27#2.p" to "Quelle distance raisonnable entre le camp et le point d'eau ?",
    "q.l27#2.o0" to "Un accès commode, mais camper à plus de 60 m de l'eau",
    "q.l27#2.o1" to "Collé à la rive",
    "q.l27#2.o2" to "Dans l'eau",
    "q.l27#2.o3" to "Le plus loin possible, deux kilomètres",
    "q.l27#2.e" to "60 m est la distance sanitaire courante : elle limite la pollution de l'eau et évite les crues nocturnes. Camper au bord de l'eau est le scénario typique d'un accident de crue.",
    "q.l27#3.p" to "Dans un camp de base, comment disposer la zone de cuisine et la zone de couchage ?",
    "q.l27#3.o0" to "Les séparer, la cuisine loin de la zone de couchage",
    "q.l27#3.o1" to "Les regrouper, c'est plus pratique",
    "q.l27#3.o2" to "La cuisine dans la tente",
    "q.l27#3.o3" to "Peu importe",
    "q.l27#3.e" to "Trois raisons de séparer : le risque de flamme nue, le monoxyde de carbone et les odeurs qui attirent les animaux. Les coller fait gagner dix mètres de marche et peut coûter la tente entière.",
    "q.l27#4.p" to "Comment fixer une tente sur de la glace ou de la neige dure ?",
    "q.l27#4.o0" to "Avec des broches à glace, des ancres à neige ou des sacs enfouis ; pas seulement des pierres posées dessus",
    "q.l27#4.o1" to "Des pierres posées dessus suffisent",
    "q.l27#4.o2" to "Attacher les haubans aux bâtons",
    "q.l27#4.o3" to "Pas besoin de fixer",
    "q.l27#4.e" to "Sur la glace, il n'y a pas de matériau meuble à poser dessus, et le vent arrache la tente avec les piquets. Broches et ancres à neige sont les seuls points efficaces.",
    "q.l27#5.p" to "En quittant le camp, que faire des traces de feu ?",
    "q.l27#5.o0" to "Les noyer d'eau, disperser les cendres et remettre le site en état",
    "q.l27#5.o1" to "Recouvrir de terre",
    "q.l27#5.o2" to "Laisser pour la prochaine fois",
    "q.l27#5.o3" to "Ne rien faire",
    "q.l27#5.e" to "Disperser les cendres aide le site à retrouver son aspect naturel. Un cercle de feu reste très longtemps et incite les suivants à faire du feu au même endroit.",
    "q.l27#6.p" to "Par grand vent, par où une tente lâche-t-elle le plus souvent ?",
    "q.l27#6.o0" to "Par les haubans et les points d'ancrage : la charge inégale arrache un côté",
    "q.l27#6.o1" to "Par le tissu",
    "q.l27#6.o2" to "Par la fermeture éclair",
    "q.l27#6.o3" to "Par le tapis de sol",
    "q.l27#6.e" to "L'angle des haubans et la qualité des ancrages déterminent la résistance au vent. La plupart des tentes détruites n'ont pas le tissu déchiré : c'est un point d'ancrage qui cède d'abord.",
    "q.l27#7.p" to "Il a neigé la nuit et la tente est à moitié ensevelie au matin. Que faire ?",
    "q.l27#7.o0" to "Dégager d'abord les aérations et la porte, puis la neige autour",
    "q.l27#7.o1" to "Prendre des photos d'abord",
    "q.l27#7.o2" to "Replier la tente directement",
    "q.l27#7.o3" to "Attendre que la neige s'arrête",
    "q.l27#7.e" to "Une aération bouchée, c'est un risque de monoxyde de carbone et d'hypoxie. D'abord la ventilation, le reste ensuite.",
    "q.l27#8.p" to "Lesquels de ces emplacements sont des « pièges du terrain » où il ne faut pas camper ?",
    "q.l27#8.o0" to "Le pied d'une zone de dépôt d'avalanche",
    "q.l27#8.o1" to "Les lits de rivière asséchés et les ravines",
    "q.l27#8.o2" to "Les cols et passages exposés d'une crête",
    "q.l27#8.o3" to "Une clairière plate en forêt",
    "q.l27#8.e" to "Les trois premiers sont des positions typiquement dangereuses (avalanche, crue, vent fort). Une clairière est relativement sûre, mais il faut vérifier les branches mortes et les arbres couchés.",
    "q.l27#9.p" to "Quelles conditions doit remplir un camp acceptable ?",
    "q.l27#9.o0" to "Sol plat et bon drainage",
    "q.l27#9.o1" to "Abrité du vent sans être fermé",
    "q.l27#9.o2" to "De l'eau disponible",
    "q.l27#9.o3" to "Un réseau mobile à pleine puissance",
    "q.l27#9.e" to "Les trois premières décident si l'on dort bien et si l'on prend froid. Le réseau est un bonus : on ne déplace pas le camp sur une crête exposée pour avoir de la couverture.",
    "q.l27#10.p" to "En pleine nature, quelles pratiques sont correctes pour les besoins et l'hygiène ?",
    "q.l27#10.o0" to "Creuser un trou de 15–20 cm et à plus de 60 m de l'eau",
    "q.l27#10.o1" to "Emporter le papier plutôt que le brûler",
    "q.l27#10.o2" to "Tout concentrer au même endroit",
    "q.l27#10.o3" to "Enterrer dans la neige",
    "q.l27#10.e" to "Concentrer aggrave la pollution locale, et enterrer dans la neige remet tout au jour à la fonte. Le trou plus le papier emporté est la pratique à faible impact courante.",
    "q.l27#11.p" to "Remettez dans l'ordre l'aménagement d'un camp.",
    "q.l27#11.o0" to "Évaluer le risque de chutes de pierres, d'avalanche et de crue",
    "q.l27#11.o1" to "Choisir l'emplacement de la tente et aplanir le sol",
    "q.l27#11.o2" to "Monter la tente, régler haubans et ancrages",
    "q.l27#11.o3" to "Délimiter la zone de cuisine, la zone de stockage et les toilettes",
    "q.l27#11.e" to "On évalue le risque avant de commencer. Beaucoup montent la tente avant de lever les yeux pour voir s'il y a des crevasses ou de la glace suspendue au-dessus.",
    "q.l27#12.p" to "La profondeur habituelle d'un trou en pleine nature est d'environ ______ cm.",
    "q.l27#12.a0" to "15–20",
    "q.l27#12.a1" to "15-20",
    "q.l27#12.a2" to "15",
    "q.l27#12.a3" to "20",
    "q.l27#12.a4" to "15~20",
    "q.l27#12.e" to "15–20 cm est la valeur la plus citée : assez pour la décomposition, sans traverser la couche superficielle du sol.",
    "q.l27#13.p" to "La distance sanitaire minimale entre le camp et l'eau ou les chemins est en général de ______ m.",
    "q.l27#13.a0" to "60",
    "q.l27#13.e" to "60 m (environ 70 pas) est la distance « sans trace » courante, pour les besoins, la vaisselle et la toilette.",
    "q.l27#14.p" to "Associez chaque zone du camp à son exigence.",
    "q.l27#14.l0" to "Zone de couchage",
    "q.l27#14.l1" to "Zone de cuisine",
    "q.l27#14.l2" to "Zone de stockage",
    "q.l27#14.l3" to "Zone de toilettes",
    "q.l27#14.r0" to "Plate, abritée, loin des flammes et des odeurs",
    "q.l27#14.r1" to "Ventilée, loin des tentes, attention au feu",
    "q.l27#14.r2" to "À l'abri de l'humidité et des animaux, proche sans gêner le passage",
    "q.l27#14.r3" to "À plus de 60 m de l'eau, hors du ruissellement de la pente",
    "q.l27#14.e" to "Séparer les zones met chaque activité dans ses conditions. Le résultat le plus direct d'un mauvais découpage, c'est une odeur de nourriture dans la tente et une flamme à côté du couchage.",
    "q.l27#15.p" to "Près du camp coule un joli ruisseau, mais il pleut fort deux kilomètres en amont. Comment juger ?",
    "q.l27#15.o0" to "Ne pas camper dans le lit : le risque de crue nocturne est élevé",
    "q.l27#15.o1" to "Ce n'est rien, le ruisseau est petit",
    "q.l27#15.o2" to "Rapprocher un peu la tente de l'eau",
    "q.l27#15.o3" to "Mettre des pierres dans le lit pour freiner l'eau",
    "q.l27#15.e" to "En montagne, une crue peut survenir en quelques minutes, et le bruit arrive avant l'eau. Ne pas camper dans un lit, une ravine ou un cône de déjection est une règle ferme.",
    "q.l27#16.p" to "Pourquoi éviter de camper sous un grand arbre isolé ?",
    "q.l27#16.o0" to "Parce que le risque de foudre et de chute de branches y est plus élevé",
    "q.l27#16.o1" to "Parce que l'air n'y circule pas",
    "q.l27#16.o2" to "Parce que les racines font trébucher",
    "q.l27#16.o3" to "Parce que cela fait de l'ombre",
    "q.l27#16.e" to "Un point haut et isolé est le chemin préférentiel de la foudre, et les branches cassées par la tempête sont une source fréquente de blessures. En forêt, on choisit une clairière, pas un arbre solitaire.",

    // ---------- l25 Préparation : permis, assurance et logistique ----------
    "q.l25#0.p" to "Qu'est-ce qui est le plus sous-estimé dans une demande de permis ?",
    "q.l25#0.o0" to "Les délais et les exigences annexes (guide, personne de liaison, certificat médical)",
    "q.l25#0.o1" to "Le coût",
    "q.l25#0.o2" to "Le format des photos",
    "q.l25#0.o3" to "Les horaires du guichet",
    "q.l25#0.e" to "Beaucoup d'itinéraires demandent une demande plusieurs semaines à l'avance, liée à un guide local ou à une personne de liaison. S'en occuper au pied de la montagne signifie souvent changer d'itinéraire.",
    "q.l25#1.p" to "En choisissant une assurance, quelles deux choses faut-il vérifier ?",
    "q.l25#1.o0" to "Que l'escalade technique est couverte et que l'évacuation en hélicoptère à haute altitude l'est aussi",
    "q.l25#1.o1" to "Qu'elle couvre les retards de vol",
    "q.l25#1.o2" to "Qu'elle soit résiliable",
    "q.l25#1.o3" to "Le montant de la prime",
    "q.l25#1.e" to "Les assurances voyage courantes excluent « l'escalade technique » et « la haute altitude ». Découvrir l'exclusion au moment du sinistre est le second dommage le plus fréquent dans ce type d'accident.",
    "q.l25#2.p" to "Quelle partie de la logistique doit absolument avoir une solution de rechange ?",
    "q.l25#2.o0" to "Transport, portage et ravitaillement du camp : chaque étape doit avoir une alternative",
    "q.l25#2.o1" to "Uniquement le transport",
    "q.l25#2.o2" to "Uniquement l'hébergement",
    "q.l25#2.o3" to "Aucune : pas besoin d'alternative",
    "q.l25#2.e" to "En montagne, le retard est la norme : route coupée, vol annulé, portage modifié. Avec une alternative à chaque étape, un blocage local ne fait pas s'effondrer toute la chaîne.",
    "q.l25#3.p" to "Dans la fiche d'itinéraire laissée au contact, quelles informations sont indispensables ?",
    "q.l25#3.o0" to "L'itinéraire, l'heure de chaque point de contrôle, et au bout de combien de temps sans nouvelles on déclenche le protocole et l'alerte",
    "q.l25#3.o1" to "Seulement le nom de la montagne",
    "q.l25#3.o2" to "Seulement les noms des partenaires",
    "q.l25#3.o3" to "Seulement le budget",
    "q.l25#3.e" to "La fiche sert à ce qu'une autre personne puisse décider « s'il faut s'inquiéter ». Les horaires et le protocole en sont le cœur, l'itinéraire en est la base.",
    "q.l25#4.p" to "Pourquoi garder 20 % de marge budgétaire ?",
    "q.l25#4.o0" to "Parce que les retards, les nuits supplémentaires et les porteurs ajoutés finissent toujours par arriver",
    "q.l25#4.o1" to "Pour acheter des souvenirs",
    "q.l25#4.o2" to "Pour les pourboires",
    "q.l25#4.o3" to "Parce que le taux de change varie",
    "q.l25#4.e" to "Ces dépenses ne sont pas des accidents, c'est la norme. La marge ne sert pas à économiser, mais à éviter de mauvaises décisions prises pour des raisons d'argent en montagne.",
    "q.l25#5.p" to "Quels documents faut-il en général pour faire certifier une ascension ?",
    "q.l25#5.o0" to "Photos ou vidéo du sommet, déclaration de sommet, permis et pièce d'identité",
    "q.l25#5.o1" to "Seulement des photos",
    "q.l25#5.o2" to "Seulement la signature d'un partenaire",
    "q.l25#5.o3" to "Aucun document",
    "q.l25#5.e" to "Chaque montagne a ses exigences, mais photos, déclaration et permis sont presque toujours demandés. Le vérifier avant de partir est bien plus simple que de régulariser au retour.",
    "q.l25#6.p" to "Quelles informations faut-il présenter à toute l'équipe avant le départ ?",
    "q.l25#6.o0" to "L'heure et le lieu de rendez-vous et d'évacuation",
    "q.l25#6.o1" to "Le canal radio et les règles d'appel",
    "q.l25#6.o2" to "Les informations médicales et les contre-indications médicamenteuses",
    "q.l25#6.o3" to "La répartition quotidienne de la nourriture de chacun",
    "q.l25#6.e" to "Les deux premières concernent les séparations et les secours, la troisième est une information clé en urgence. La répartition de la nourriture est un détail logistique que le chef d'expédition règle seul.",
    "q.l25#7.p" to "Lesquels de ces documents peuvent empêcher l'entrée s'ils manquent ?",
    "q.l25#7.o0" to "Le permis de réserve ou d'ascension",
    "q.l25#7.o1" to "La pièce d'identité",
    "q.l25#7.o2" to "L'attestation d'assurance (sur certains itinéraires)",
    "q.l25#7.o3" to "Le certificat de sommet",
    "q.l25#7.e" to "Le certificat de sommet s'obtient au retour et ne sert pas de document d'accès. Les deux premiers sont presque toujours contrôlés, le troisième selon l'itinéraire.",
    "q.l25#8.p" to "De la décision de partir à une montagne jusqu'au départ, quel est l'ordre raisonnable ?",
    "q.l25#8.o0" to "Fixer l'itinéraire et la fenêtre de temps",
    "q.l25#8.o1" to "Obtenir les permis, réserver le transport et le portage",
    "q.l25#8.o2" to "Souscrire une assurance adaptée et vérifier les exclusions",
    "q.l25#8.o3" to "Constituer le dossier de documents et laisser la fiche d'itinéraire au contact",
    "q.l25#8.e" to "D'abord l'itinéraire pour pouvoir demander le permis ; une fois permis et transport fixés, on sait quels jours et quelles activités l'assurance doit couvrir ; le classement des documents vient en dernier.",
    "q.l25#9.p" to "Si les bagages sont retardés ou n'arrivent pas sur le même vol, ce qu'il faut le plus avoir sur soi, ce sont ______.",
    "q.l25#9.a0" to "les chaussures d'alpinisme",
    "q.l25#9.a1" to "les chaussures de haute montagne",
    "q.l25#9.a2" to "les chaussures",
    "q.l25#9.a3" to "le matériel technique personnel",
    "q.l25#9.e" to "Perdre ses chaussures ou son matériel technique personnel est presque impossible à remplacer au pied levé. La plupart des équipes exigent de les garder en cabine.",
    "q.l25#10.p" to "On recommande de garder une marge de ______ % sur le budget.",
    "q.l25#10.a0" to "20",
    "q.l25#10.e" to "20 % est une valeur empirique. En montagne, les dépenses imprévues se concentrent sur « les retards » et « la main-d'œuvre ».",
    "q.l25#11.p" to "Associez chaque document à sa fonction.",
    "q.l25#11.l0" to "Permis d'ascension",
    "q.l25#11.l1" to "Attestation d'assurance et numéro de secours",
    "q.l25#11.l2" to "Déclaration de sommet",
    "q.l25#11.l3" to "Fiche d'itinéraire",
    "q.l25#11.r0" to "Justificatif d'accès, contrôlé aux postes",
    "q.l25#11.r1" to "Base pour joindre les secours et déclarer le sinistre",
    "q.l25#11.r2" to "À remettre pour demander le certificat de sommet",
    "q.l25#11.r3" to "Laissée au contact pour décider quand donner l'alerte",
    "q.l25#11.e" to "Quatre documents pour quatre situations : entrer, avoir un accident, faire certifier, disparaître. S'il en manque un, la situation correspondante se bloque.",
    "q.l25#12.p" to "Si l'équipe n'a pas clarifié avant le départ « qui a le droit de dire stop », quelle est la conséquence la plus probable ?",
    "q.l25#12.o0" to "Que personne n'ose parler quand il faudrait s'arrêter, et que le silence collectif amplifie le risque",
    "q.l25#12.o1" to "Qu'on marche plus vite",
    "q.l25#12.o2" to "Que le sac soit plus léger",
    "q.l25#12.o3" to "Aucune",
    "q.l25#12.e" to "Faire du « stop » une autorisation donnée à l'avance, et non une épreuve de courage personnel. Le dire avant le départ est bien plus utile que d'en débattre en montagne.",
    "q.l25#13.p" to "Le permis exige un guide local et quelqu'un s'y oppose. Que faire ?",
    "q.l25#13.o0" to "Respecter la règle et intégrer le guide au budget et au plan",
    "q.l25#13.o1" to "Contourner le poste de contrôle",
    "q.l25#13.o2" to "Faire figurer le guide seulement sur le papier",
    "q.l25#13.o3" to "Changer pour un itinéraire qui ne l'exige pas et réévaluer",
    "q.l25#13.e" to "Contourner le permis n'est pas seulement illégal : cela annule aussi le secours et l'assurance. Soit on est en règle, soit on change d'itinéraire — on ne compte pas sur la chance.",
    "q.l25#14.p" to "Pourquoi recueillir à l'avance les informations médicales et les traitements ?",
    "q.l25#14.o0" to "Parce qu'en urgence il faut connaître les contre-indications et les antécédents, et que l'altitude amplifie le risque des pathologies préexistantes",
    "q.l25#14.o1" to "Pour obtenir une réduction d'assurance",
    "q.l25#14.o2" to "Pour constituer les groupes",
    "q.l25#14.o3" to "Cela ne sert à rien",
    "q.l25#14.e" to "Au-dessus de 5 000 m, une infection banale ou une allergie médicamenteuse peut devenir une urgence. Les informations se recueillent avant le départ, pas en interrogeant chacun quand le problème est arrivé.",
    // ---------- l28 Se perdre et appeler à l'aide en pleine nature ----------
    "q.l28#0.p" to "Quelle est la première étape du principe STOP ?",
    "q.l28#0.o0" to "S'arrêter",
    "q.l28#0.o1" to "Revenir immédiatement sur ses pas",
    "q.l28#0.o2" to "Téléphoner",
    "q.l28#0.o3" to "Monter pour voir le chemin",
    "q.l28#0.e" to "S'arrêter ramène le jugement à la raison. En se perdant, le premier réflexe est souvent d'accélérer, et c'est précisément le début de l'aggravation.",
    "q.l28#1.p" to "Combien de signaux compte la convention internationale de détresse ?",
    "q.l28#1.o0" to "Trois (trois coups de sifflet, trois feux, trois colonnes de fumée)",
    "q.l28#1.o1" to "Un",
    "q.l28#1.o2" to "Cinq",
    "q.l28#1.o3" to "Le plus possible",
    "q.l28#1.e" to "Le « trois » est la convention internationale de détresse en montagne. Trois répétitions espacées d'une minute sont reconnues comme un appel, et non comme un bruit accidentel.",
    "q.l28#2.p" to "En pleine nature, quel moyen de signalisation demande le moins d'effort et porte le plus loin ?",
    "q.l28#2.o0" to "Le sifflet",
    "q.l28#2.o1" to "Crier fort",
    "q.l28#2.o2" to "Agiter les bras",
    "q.l28#2.o3" to "Siffler avec la bouche",
    "q.l28#2.e" to "Crier fait perdre la voix en quelques minutes, alors que le sifflet traverse le vent. C'est l'une des raisons pour lesquelles il figure dans les dix essentiels.",
    "q.l28#3.p" to "Vous vous êtes perdu et vous êtes sur une pente douce sans repère net. Que faire en priorité ?",
    "q.l28#3.o0" to "Se rappeler la dernière position sûre et juger si un retour en arrière est possible",
    "q.l28#3.o1" to "Continuer à descendre pour chercher un chemin",
    "q.l28#3.o2" to "Rester sur place jusqu'à la nuit",
    "q.l28#3.o3" to "Se séparer pour chercher chacun de son côté",
    "q.l28#3.e" to "La « dernière position sûre » est le seul point d'ancrage fiable. Se séparer est l'option la plus dangereuse : d'une personne perdue, on passe à deux.",
    "q.l28#4.p" to "En attendant les secours, qu'est-ce qu'il faut garantir d'abord ?",
    "q.l28#4.o0" to "Se protéger du froid et trouver de l'eau ; ensuite, se rendre visible",
    "q.l28#4.o1" to "Finir la nourriture du sac",
    "q.l28#4.o2" to "Continuer à chercher le chemin",
    "q.l28#4.o3" to "Dormir un peu",
    "q.l28#4.e" to "La plupart des décès après une perte de repères sont dus à l'hypothermie et à la déshydratation, pas à l'échec de la recherche du chemin. Abri, eau, visibilité : voilà les trois tâches de l'attente.",
    "q.l28#5.p" to "Lors d'une nuit imprévue, qu'est-ce qui est le plus nécessaire et le plus souvent resté au camp ?",
    "q.l28#5.o0" to "La frontale et la couche d'isolation",
    "q.l28#5.o1" to "Les barres de céréales",
    "q.l28#5.o2" to "La carte",
    "q.l28#5.o3" to "La gourde",
    "q.l28#5.e" to "Sur une sortie courte, on laisse souvent ces deux choses au camp. Si l'on est contraint de passer la nuit dehors, ce sont justement elles qui décident si l'on tient jusqu'au matin.",
    "q.l28#6.p" to "Un partenaire n'est pas rentré à l'heure prévue. Que faire en premier ?",
    "q.l28#6.o0" to "Confirmer le dernier point où on l'a vu et l'heure, et déclencher le protocole de disparition convenu",
    "q.l28#6.o1" to "Que tout le monde parte chercher séparément",
    "q.l28#6.o2" to "Continuer à attendre",
    "q.l28#6.o3" to "Replier la tente",
    "q.l28#6.e" to "On fixe d'abord l'information (heure, lieu, matériel, état), puis on décide comment chercher. Disperser tout le groupe est une recette fréquente de second accident.",
    "q.l28#7.p" to "Pourquoi le reflet d'un miroir fonctionne-t-il par beau temps ?",
    "q.l28#7.o0" to "Parce que la lumière réfléchie se voit de loin et depuis le ciel, bien plus loin que le son",
    "q.l28#7.o1" to "Parce que le miroir est brillant",
    "q.l28#7.o2" to "Parce qu'il émet un son",
    "q.l28#7.o3" to "Parce qu'il allume un feu",
    "q.l28#7.e" to "Les hélicoptères et les équipes lointaines repèrent facilement des éclats rythmés. Avec du soleil, le miroir est l'outil de signalisation au meilleur rapport efficacité-encombrement.",
    "q.l28#8.p" to "Quelles pratiques faut-il éviter quand on s'est perdu ?",
    "q.l28#8.o0" to "Continuer à marcher de nuit",
    "q.l28#8.o1" to "Se séparer",
    "q.l28#8.o2" to "Descendre en suivant un ruisseau sans réfléchir",
    "q.l28#8.o3" to "S'arrêter et monter un abri",
    "q.l28#8.e" to "Marcher de nuit, se disperser et descendre aveuglément un ruisseau sont les trois décisions mortelles les plus fréquentes. S'arrêter et monter un abri est justement la bonne réponse.",
    "q.l28#9.p" to "Que comprennent en général les « dix essentiels » ?",
    "q.l28#9.o0" to "Des outils de navigation (carte et boussole)",
    "q.l28#9.o1" to "Une frontale",
    "q.l28#9.o2" to "Un vêtement chaud supplémentaire",
    "q.l28#9.o3" to "Une protection solaire et une trousse de secours",
    "q.l28#9.e" to "La logique des dix essentiels est « pouvoir survivre à une nuit imprévue » : navigation, éclairage, chaleur, eau, nourriture, protection solaire, trousse de secours, allumage de feu, couteau et abri.",
    "q.l28#10.p" to "Que faut-il absolument préciser dans un message de détresse ?",
    "q.l28#10.o0" to "La position (coordonnées ou repère visible)",
    "q.l28#10.o1" to "Le nombre de personnes et l'état des blessés",
    "q.l28#10.o2" to "Le matériel et les vivres disponibles",
    "q.l28#10.o3" to "L'année de création du groupe",
    "q.l28#10.e" to "Les secours ont besoin de savoir « où, combien, dans quel état, et jusqu'à quand on peut tenir ». S'il manque un des quatre premiers, on perd des heures en vérifications.",
    "q.l28#11.p" to "Remettez dans l'ordre la réaction après une perte de repères.",
    "q.l28#11.o0" to "S'arrêter et admettre qu'on s'est perdu",
    "q.l28#11.o1" to "Se rappeler la dernière position sûre",
    "q.l28#11.o2" to "Évaluer s'il est possible de revenir sur ses pas ou de rejoindre un terrain évident",
    "q.l28#11.o3" to "Fixer un plan et l'exécuter, avec une solution de secours préparée",
    "q.l28#11.e" to "Le cœur de l'ordre est « admettre, se situer, décider ». Sans l'aveu, les trois étapes suivantes ne sont pas vraiment exécutées.",
    "q.l28#12.p" to "Quel est l'ordre des priorités pendant l'attente des secours ?",
    "q.l28#12.o0" to "Trouver un endroit abrité et enfiler la couche chaude",
    "q.l28#12.o1" to "Trouver de l'eau ou faire fondre de la neige",
    "q.l28#12.o2" to "Mettre en place des signaux visibles (sifflet, miroir, vêtements de couleur)",
    "q.l28#12.o3" to "Répéter les appels à intervalles fixes",
    "q.l28#12.e" to "D'abord survivre, ensuite appeler. Dans l'autre sens, on peut être en hypothermie avant même d'avoir émis le premier signal.",
    "q.l28#13.p" to "Le signal international de détresse se répète ______ fois par série.",
    "q.l28#13.a0" to "3",
    "q.l28#13.a1" to "trois",
    "q.l28#13.e" to "Trois répétitions espacées d'une minute : c'est la convention commune en montagne et en mer.",
    "q.l28#14.p" to "La règle en quatre étapes quand on se perd est STOP, et le P signifie ______.",
    "q.l28#14.a0" to "Plan",
    "q.l28#14.a1" to "plan",
    "q.l28#14.a2" to "planifier",
    "q.l28#14.e" to "Stop, Think, Observe, Plan. D'abord s'arrêter, puis réfléchir, puis observer, et enfin fixer le plan.",
    "q.l28#15.p" to "Associez chaque moyen d'appel à sa condition d'emploi.",
    "q.l28#15.l0" to "Sifflet",
    "q.l28#15.l1" to "Reflet d'un miroir",
    "q.l28#15.l2" to "Trois colonnes de fumée",
    "q.l28#15.l3" to "Vêtements de couleur vive",
    "q.l28#15.r0" to "Par tous les temps, trois coups brefs répétés",
    "q.l28#15.r1" to "Ciel dégagé, avec soleil et bonne visibilité",
    "q.l28#15.r2" to "De jour, sans vent fort et avec un espace ouvert",
    "q.l28#15.r3" to "Étendus au sol face à un hélicoptère ou à une équipe lointaine",
    "q.l28#15.e" to "Aucun moyen ne marche par tous les temps : il faut en utiliser plusieurs à la fois. Appeler à l'aide consiste à augmenter la probabilité d'être vu, pas à trouver la méthode parfaite.",
    "q.l28#16.p" to "Pas de réseau mobile, mais l'équipe a un communicateur satellite. Quand l'utiliser ?",
    "q.l28#16.o0" to "Dès qu'un secours extérieur est confirmé nécessaire, sans attendre la nuit",
    "q.l28#16.o1" to "Le lendemain",
    "q.l28#16.o2" to "Seulement si quelqu'un est blessé",
    "q.l28#16.o3" to "Garder pour le dernier jour",
    "q.l28#16.e" to "L'appareil a une batterie limitée et dépend de fenêtres météo, et un secours demande du temps. Si l'on attend la nuit ou une dégradation, l'hélicoptère ne peut souvent plus passer.",
    "q.l28#17.p" to "Si l'on décide de sortir par ses propres moyens, que faire avant de partir ?",
    "q.l28#17.o0" to "Laisser un mot avec la destination et l'heure, emporter de quoi se chauffer et s'éclairer, et fixer l'azimut",
    "q.l28#17.o1" to "Partir directement",
    "q.l28#17.o2" to "Laisser le matériel pour alléger",
    "q.l28#17.o3" to "Se séparer",
    "q.l28#17.e" to "« Sortir par ses propres moyens » est une décision qui doit être documentée : le mot indique à l'équipe de recherche où vous allez, et le matériel décide si vous arrivez.",

    // ---------- l29 Déshydratation, coup de chaleur et traumatismes courants ----------
    "q.l29#0.p" to "En altitude, quel est l'indicateur quotidien le plus fiable d'une déshydratation ?",
    "q.l29#0.o0" to "Urines plus foncées et moins abondantes",
    "q.l29#0.o1" to "L'intensité de la soif",
    "q.l29#0.o2" to "Le poids corporel",
    "q.l29#0.o3" to "La sécheresse de la peau",
    "q.l29#0.e" to "Quand la soif apparaît, le déficit est déjà net. La couleur des urines est le moyen de contrôle le moins coûteux : jaune clair, c'est bon ; foncé, il faut boire.",
    "q.l29#1.p" to "Quel est le critère central du coup de chaleur ?",
    "q.l29#1.o0" to "Une température centrale supérieure à 40 °C avec trouble de la conscience",
    "q.l29#1.o1" to "Transpirer beaucoup",
    "q.l29#1.o2" to "Une peau rouge",
    "q.l29#1.o3" to "Un pouls accéléré",
    "q.l29#1.e" to "Dès qu'apparaît un trouble de la conscience (propos incohérents, démarche instable, coma), il faut traiter comme un coup de chaleur, refroidir immédiatement et évacuer, sans attendre le thermomètre.",
    "q.l29#2.p" to "Quel est le bon ordre de traitement d'un problème lié à la chaleur ?",
    "q.l29#2.o0" to "Mettre à l'ombre, desserrer les vêtements, refroidir physiquement, réhydrater avec des électrolytes",
    "q.l29#2.o1" to "Réhydrater d'abord, refroidir ensuite",
    "q.l29#2.o2" to "Faire boire d'abord, mettre à l'ombre ensuite",
    "q.l29#2.o3" to "Masser d'abord les membres",
    "q.l29#2.e" to "Refroidir passe avant la réhydratation : la chaleur abîme les organes, alors que la réhydratation demande du temps pour agir. Masser les membres peut en plus surcharger la circulation.",
    "q.l29#3.p" to "Que faire si la personne en coup de chaleur est inconsciente ?",
    "q.l29#3.o0" to "Ne pas forcer à boire : appliquer des linges froids et évacuer au plus vite",
    "q.l29#3.o1" to "Lui verser de l'eau dans la bouche",
    "q.l29#3.o2" to "Lui donner des comprimés de sel",
    "q.l29#3.o3" to "La laisser boire seule",
    "q.l29#3.e" to "Avec une conscience altérée, le réflexe de déglutition n'est pas fiable et forcer à boire provoque une fausse route. Ici, seuls le refroidissement et le secours professionnel agissent.",
    "q.l29#4.p" to "Quand une ampoule empêche de marcher, quel est le bon traitement ?",
    "q.l29#4.o0" to "Désinfecter, percer depuis le bord, conserver l'épiderme et couvrir d'un pansement",
    "q.l29#4.o1" to "Arracher la peau entière",
    "q.l29#4.o2" to "Percer au centre",
    "q.l29#4.o3" to "Ne rien faire et continuer à marcher",
    "q.l29#4.e" to "La peau de l'ampoule est le meilleur pansement et prévient l'infection. Percer au centre la déchire, et l'arracher met la plaie au contact de la chaussette sale.",
    "q.l29#5.p" to "Comment traiter sur place une brûlure du premier degré (peau rouge et douloureuse) ?",
    "q.l29#5.o0" to "Rincer à l'eau froide pendant 20 minutes, puis couvrir d'un pansement propre",
    "q.l29#5.o1" to "Du dentifrice",
    "q.l29#5.o2" to "De l'huile",
    "q.l29#5.o3" to "De l'alcool",
    "q.l29#5.e" to "L'eau froide évacue la chaleur résiduelle et limite les lésions. Le dentifrice et les pommades grasses emprisonnent la chaleur et augmentent le risque d'infection.",
    "q.l29#6.p" to "Pourquoi un coup de soleil est-il plus grave en altitude qu'en plaine ?",
    "q.l29#6.o0" to "Le rayonnement ultraviolet est plus intense et la neige le réfléchit, doublant l'exposition",
    "q.l29#6.o1" to "Parce qu'il y a plus de vent",
    "q.l29#6.o2" to "Parce que la peau est plus fine",
    "q.l29#6.o3" to "Parce qu'on transpire plus",
    "q.l29#6.e" to "Tous les 1 000 m d'altitude, le rayonnement ultraviolet augmente d'environ 10–12 %, et la neige en réfléchit une grande partie. Par temps couvert et dans le brouillard neigeux, on brûle aussi.",
    "q.l29#7.p" to "Quel ensemble d'observations permet le mieux de juger si la réhydratation est suffisante ?",
    "q.l29#7.o0" to "Couleur et volume des urines, fréquence cardiaque au repos et état mental",
    "q.l29#7.o1" to "La variation de poids",
    "q.l29#7.o2" to "L'élasticité de la peau",
    "q.l29#7.o3" to "La sensation de soif",
    "q.l29#7.e" to "Les quatre ensemble sont informatifs. Seul avec la soif ou seul avec la couleur, on peut se tromper, surtout par temps froid où les urines se concentrent.",
    "q.l29#8.p" to "Un partenaire a des crampes (après avoir beaucoup transpiré). Que faire ?",
    "q.l29#8.o0" to "Arrêter l'effort, aller à l'ombre, donner une boisson avec des électrolytes et étirer doucement",
    "q.l29#8.o1" to "Continuer à marcher, ça passera",
    "q.l29#8.o2" to "Ne donner que de l'eau",
    "q.l29#8.o3" to "Frictionner le muscle avec force",
    "q.l29#8.e" to "Les crampes signalent une perte d'électrolytes. Ne donner que de l'eau dilue encore le sodium et peut aggraver la situation.",
    "q.l29#9.p" to "Quels facteurs augmentent nettement le risque de problème lié à la chaleur ?",
    "q.l29#9.o0" to "Forte humidité et absence de vent",
    "q.l29#9.o1" to "Des vêtements qui ne respirent pas",
    "q.l29#9.o2" to "Ne pas avoir assez dormi la nuit précédente",
    "q.l29#9.o3" to "Ne boire que de l'eau après avoir beaucoup transpiré",
    "q.l29#9.e" to "Les quatre affaiblissent la dissipation de chaleur ou l'équilibre des électrolytes. Le problème de chaleur n'a jamais une seule cause : c'est l'addition de plusieurs conditions défavorables.",
    "q.l29#10.p" to "Parmi les traumatismes courants, lesquels faut-il traiter en priorité sur place ?",
    "q.l29#10.o0" to "Une hémorragie importante",
    "q.l29#10.o1" to "Le déplacement d'une personne avec suspicion de lésion de la colonne",
    "q.l29#10.o2" to "Une plaie au pied qui empêche de marcher",
    "q.l29#10.o3" to "Une simple éraflure",
    "q.l29#10.e" to "Arrêter une hémorragie, protéger la colonne et rétablir la capacité de marcher font partie de ce qui s'aggrave sans traitement ; une éraflure peut attendre le nettoyage au camp.",
    "q.l29#11.p" to "Que contient en général une petite pharmacie d'urgence en pleine nature ?",
    "q.l29#11.o0" to "Antalgiques et antipyrétiques",
    "q.l29#11.o1" to "Antihistaminiques",
    "q.l29#11.o2" to "Antidiarrhéiques et sels de réhydratation orale",
    "q.l29#11.o3" to "Des antibiotiques (à usage libre)",
    "q.l29#11.e" to "Les trois premiers relèvent du traitement symptomatique, avec une indication claire et un risque maîtrisé. Les antibiotiques se décident avec un médecin : en avoir sur soi n'autorise pas à en prendre seul.",
    "q.l29#12.p" to "Remettez dans l'ordre la prise en charge d'un coup de chaleur sur place.",
    "q.l29#12.o0" to "Mettre à l'ombre et retirer les vêtements superflus",
    "q.l29#12.o1" to "Arroser d'eau froide ou appliquer du froid sur la nuque, les aisselles et l'aine",
    "q.l29#12.o2" to "Surveiller la conscience et la respiration, et préparer l'appel aux secours",
    "q.l29#12.o3" to "Évacuer au plus vite en poursuivant le refroidissement pendant le transport",
    "q.l29#12.e" to "Le cœur de l'ordre est « ne pas interrompre le refroidissement ». La mortalité du coup de chaleur dépend de la durée de l'hyperthermie, donc on refroidit aussi pendant le transport.",
    "q.l29#13.p" to "Remettez dans l'ordre le traitement d'une ampoule au pied.",
    "q.l29#13.o0" to "Se laver les mains et désinfecter le matériel",
    "q.l29#13.o1" to "Percer et drainer depuis le bord de l'ampoule",
    "q.l29#13.o2" to "Conserver l'épiderme et couvrir d'un pansement",
    "q.l29#13.o3" to "Mettre des chaussettes sèches et ajuster les lacets",
    "q.l29#13.e" to "L'infection est la principale complication d'une ampoule. Désinfecter, conserver la peau et garder au sec : en manquer une des trois étapes gâche le résultat.",
    "q.l29#14.p" to "La ligne de température centrale qui définit le coup de chaleur est ______ °C (donnez un nombre entier).",
    "q.l29#14.a0" to "40",
    "q.l29#14.e" to "40 °C plus un trouble de la conscience : c'est le critère classique. Sans thermomètre sur place, c'est l'état mental qui prime.",
    "q.l29#15.p" to "Après une brûlure, on recommande de rafraîchir à l'eau froide pendant environ ______ minutes.",
    "q.l29#15.a0" to "20",
    "q.l29#15.e" to "20 minutes évacuent efficacement la chaleur résiduelle. Moins longtemps, la chaleur continue de diffuser vers les tissus profonds.",
    "q.l29#16.p" to "Un des signaux précoces les plus fiables de déshydratation est une urine plus ______.",
    "q.l29#16.a0" to "foncée",
    "q.l29#16.a1" to "foncé",
    "q.l29#16.a2" to "concentrée",
    "q.l29#16.e" to "Des urines foncées signifient une concentration. C'est l'indicateur le moins coûteux et le plus simple à vérifier chaque jour.",
    "q.l29#17.p" to "Associez chaque degré de problème lié à la chaleur à ses signes typiques.",
    "q.l29#17.l0" to "Crampes de chaleur",
    "q.l29#17.l1" to "Épuisement par la chaleur",
    "q.l29#17.l2" to "Coup de chaleur débutant",
    "q.l29#17.l3" to "Coup de chaleur",
    "q.l29#17.r0" to "Crampes musculaires après avoir beaucoup transpiré, conscience normale",
    "q.l29#17.r1" to "Faiblesse, vertiges, nausées, peau froide et moite",
    "q.l29#17.r2" to "Température élevée, mal de tête, coordinations perturbées",
    "q.l29#17.r3" to "Température centrale supérieure à 40 °C avec trouble de la conscience",
    "q.l29#17.e" to "Les quatre degrés forment une aggravation continue, pas quatre maladies indépendantes. Identifier le degré décide si l'on doit « s'arrêter et boire » ou « refroidir et appeler tout de suite ».",
    "q.l29#18.p" to "Associez chaque traumatisme à son traitement sur place.",
    "q.l29#18.l0" to "Hémorragie importante",
    "q.l29#18.l1" to "Entorse",
    "q.l29#18.l2" to "Brûlure",
    "q.l29#18.l3" to "Suspicion de lésion de la colonne",
    "q.l29#18.r0" to "Compression directe et, si besoin, bandage compressif",
    "q.l29#18.r1" to "Repos, froid, compression, élévation (RICE)",
    "q.l29#18.r2" to "Eau froide 20 minutes puis pansement propre",
    "q.l29#18.r3" to "Ne pas mobiliser, maintenir l'axe et appeler les secours",
    "q.l29#18.e" to "Le point commun des quatre : faire d'abord ce qui ne peut pas être fait de travers — comprimer, immobiliser, refroidir, ne pas bouger. Ensuite on attend l'avis professionnel, sans inventer de geste.",
    "q.l29#19.p" to "Quelqu'un a depuis deux jours des urines très foncées, mal à la tête et se sent faible. Quelle est l'interprétation la plus raisonnable ?",
    "q.l29#19.o0" to "Traiter d'abord comme une déshydratation et surveiller, en restant attentif au mal des montagnes",
    "q.l29#19.o1" to "C'est forcément le mal des montagnes : descendre immédiatement",
    "q.l29#19.o2" to "C'est juste la fatigue",
    "q.l29#19.o3" to "Donner du café pour le réveiller",
    "q.l29#19.e" to "Déshydratation et MAM se recouvrent largement, et les traitements ne s'opposent pas : hydratation, repos, surveillance. Si cela ne s'améliore pas ou qu'apparaît une démarche instable, on traite comme le mal des montagnes.",
    "q.l29#20.p" to "Pourquoi ne pas conseiller « boire seulement quand on a soif » en altitude ?",
    "q.l29#20.o0" to "Parce que la soif arrive en retard sur le déficit réel et qu'en altitude on perd plus d'eau en respirant",
    "q.l29#20.o1" to "Parce que l'eau pèse lourd",
    "q.l29#20.o2" to "Parce que boire provoque le mal des montagnes",
    "q.l29#20.o3" to "Parce qu'on va aux toilettes trop souvent",
    "q.l29#20.e" to "L'air sec et le volume respiratoire élevé provoquent des pertes invisibles importantes. Quand la soif apparaît, le jugement est souvent déjà altéré.",
    "q.l29#21.p" to "Après une marche en plein soleil, un partenaire a mal à la tête, des nausées et la peau froide et moite. Que faire en premier ?",
    "q.l29#21.o0" to "Arrêter l'effort immédiatement, le mettre à l'ombre, commencer à refroidir et réhydrater avec des électrolytes",
    "q.l29#21.o1" to "Continuer jusqu'au camp",
    "q.l29#21.o2" to "Lui donner un antalgique et continuer",
    "q.l29#21.o3" to "Le couvrir pour qu'il n'attrape pas froid",
    "q.l29#21.e" to "C'est le tableau typique de l'épuisement par la chaleur. Continuer à marcher pousse rapidement vers le coup de chaleur, qui peut tuer en quelques dizaines de minutes.",
    "q.l29#22.p" to "En protection solaire, quelles zones oublie-t-on le plus ?",
    "q.l29#22.o0" to "Les lèvres, les ailes du nez, derrière les oreilles et sous le menton",
    "q.l29#22.o1" to "Les bras",
    "q.l29#22.o2" to "Les mollets",
    "q.l29#22.o3" to "La nuque",
    "q.l29#22.e" to "Ces zones soit n'ont pas de protection mélanique, soit reçoivent une lumière réfléchie par le bas. Une brûlure à cet endroit fait mal en mangeant, en parlant et en portant le casque.",
    // ---------- l32 Corde fixe et systèmes d'ancrage ----------
    "q.l32#0.p" to "La corde fixe se classe en trois types selon l'usage. Quel groupe est correct ?",
    "q.l32#0.o0" to "Main courante, corde fixe courte, équipement de la voie",
    "q.l32#0.o1" to "Simple, double, jumelée",
    "q.l32#0.o2" to "Dynamique, statique, cordelette",
    "q.l32#0.o3" to "Tronçon supérieur, médian, inférieur",
    "q.l32#0.e" to "Les trois types correspondent à trois situations et à trois façons de faire. Confondre les situations, c'est équiper pour toute une saison un itinéraire avec la méthode d'une main courante.",

    "q.l32#1.p" to "Quelle corde utiliser pour une corde fixe de longue distance ?",
    "q.l32#1.o0" to "Une corde statique (peu allongeable)",
    "q.l32#1.o1" to "Une corde dynamique",
    "q.l32#1.o2" to "Une cordelette",
    "q.l32#1.o3" to "Une sangle",
    "q.l32#1.e" to "L'allongement d'une corde dynamique est conçu pour la chute ; sur une corde fixe, il fait rebondir la personne et accélère l'usure.",

    "q.l32#2.p" to "Quelle plage de diamètre est courante pour une corde fixe statique ?",
    "q.l32#2.o0" to "9–11 mm",
    "q.l32#2.o1" to "5–6 mm",
    "q.l32#2.o2" to "7–8 mm",
    "q.l32#2.o3" to "12–14 mm",
    "q.l32#2.e" to "Trop fine, la résistance à l'abrasion est faible et la prise glisse ; trop grosse, poids et volume augmentent. 9–11 mm est la plage usuelle de l'équipement de la voie.",

    "q.l32#3.p" to "Quel est le problème de « deux ancrages enfilés sur une même sangle » ?",
    "q.l32#3.o0" to "C'est une défaillance en série, pas de la redondance",
    "q.l32#3.o1" to "Cela gaspille de la sangle",
    "q.l32#3.o2" to "Ce n'est pas esthétique",
    "q.l32#3.o3" to "Cela ralentit la corde",
    "q.l32#3.e" to "Dans un montage en série, la défaillance d'un point détend tout le système et fait varier brutalement les efforts. La redondance suppose que chaque point rejoigne le mousqueton indépendamment.",

    "q.l32#4.p" to "Dans les cinq contrôles d'ancrage, que signifie « indépendance » ?",
    "q.l32#4.o0" to "Deux ancrages sur des rochers, des arbres ou des scellements différents",
    "q.l32#4.o1" to "Deux ancrages proches l'un de l'autre",
    "q.l32#4.o2" to "Une seule et même sangle",
    "q.l32#4.o3" to "Deux coinceurs dans la même fissure",
    "q.l32#4.e" to "Deux coinceurs dans la même fissure lâchent ensemble quand le rocher cède. L'indépendance juge si la cause de défaillance est la même.",

    "q.l32#5.p" to "Que vérifie le contrôle de « direction » d'un ancrage ?",
    "q.l32#5.o0" to "L'ancrage doit encaisser la direction réelle de l'effort, pas seulement vers le bas",
    "q.l32#5.o1" to "L'ancrage doit être orienté vers le paysage",
    "q.l32#5.o2" to "La corde doit filer droit",
    "q.l32#5.o3" to "L'ancrage doit être au-dessus",
    "q.l32#5.e" to "Le balancement latéral pendant l'équipement et les oscillations en montant créent des efforts latéraux. Un ancrage pensé uniquement vers le bas cède sous un effort latéral.",

    "q.l32#6.p" to "Sur un ancrage dans la neige, de quoi faut-il se méfier en plus ?",
    "q.l32#6.o0" to "De la résistance du manteau et du risque de fonte : en fondant, tout un tronçon peut céder",
    "q.l32#6.o1" to "La neige est trop molle pour enterrer",
    "q.l32#6.o2" to "La neige va mouiller la corde",
    "q.l32#6.o3" to "Le corps mort est trop lourd",
    "q.l32#6.e" to "La fiabilité d'un ancrage neige dépend fortement de la température et de l'heure. Un ancrage de l'après-midi, quand la neige fond, n'a plus rien à voir avec celui du matin.",

    "q.l32#7.p" to "À quoi sert le nœud d'arrêt au bout de la corde ?",
    "q.l32#7.o0" to "À empêcher le bout de sortir du matériel",
    "q.l32#7.o1" to "À faciliter le rangement de la corde",
    "q.l32#7.o2" to "À marquer la longueur",
    "q.l32#7.o3" to "À augmenter le frottement",
    "q.l32#7.e" to "En descente ou en second, si le bout sort du matériel, la personne perd toute connexion. Le nœud d'arrêt est l'assurance qui coûte le moins et rapporte le plus.",

    "q.l32#8.p" to "Quel est le rôle principal d'un relais intermédiaire (re-belay) ?",
    "q.l32#8.o0" to "Faire suivre la corde sans à-coup et limiter chute et usure à un seul tronçon",
    "q.l32#8.o1" to "Ajouter du poids",
    "q.l32#8.o2" to "Faciliter les photos",
    "q.l32#8.o3" to "Remplacer le relais d'assurage",
    "q.l32#8.e" to "Sans relais sur un itinéraire long, la corde forme un angle énorme sur les arêtes : tirage difficile, usure concentrée et chute plus longue.",

    "q.l32#9.p" to "Pendant l'équipement, peut-il y avoir quelqu'un en dessous ?",
    "q.l32#9.o0" to "Non : la zone en dessous doit être vide quand l'équipeur travaille au-dessus",
    "q.l32#9.o1" to "Oui, pour passer les outils",
    "q.l32#9.o2" to "Oui, à condition de porter un casque",
    "q.l32#9.o3" to "Oui, à condition de ne pas plaisanter",
    "q.l32#9.e" to "Les chutes de pierres sont la première cause de blessure pendant l'équipement. Laisser quelqu'un en dessous, c'est réserver la place la plus dangereuse à un coéquipier.",

    "q.l32#10.p" to "Quelles sont les quatre choses à fixer dès la planification de l'équipement ?",
    "q.l32#10.o0" to "Début et fin de chaque tronçon, relais et points de retrait, longueur de corde, mode de fixation",
    "q.l32#10.o1" to "Couleur, marque, prix, poids",
    "q.l32#10.o2" to "Qui monte d'abord, qui photographie, qui fait chauffer l'eau, qui tient les comptes",
    "q.l32#10.o3" to "Météo, humeur, budget, congés",
    "q.l32#10.e" to "Ces quatre points décident si l'équipement peut se retirer en sécurité. Sauter la planification et monter directement sur la corde, c'est confier le retrait à la chance.",

    "q.l32#11.p" to "Pourquoi une corde fixe doit-elle être « contrôlée régulièrement et consignée » ?",
    "q.l32#11.o0" to "L'itinéraire sert souvent toute la saison et l'état de la corde évolue avec le soleil, l'usure et le gel-dégel",
    "q.l32#11.o1" to "Pour l'audit",
    "q.l32#11.o2" to "Pour répartir les responsabilités",
    "q.l32#11.o3" to "Ce n'est pas nécessaire",
    "q.l32#11.e" to "Une gaine pelucheuse, une corde raidie, un aplatissement local sont des signaux de mise au rebut. Sans relevé, personne ne peut dire combien de jours cette corde est restée en place.",

    "q.l32#12.p" to "Quels points font partie des cinq contrôles d'ancrage ?",
    "q.l32#12.o0" to "Indépendance",
    "q.l32#12.o1" to "Répartition",
    "q.l32#12.o2" to "Direction",
    "q.l32#12.o3" to "Protection des arêtes",
    "q.l32#12.e" to "Le cinquième est la redondance. Le plus souvent oublié est l'arête : une sangle entaillée par un angle de rocher peut perdre une grande partie de sa résistance.",

    "q.l32#13.p" to "Quels signes indiquent qu'une corde fixe doit être retirée ?",
    "q.l32#13.o0" to "Gaine pelucheuse, âme perceptible au toucher",
    "q.l32#13.o1" to "Corde raidie, toucher cassant",
    "q.l32#13.o2" to "Aplatissement local",
    "q.l32#13.o3" to "Couleur passée",
    "q.l32#13.e" to "Les trois premiers sont des dommages structurels. La décoloration n'est qu'esthétique, mais il faut garder en tête son lien avec le vieillissement aux UV.",

    "q.l32#14.p" to "Quelles exigences d'auto-assurance s'appliquent au travail d'équipement ?",
    "q.l32#14.o0" to "Toujours au moins deux points de connexion",
    "q.l32#14.o1" to "Porter un casque",
    "q.l32#14.o2" to "Surveiller au-dessus et prévenir les chutes de pierres",
    "q.l32#14.o3" to "Gérer le rab de corde dans un sac",
    "q.l32#14.e" to "Les quatre forment la sécurité du poste de travail. « Deux points » est la seule règle dure ; la seule exception est l'encordement direct pour ouvrir.",

    "q.l32#15.p" to "Sur quels plans la redondance d'un système de corde fixe peut-elle se lire ?",
    "q.l32#15.o0" to "Redondance d'ancrage (deux points indépendants)",
    "q.l32#15.o1" to "Redondance de connexion (PAS ou sangle de secours)",
    "q.l32#15.o2" to "Redondance de matériel (nœud autobloquant de secours)",
    "q.l32#15.o3" to "Redondance de couleur (acheter plusieurs coloris)",
    "q.l32#15.e" to "Les trois premiers niveaux correspondent à « le système ne cède pas, le transfert ne tombe pas dans le vide, le matériel ne porte pas seul ». La couleur n'a rien à voir avec la sécurité.",

    "q.l32#16.p" to "Remettez dans l'ordre l'installation d'une corde fixe.",
    "q.l32#16.o0" to "Repérer début, fin et relais, estimer la longueur de corde",
    "q.l32#16.o1" to "Construire les ancrages (indépendants, répartis, avec redondance)",
    "q.l32#16.o2" to "Poser la corde et installer les relais intermédiaires",
    "q.l32#16.o3" to "Nouer le bout et consigner l'état de la corde",
    "q.l32#16.e" to "La longueur doit garder de la marge pour les nœuds et les connexions : plutôt trop long que trop court. Le nœud d'arrêt vient en dernier, mais il n'est jamais facultatif.",

    "q.l32#17.p" to "Un point d'ancrage paraît douteux : dans quel ordre agir ?",
    "q.l32#17.o0" to "Arrêter l'usage du tronçon et mettre les personnes en sécurité",
    "q.l32#17.o1" to "Ajouter un point de secours indépendant",
    "q.l32#17.o2" to "Rééquilibrer les efforts",
    "q.l32#17.o3" to "Contrôler, consigner, puis décider de continuer ou non",
    "q.l32#17.e" to "Mettre les gens en sécurité avant la technique. L'ordre inverse transforme l'intervention elle-même en scène d'accident.",

    "q.l32#18.p" to "Quel est le bon déroulé quotidien d'une corde fixe utilisée longtemps ?",
    "q.l32#18.o0" to "Contrôler les ancrages et l'état de la corde avant de partir",
    "q.l32#18.o1" to "Vérifier les deux connexions au passage",
    "q.l32#18.o2" to "Au retour, contrôler l'usure et le nœud d'arrêt",
    "q.l32#18.o3" to "Noter la date du contrôle et les problèmes",
    "q.l32#18.e" to "La valeur de ce déroulé est de transformer le contrôle en habitude. Gérer de mémoire une corde fixe de toute une saison finit toujours par laisser passer quelque chose.",

    "q.l32#19.p" to "La norme de la corde dynamique est EN ______.",
    "q.l32#19.a0" to "892",
    "q.l32#19.e" to "Corde dynamique EN 892 / UIAA 101, corde statique EN 1891 / UIAA 110. À l'achat comme au contrôle, on vérifie le numéro de norme.",

    "q.l32#20.p" to "Pour une corde fixe, on choisit une corde ______ (répondre « dynamique » ou « statique »).",
    "q.l32#20.a0" to "statique",
    "q.l32#20.a1" to "corde statique",
    "q.l32#20.e" to "La corde statique est peu allongeable et résiste à l'abrasion, ce qui convient à une fixation longue. L'allongement d'une dynamique fait sans cesse rebondir la corde fixe.",

    "q.l32#21.p" to "Pendant l'équipement, le bout de corde doit être ______ pour éviter qu'il ne sorte du matériel.",
    "q.l32#21.a0" to "noué",
    "q.l32#21.a1" to "un nœud d'arrêt",
    "q.l32#21.e" to "C'est l'étape la plus souvent omise, et celle dont les conséquences sont les plus directes.",

    "q.l32#22.p" to "La plage de diamètre usuelle du statique pour l'équipement de la voie est ______–11 mm.",
    "q.l32#22.a0" to "9",
    "q.l32#22.e" to "9–11 mm concilie abrasion et poids. En dessous de 9 mm l'usure est rapide, au-dessus de 11 mm le poids se sent nettement.",

    "q.l32#23.p" to "Associez chaque type de corde fixe à sa situation typique.",
    "q.l32#23.l0" to "Main courante",
    "q.l32#23.l1" to "Corde fixe courte",
    "q.l32#23.l2" to "Équipement de la voie",
    "q.l32#23.l3" to "Relais intermédiaire",
    "q.l32#23.r0" to "Petit passage exposé que l'on traverse en se tenant à la corde",
    "q.l32#23.r1" to "Une pente raide ou une longueur, montée et descente répétées",
    "q.l32#23.r2" to "Itinéraire long, plusieurs longueurs, portage, usage toute la saison",
    "q.l32#23.r3" to "Découper une longue corde pour réduire les angles et l'usure",
    "q.l32#23.e" to "La situation dicte la norme : plus c'est long, chargé et exposé, plus les exigences de redondance et de suivi montent.",

    "q.l32#24.p" to "Associez chaque matériel à son numéro de norme.",
    "q.l32#24.l0" to "Corde statique",
    "q.l32#24.l1" to "Corde dynamique",
    "q.l32#24.l2" to "Bloqueur",
    "q.l32#24.l3" to "Harnais",
    "q.l32#24.r0" to "EN 1891 / UIAA 110",
    "q.l32#24.r1" to "EN 892 / UIAA 101",
    "q.l32#24.r2" to "EN 567",
    "q.l32#24.r3" to "EN 12277",
    "q.l32#24.e" to "Le numéro de norme sert de base à l'achat et au contrôle, et permet de savoir pour quel effort tel objet a été conçu.",

    "q.l32#25.p" to "Associez chaque problème d'ancrage à sa conséquence.",
    "q.l32#25.l0" to "Défaillance en série",
    "q.l32#25.l1" to "Direction d'effort unique",
    "q.l32#25.l2" to "Arête non protégée",
    "q.l32#25.l3" to "Point unique sans redondance",
    "q.l32#25.r0" to "La défaillance d'un point détend tout le système et fait varier les efforts",
    "q.l32#25.r1" to "L'ancrage s'arrache ou casse sous un effort latéral",
    "q.l32#25.r2" to "La sangle est entaillée et perd beaucoup de résistance",
    "q.l32#25.r3" to "La seule connexion cède et il ne reste plus aucune protection",
    "q.l32#25.e" to "Quatre problèmes, quatre modes de défaillance. Ils coexistent souvent, d'où un contrôle point par point plutôt qu'un « ça a l'air d'aller ».",

    "q.l32#26.p" to "Un coéquipier dit : « cette corde n'a servi qu'une saison, pas besoin de la contrôler ». Que répondez-vous ?",
    "q.l32#26.o0" to "L'usure d'une corde fixe dépend de l'exposition et de l'abrasion, pas de la durée",
    "q.l32#26.o1" to "Effectivement, pas besoin de contrôle",
    "q.l32#26.o2" to "Il suffit de changer de couleur",
    "q.l32#26.o3" to "Tant qu'elle n'est pas cassée, elle sert",
    "q.l32#26.e" to "Soleil, gel-dégel et frottement sur les arêtes s'accumulent. La fréquence de contrôle dépend de l'intensité d'usage, pas du calendrier.",

    "q.l32#27.p" to "Quel est le principe d'estimation de la longueur de corde pendant l'équipement ?",
    "q.l32#27.o0" to "Garder de la marge pour les nœuds et les connexions, plutôt long que court",
    "q.l32#27.o1" to "Exactement la longueur du tronçon",
    "q.l32#27.o2" to "Le plus court possible, pour le poids",
    "q.l32#27.o3" to "La distance à vol d'oiseau sur la carte",
    "q.l32#27.e" to "Trop courte, la corde condamne tout le tronçon ; trop longue, elle pèse simplement un peu plus. Nœuds, connexions et relais consomment de la longueur : il faut la compter.",

    "q.l32#28.p" to "Un membre doit passer un tronçon de corde fixe avec balancement latéral. Que doit-il vérifier en priorité ?",
    "q.l32#28.o0" to "Que l'ancrage encaisse un effort latéral et qu'une deuxième connexion existe",
    "q.l32#28.o1" to "La couleur de la corde",
    "q.l32#28.o2" to "La longueur de corde",
    "q.l32#28.o3" to "Son poids",
    "q.l32#28.e" to "Le balancement transforme un ancrage prévu « vers le bas » en effort latéral ; c'est ainsi que beaucoup d'ancrages s'arrachent.",

    "q.l32#29.p" to "Pourquoi prévoir des « points de retrait » sur un itinéraire équipé ?",
    "q.l32#29.o0" to "Pour pouvoir sortir en sécurité dans un tronçon si la météo ou l'état du groupe change",
    "q.l32#29.o1" to "Pour se reposer",
    "q.l32#29.o2" to "Pour stocker du matériel",
    "q.l32#29.o3" to "Pour faire des photos",
    "q.l32#29.e" to "On ne va pas au bout d'un itinéraire long à chaque fois. Le point de retrait décide s'il reste un choix quand les choses se gâtent.",
    // ---------- l33 Remontée, passage de nœud et changement de corde ----------
    "q.l33#0.p" to "Quel élément ne fait pas partie de la configuration standard pour remonter une corde fixe ?",
    "q.l33#0.o0" to "Un descendeur (en huit ou tubulaire)",
    "q.l33#0.o1" to "Un bloqueur de poignée",
    "q.l33#0.o2" to "Un étrier",
    "q.l33#0.o3" to "Un nœud autobloquant de secours",
    "q.l33#0.e" to "La montée ne demande pas de descendeur : il appartient au changement de corde et à la descente. La liste se fait selon le mouvement en cours, pas en accrochant tout le matériel.",

    "q.l33#1.p" to "Quel est le mantra du mouvement de montée ?",
    "q.l33#1.o0" to "Se lever, s'asseoir, pousser",
    "q.l33#1.o1" to "Tirer, pousser, sauter",
    "q.l33#1.o2" to "S'accroupir, sauter, attraper",
    "q.l33#1.o3" to "Pousser, tirer, s'asseoir",
    "q.l33#1.e" to "Debout sur l'étrier, le centre de gravité monte, on pousse le bloqueur de poitrine, on s'assoit, puis on pousse celui de poignée. Le bon rythme économise la moitié de l'effort.",

    "q.l33#2.p" to "Où doit se trouver le centre de gravité en montant ?",
    "q.l33#2.o0" to "Contre la corde",
    "q.l33#2.o1" to "Le plus possible vers l'extérieur",
    "q.l33#2.o2" to "En balançant de gauche à droite",
    "q.l33#2.o3" to "Le plus possible en arrière",
    "q.l33#2.e" to "Un centre de gravité qui part vers l'extérieur met le bloqueur en effort latéral, le fait dégager plus facilement et coûte beaucoup d'énergie. Être contre la corde, c'est la sécurité et l'efficacité.",

    "q.l33#3.p" to "Quelle est l'exception au principe des « deux connexions » ?",
    "q.l33#3.o0" to "L'encordement direct pour ouvrir une longueur",
    "q.l33#3.o1" to "Quand la météo est bonne",
    "q.l33#3.o2" to "De jour",
    "q.l33#3.o3" to "Sur une courte distance",
    "q.l33#3.e" to "En ouverture, la personne fait partie du système et ne peut pas ajouter un second point. En dehors de ce cas, deux connexions indépendantes à tout instant.",

    "q.l33#4.p" to "Quel est le premier principe du passage de nœud ?",
    "q.l33#4.o0" to "Créer la nouvelle connexion avant de retirer l'ancienne",
    "q.l33#4.o1" to "Retirer l'ancienne connexion avant de créer la nouvelle",
    "q.l33#4.o2" to "Travailler les deux bloqueurs en même temps",
    "q.l33#4.o3" to "Sauter le nœud directement",
    "q.l33#4.e" to "L'ordre inverse crée un instant où l'on ne tient que sur un point, voire sur aucun. Passer un nœud est un transfert de système maîtrisé.",

    "q.l33#5.p" to "Pendant le passage, les deux bloqueurs peuvent-ils quitter la corde en même temps ?",
    "q.l33#5.o0" to "Non : à tout instant, au moins un bloqueur est sur la corde et porte",
    "q.l33#5.o1" to "Oui, à condition d'aller vite",
    "q.l33#5.o2" to "Oui, à condition que quelqu'un regarde",
    "q.l33#5.o3" to "Oui, si le nœud est court",
    "q.l33#5.e" to "Les deux décrochés en même temps, c'est perdre toute connexion de progression. Mieux vaut une minute de plus à réorganiser que de tenter le coup.",

    "q.l33#6.p" to "Quelle est la première étape d'une conversion montée-descente ?",
    "q.l33#6.o0" to "Se vacher au relais avec le PAS ou une sangle",
    "q.l33#6.o1" to "Retirer d'abord le bloqueur de poignée",
    "q.l33#6.o2" to "Installer d'abord le descendeur",
    "q.l33#6.o3" to "Décrocher d'abord le bloqueur de poitrine",
    "q.l33#6.e" to "Il faut d'abord une connexion indépendante du système de montée avant de parler de démonter. C'est le point de départ commun à tous les changements de corde.",

    "q.l33#7.p" to "Une fois le descendeur installé et avant de retirer les bloqueurs, que faut-il faire ?",
    "q.l33#7.o0" to "Mettre le descendeur en charge et l'essayer",
    "q.l33#7.o1" to "Ouvrir d'abord le harnais",
    "q.l33#7.o2" to "Ranger d'abord la corde",
    "q.l33#7.o3" to "Retirer d'abord le casque",
    "q.l33#7.e" to "« Mettre en charge » est le seul moyen de confirmer que le nouveau système porte vraiment le poids du corps. Sauter cette étape, et démonter l'ancien peut mener droit à la chute.",

    "q.l33#8.p" to "En descente, à quoi sert le nœud de friction placé au-dessus du descendeur ?",
    "q.l33#8.o0" to "À bloquer automatiquement en cas de lâcher, comme secours indépendant",
    "q.l33#8.o1" to "À accélérer la descente",
    "q.l33#8.o2" to "À protéger la corde",
    "q.l33#8.o3" to "À marquer la position",
    "q.l33#8.e" to "Le nœud mord la corde dès qu'on relâche la main de freinage. C'est la seule défense à l'instant le plus dangereux : celui où la main s'ouvre.",

    "q.l33#9.p" to "Pourquoi nouer le bout de corde avant de descendre ?",
    "q.l33#9.o0" to "Pour empêcher le bout de sortir du descendeur",
    "q.l33#9.o1" to "Pour ranger la corde plus facilement",
    "q.l33#9.o2" to "Pour marquer la longueur",
    "q.l33#9.o3" to "Pour réduire l'usure",
    "q.l33#9.e" to "Si la corde est trop courte, le bout qui sort, c'est le freinage perdu instantanément. Le nœud d'arrêt est un point de contrôle obligatoire avant la descente.",

    "q.l33#10.p" to "Au passage d'un relais intermédiaire, quel est le bon ordre ?",
    "q.l33#10.o0" to "Se vacher au relais, déplacer les bloqueurs, puis libérer le relais",
    "q.l33#10.o1" to "Déplacer les bloqueurs, puis se vacher",
    "q.l33#10.o2" to "Passer directement, sans se vacher",
    "q.l33#10.o3" to "Libérer le relais, puis déplacer",
    "q.l33#10.e" to "Au relais, la corde est contrainte par le mousqueton : peu de place, gestes vite déformés. Créer d'abord une connexion indépendante donne une marge d'erreur.",

    "q.l33#11.p" to "Que faire quand la corde se coince ?",
    "q.l33#11.o0" to "Changer l'angle de tirage ou tirer de côté, sans se placer sous la corde et tirer fort",
    "q.l33#11.o1" to "Se placer juste en dessous et tirer fort",
    "q.l33#11.o2" to "Tirer de tout son poids",
    "q.l33#11.o3" to "Couper directement",
    "q.l33#11.e" to "Tirer fort pile en dessous, c'est s'exposer au retour de corde ou aux chutes de pierres, et souvent coincer le nœud plus profond. Changer l'angle est le premier geste utile.",

    "q.l33#12.p" to "En descente sur double, de quel côté tire-t-on pour récupérer la corde ?",
    "q.l33#12.o0" to "Du côté où le frottement est le plus faible",
    "q.l33#12.o1" to "Du côté où le frottement est le plus fort",
    "q.l33#12.o2" to "Peu importe le côté",
    "q.l33#12.o3" to "Des deux côtés en même temps",
    "q.l33#12.e" to "Tirer du côté le moins frotté ramène la corde plus facilement et use moins la gaine. À condition que le bout soit noué et que rien ne s'accroche.",

    "q.l33#13.p" to "Pour remonter une corde fixe, quels matériels doivent être sur soi ?",
    "q.l33#13.o0" to "Bloqueurs de poignée et de poitrine (ou un second autobloquant)",
    "q.l33#13.o1" to "Un étrier",
    "q.l33#13.o2" to "Un nœud autobloquant de secours et le PAS",
    "q.l33#13.o3" to "Un casque",
    "q.l33#13.e" to "Les quatre forment le système complet de montée et de secours. S'il en manque un, le passage de nœud et le changement de corde imposent de travailler sur un seul point.",

    "q.l33#14.p" to "Quelles sont les erreurs les plus fréquentes lors du changement de corde ?",
    "q.l33#14.o0" to "Démonter l'ancien système avant de construire le nouveau",
    "q.l33#14.o1" to "Retirer les bloqueurs sans avoir essayé le descendeur en charge",
    "q.l33#14.o2" to "Décrocher les deux bloqueurs en même temps",
    "q.l33#14.o3" to "Se vacher au relais avant de changer de corde",
    "q.l33#14.e" to "Les trois premiers sont des erreurs d'ordre. Le dernier est justement la bonne pratique : se vacher d'abord évite les trois autres.",

    "q.l33#15.p" to "Quels contrôles sont obligatoires avant de descendre ?",
    "q.l33#15.o0" to "Sens de passage de la corde dans le descendeur correct",
    "q.l33#15.o1" to "Nœud de friction de secours en place et efficace",
    "q.l33#15.o2" to "Bout de corde noué",
    "q.l33#15.o3" to "Longueur suffisante pour atteindre le relais suivant",
    "q.l33#15.e" to "S'il manque un de ces quatre, le contrôle peut être perdu. Cette série se fait entièrement avant de libérer l'assurance.",

    "q.l33#16.p" to "Quels moyens peuvent servir de « nouvelle connexion » au passage d'un nœud ?",
    "q.l33#16.o0" to "PAS ou sangle vacher au-dessus du nœud",
    "q.l33#16.o1" to "Vacher sur un ancrage proche",
    "q.l33#16.o2" to "Installer un second bloqueur au-dessus",
    "q.l33#16.o3" to "Tenir la corde à la main",
    "q.l33#16.e" to "Tenir à la main n'est pas une connexion : la main s'ouvre et tout disparaît. Les trois premiers créent un point porteur indépendant de l'ancien système.",

    "q.l33#17.p" to "Remettez dans l'ordre les étapes du passage d'un nœud en montée.",
    "q.l33#17.o0" to "Ralentir avant le nœud, observer sa position et le brin au-dessus",
    "q.l33#17.o1" to "Se vacher avec le PAS ou une sangle au-dessus du nœud ou sur un ancrage proche",
    "q.l33#17.o2" to "Installer un second bloqueur ou un autobloquant au-dessus, puis se lever pour transférer le poids",
    "q.l33#17.o3" to "Retirer le bloqueur du bas et l'installer au-dessus du nœud",
    "q.l33#17.o4" to "Vérifier que la nouvelle connexion porte, puis libérer le PAS",
    "q.l33#17.e" to "Le cœur de la méthode est « toujours un point de plus ». Sauter une étape crée un moment où l'on porte sur un seul point, voire sur aucun.",

    "q.l33#18.p" to "Remettez dans l'ordre la conversion montée-descente.",
    "q.l33#18.o0" to "Se vacher au relais (PAS ou sangle)",
    "q.l33#18.o1" to "Installer le descendeur et passer la corde correctement",
    "q.l33#18.o2" to "Mettre le descendeur en charge et l'essayer",
    "q.l33#18.o3" to "Retirer le bloqueur de poignée, garder celui de poitrine ou le secours",
    "q.l33#18.o4" to "Retirer l'autre bloqueur et vérifier le descendeur comme le secours",
    "q.l33#18.o5" to "Libérer le PAS et commencer à descendre",
    "q.l33#18.e" to "L'ordre est fixe, aucune improvisation. Chaque étape garantit « au moins une connexion fiable ».",

    "q.l33#19.p" to "Remettez dans l'ordre la conversion descente-montée.",
    "q.l33#19.o0" to "Installer un autobloquant ou un bloqueur au-dessus du descendeur et le relier au harnais",
    "q.l33#19.o1" to "Se lever et transférer le poids sur l'autobloquant",
    "q.l33#19.o2" to "Installer un second bloqueur ou l'étrier et vérifier qu'il porte",
    "q.l33#19.o3" to "Retirer le descendeur",
    "q.l33#19.o4" to "Commencer à monter",
    "q.l33#19.e" to "Le point clé est la troisième étape : le nouveau système doit déjà porter avant qu'on retire le descendeur.",

    "q.l33#20.p" to "Remettez dans l'ordre le passage d'un nœud en descente.",
    "q.l33#20.o0" to "Au-dessus du nœud, se vacher sur le nœud ou sur l'ancrage avec le PAS",
    "q.l33#20.o1" to "Déplacer le descendeur sous le nœud, retendre et essayer en charge",
    "q.l33#20.o2" to "Libérer le PAS et continuer la descente",
    "q.l33#20.e" to "Quand le nœud est trop gros pour passer directement, on déplace d'abord le secours sous le nœud, puis le descendeur : entre les deux transferts, une connexion fiable reste toujours en place.",

    "q.l33#21.p" to "En montant sur corde fixe, il faut maintenir ______ point(s) de connexion indépendant(s) à tout instant.",
    "q.l33#21.a0" to "2",
    "q.l33#21.a1" to "deux",
    "q.l33#21.e" to "Deux connexions sont la règle dure du travail sur corde fixe. La seule exception est l'encordement direct pour ouvrir.",

    "q.l33#22.p" to "Pour passer de la montée à la descente, il faut d'abord se vacher sur ______, puis retirer les bloqueurs.",
    "q.l33#22.a0" to "un ancrage",
    "q.l33#22.a1" to "le relais",
    "q.l33#22.a2" to "le relais intermédiaire",
    "q.l33#22.e" to "Obtenir d'abord une connexion qui ne dépend pas de l'ancien système, c'est le point de départ de tout changement de corde.",

    "q.l33#23.p" to "Le nœud de friction de secours placé au-dessus du descendeur prend souvent la forme d'un prussik ou d'un ______.",
    "q.l33#23.a0" to "autoblock",
    "q.l33#23.a1" to "nœud français",
    "q.l33#23.a2" to "nœud de friction",
    "q.l33#23.e" to "Les deux se bloquent dès qu'on lâche. Monté à l'envers ou trop long, le nœud ne remplit plus sa fonction : il faut le répéter jusqu'à pouvoir le vérifier les yeux fermés.",

    "q.l33#24.p" to "Associez chaque étape à son principe clé.",
    "q.l33#24.l0" to "Passage de nœud",
    "q.l33#24.l1" to "Passage de relais",
    "q.l33#24.l2" to "Montée vers descente",
    "q.l33#24.l3" to "Descente vers montée",
    "q.l33#24.r0" to "Créer la nouvelle connexion avant de retirer l'ancienne",
    "q.l33#24.r1" to "Se vacher au relais avant de déplacer le matériel",
    "q.l33#24.r2" to "Vacher, descendeur, essai, puis retirer les bloqueurs",
    "q.l33#24.r3" to "Ne retirer le descendeur que lorsque le nouveau système porte",
    "q.l33#24.e" to "La structure commune des quatre est « établir, transférer, démonter ». Retenir la structure résiste mieux à l'oubli que retenir les étapes.",

    "q.l33#25.p" to "Associez chaque lettre du contrôle ABCDE à son contenu.",
    "q.l33#25.l0" to "A — ancrages",
    "q.l33#25.l1" to "B — backup",
    "q.l33#25.l2" to "C — connexions",
    "q.l33#25.l3" to "E — échappatoire",
    "q.l33#25.r0" to "Deux points indépendants, répartis, direction d'effort correcte, arêtes protégées",
    "q.l33#25.r1" to "PAS ou autobloquant en place, chaque matériel avec son secours indépendant",
    "q.l33#25.r2" to "Mousquetons fermés, nœuds serrés, bout de corde noué",
    "q.l33#25.r3" to "Point de retrait le plus proche connu, longueur suffisante, communication claire",
    "q.l33#25.e" to "La valeur de cette liste est de la passer avant chaque montée sur corde. Elle ne remplace pas le jugement, mais elle arrête la grande majorité des erreurs basiques.",

    "q.l33#26.p" to "Un coéquipier compte « retirer un bloqueur puis remettre l'autre tout de suite » au passage du nœud. Que lui dites-vous ?",
    "q.l33#26.o0" to "Il faut d'abord créer une connexion PAS ou ancrage ; aucun moment sans connexion n'est permis",
    "q.l33#26.o1" to "Il suffit d'aller vite",
    "q.l33#26.o2" to "C'est acceptable de jour",
    "q.l33#26.o3" to "C'est acceptable sur un nœud court",
    "q.l33#26.e" to "« Tout de suite » ne laisse aucune tolérance en cas de faux geste. La marge du passage de nœud doit être créée par une troisième connexion.",

    "q.l33#27.p" to "À un relais, la corde doit sortir du mousqueton puis y retourner. Que faites-vous ?",
    "q.l33#27.o0" to "Se vacher d'abord, manipuler la corde ensuite, libérer le secours en dernier",
    "q.l33#27.o1" to "Sortir la corde d'abord, puis se vacher",
    "q.l33#27.o2" to "Demander à quelqu'un de tenir la corde",
    "q.l33#27.o3" to "Ouvrir directement le mousqueton",
    "q.l33#27.e" to "À l'instant où la corde sort, la personne peut dépendre entièrement de l'ancienne connexion. Créer une connexion indépendante d'abord donne du sens à la manipulation.",

    "q.l33#28.p" to "Pourquoi le changement de corde est-il l'étape la plus accidentogène du travail sur corde fixe ?",
    "q.l33#28.o0" to "Parce qu'il faut transférer entre démonter l'ancien système et construire le nouveau, avec la plus faible marge d'erreur",
    "q.l33#28.o1" to "Parce qu'il y a beaucoup de matériel",
    "q.l33#28.o2" to "Parce que c'est très fatigant",
    "q.l33#28.o3" to "Parce qu'il faut être deux",
    "q.l33#28.e" to "Passer un nœud, c'est ajouter un point ; changer de corde, c'est changer tout un système. Toute erreur d'ordre fait perdre la connexion.",
    // ---------- l34 Progression sur glacier et choix d'itinéraire ----------
    "q.l34#0.p" to "Sur un glacier, quel terrain est le plus dangereux et le plus sous-estimé ?",
    "q.l34#0.o0" to "Les crevasses et les ponts de neige recouverts",
    "q.l34#0.o1" to "Les cordons morainiques",
    "q.l34#0.o2" to "Les vastes étendues de neige plates",
    "q.l34#0.o3" to "Les pentes d'éboulis sur les côtés",
    "q.l34#0.e" to "Recouverte de neige fraîche, une crevasse ressemble à une surface banale. Dans les accidents de glacier, la chute en crevasse est la plus fréquente.",

    "q.l34#1.p" to "Où apparaissent le plus souvent les crevasses transversales ?",
    "q.l34#1.o0" to "Aux changements de pente (haut de pente, pied de pente, franchissement de ressaut)",
    "q.l34#1.o1" to "Exactement au milieu du glacier",
    "q.l34#1.o2" to "À l'extrémité aval du glacier",
    "q.l34#1.o3" to "Sur la moraine",
    "q.l34#1.e" to "Un changement brutal de pente signifie étirement ou compression, et c'est là que les crevasses s'ouvrent. Observer la zone du haut de pente avant de monter est l'habitude la plus utile.",

    "q.l34#2.p" to "Les crevasses longitudinales fréquentes sur les côtés du glacier viennent de quoi ?",
    "q.l34#2.o0" to "De l'étirement dû au frottement du glacier contre le terrain sur les côtés",
    "q.l34#2.o1" to "De chutes de pierres",
    "q.l34#2.o2" to "Du piétinement des alpinistes",
    "q.l34#2.o3" to "De l'eau de fonte",
    "q.l34#2.e" to "Le centre s'écoule plus vite que les bords ; cette différence de vitesse crée cisaillement et étirement. Suivre l'axe du glacier est donc en général plus sûr que longer le bord.",

    "q.l34#3.p" to "En progression encordée, quelle longueur de corde prend-on en général entre deux personnes ?",
    "q.l34#3.o0" to "8–10 m",
    "q.l34#3.o1" to "2–3 m",
    "q.l34#3.o2" to "20–30 m",
    "q.l34#3.o3" to "Le plus près possible",
    "q.l34#3.e" to "Trop courte, la chute d'un seul entraîne le coéquipier ; trop longue, la distance de blocage et la difficulté de sauvetage augmentent. En zone dense, on raccourcit mais sans descendre sous 6–8 m.",

    "q.l34#4.p" to "Pourquoi fait-on des nœuds dans la corde en progression encordée ?",
    "q.l34#4.o0" to "Pour limiter la profondeur de chute, ajouter du frottement au blocage et faciliter la prise en sauvetage",
    "q.l34#4.o1" to "Pour empêcher la corde de vriller",
    "q.l34#4.o2" to "Pour marquer la longueur",
    "q.l34#4.o3" to "Pour l'esthétique",
    "q.l34#4.e" to "Le nœud crée une résistance et un point de blocage au bord de la crevasse, ce qui réduit nettement la profondeur de chute. Le prix est un tirage un peu plus pénible, mais cela vaut la peine.",

    "q.l34#5.p" to "Quel est le principal avantage d'une cordée de trois par rapport à une cordée de deux ?",
    "q.l34#5.o0" to "Si l'un tombe, deux bloquent et l'un peut préparer le système de sauvetage : bien plus de marge",
    "q.l34#5.o1" to "On avance plus vite",
    "q.l34#5.o2" to "La corde est plus légère",
    "q.l34#5.o3" to "Pas besoin de nœuds",
    "q.l34#5.e" to "À deux, celui qui bloque ne peut presque plus manipuler un système de sauvetage ; à trois seulement existe la répartition « bloquer et construire ».",

    "q.l34#6.p" to "Pour juger de la fiabilité d'un pont de neige, que regarde-t-on en premier ?",
    "q.l34#6.o0" to "La couleur et les affaissements : sombre, bleuté ou avec des fissures rayonnantes signale une faible épaisseur",
    "q.l34#6.o1" to "Le nombre de traces",
    "q.l34#6.o2" to "Si la surface est plane",
    "q.l34#6.o3" to "S'il y a du vent",
    "q.l34#6.e" to "La résistance d'un pont dépend de sa portée et de l'épaisseur du manteau. Couleur et affaissement sont les indices les plus directs ; les traces disent seulement que d'autres sont passés, pas que c'est sûr.",

    "q.l34#7.p" to "Quel est le moment le plus favorable pour franchir une zone de crevasses dense ?",
    "q.l34#7.o0" to "Tôt le matin ou pendant les heures froides de la nuit",
    "q.l34#7.o1" to "À midi",
    "q.l34#7.o2" to "L'après-midi",
    "q.l34#7.o3" to "N'importe quand, c'est pareil",
    "q.l34#7.e" to "Par basse température, les ponts de neige sont les plus solides ; après la fonte de l'après-midi, leur résistance chute nettement. Le programme doit être construit autour de ce point.",

    "q.l34#8.p" to "Quelle est la bonne façon de traverser une zone de séracs ?",
    "q.l34#8.o0" to "Passer vite, garder les distances, casque, sans s'arrêter dans la zone",
    "q.l34#8.o1" to "Traverser lentement, encordés",
    "q.l34#8.o2" to "S'y reposer",
    "q.l34#8.o3" to "Prendre des photos",
    "q.l34#8.e" to "Le risque en zone de séracs est la chute d'un bloc, pas la crevasse : cela tombe en masse. Moins on reste, mieux c'est, et on n'y attend pas ses coéquipiers.",

    "q.l34#9.p" to "Sur un glacier, dans quel état doit rester la corde ?",
    "q.l34#9.o0" to "Légèrement tendue, ni traînant au sol ni trop molle",
    "q.l34#9.o1" to "Complètement détendue, traînant sur la neige",
    "q.l34#9.o2" to "Très tendue",
    "q.l34#9.o3" to "Enroulée et portée à la main",
    "q.l34#9.e" to "Une corde molle provoque un choc au moment de la chute, une corde tendue tire sur les autres. Tension modérée plus nœuds dans la corde est la combinaison la plus stable.",

    "q.l34#10.p" to "Face à une crevasse bien ouverte, quelle est la première réponse ?",
    "q.l34#10.o0" to "Contourner, chercher un passage plus étroit ou déjà ponté",
    "q.l34#10.o1" to "Sauter par-dessus",
    "q.l34#10.o2" to "Se placer sur le bord pour regarder la profondeur",
    "q.l34#10.o3" to "L'élargir au piolet",
    "q.l34#10.e" to "Le premier principe du choix d'itinéraire sur glacier est de contourner. Sauter et se pencher sur le bord sont les deux façons les plus fréquentes de se blesser soi-même.",

    "q.l34#11.p" to "Pourquoi dit-on que « suivre l'axe du glacier » est en général plus sûr ?",
    "q.l34#11.o0" to "Les bandes d'étirement latérales portent plus de crevasses ; au centre, les efforts sont plus homogènes",
    "q.l34#11.o1" to "La neige est plus épaisse au centre",
    "q.l34#11.o2" to "Le centre est plus court",
    "q.l34#11.o3" to "Il y a plus de monde au centre",
    "q.l34#11.e" to "Au centre, les crevasses sont en général moins nombreuses et les ponts plus courts. Mais en zone de séracs et aux ressauts, il faut juger autrement, sans appliquer la règle mécaniquement.",

    "q.l34#12.p" to "Quels éléments entrent dans l'évaluation du risque d'un itinéraire glaciaire ?",
    "q.l34#12.o0" to "La densité de crevasses et l'état des ponts de neige",
    "q.l34#12.o1" to "Le risque de chute de séracs et de blocs de glace",
    "q.l34#12.o2" to "La température du jour et l'ensoleillement (qui jouent sur la solidité des ponts)",
    "q.l34#12.o3" to "Le nombre de personnes et le mode d'encordement",
    "q.l34#12.e" to "Les quatre se commandent l'un l'autre : la température décide des ponts, l'effectif décide de l'encordement, l'encordement décide des conséquences d'une chute. L'évaluation consiste à les regarder ensemble.",

    "q.l34#13.p" to "Quels signes suggèrent qu'un pont de neige peut être douteux ?",
    "q.l34#13.o0" to "La surface du pont s'affaisse nettement",
    "q.l34#13.o1" to "La couleur est sombre ou bleutée",
    "q.l34#13.o2" to "Des fissures rayonnantes partent du bord",
    "q.l34#13.o3" to "Le pont est recouvert de neige fraîche mais sonne creux dessous",
    "q.l34#13.e" to "Les quatre traduisent un manque de résistance sous des formes différentes. Quand cela sonne creux, il faut reculer, pas avancer d'un pas de plus.",

    "q.l34#14.p" to "Sur un glacier, quelles pratiques augmentent le risque ?",
    "q.l34#14.o0" to "Un espacement d'encordement trop court",
    "q.l34#14.o1" to "Pas de nœuds dans la corde",
    "q.l34#14.o2" to "S'arrêter pour se reposer en zone de séracs",
    "q.l34#14.o3" to "Longer le bord du glacier",
    "q.l34#14.e" to "Les quatre augmentent respectivement le risque d'entraînement, d'ensevelissement profond, de chute de glace et de crevasse latérale. Ce sont des choix évitables.",

    "q.l34#15.p" to "Que faut-il mettre au point avant qu'un groupe franchisse une zone de crevasses dense ?",
    "q.l34#15.o0" to "L'espacement et la façon de faire les nœuds",
    "q.l34#15.o1" to "L'ordre de passage et les distances",
    "q.l34#15.o2" to "La règle face à un pont de neige (sonder, contourner, reculer)",
    "q.l34#15.o3" to "Qui a le sac le plus lourd",
    "q.l34#15.e" to "Les trois premiers décident comment le groupe réagit en cas de problème. S'accorder avant est bien plus sûr que d'en discuter au bord de la crevasse.",

    "q.l34#16.p" to "Remettez dans l'ordre le franchissement d'un pont de neige douteux.",
    "q.l34#16.o0" to "S'arrêter, observer couleur, affaissement et fissures alentour",
    "q.l34#16.o1" to "Sonder l'épaisseur du pont au piolet ou à la sonde",
    "q.l34#16.o2" to "Après avoir vérifié qu'un contournement est impossible, raccourcir l'encordement et passer un par un",
    "q.l34#16.o3" to "Une fois tout le monde passé, le dernier libère l'assurance et rejoint",
    "q.l34#16.e" to "Le sondage se fait avant que quiconque monte sur le pont. Passer un par un signifie « ne porter qu'une personne à la fois » : c'est l'organisation la plus importante.",

    "q.l34#17.p" to "Dans quel ordre construit-on un programme sur glacier ?",
    "q.l34#17.o0" to "D'abord la carte de l'itinéraire et la répartition des crevasses",
    "q.l34#17.o1" to "Fixer la plage horaire de franchissement de la zone de crevasses (matin ou nuit)",
    "q.l34#17.o2" to "Déterminer le mode d'encordement et l'espacement",
    "q.l34#17.o3" to "Reconfirmer météo et température avant de partir",
    "q.l34#17.e" to "Terrain, puis horaire, puis encordement, enfin vérification météo. L'ordre inverse produit exactement le cas « on suit le programme, mais à la mauvaise heure ».",

    "q.l34#18.p" to "Un coéquipier tombe en crevasse : dans quel ordre faire les trois premières choses ?",
    "q.l34#18.o0" to "Bloquer immédiatement et maintenir la corde en tension",
    "q.l34#18.o1" to "Vérifier que sa propre position est sûre et s'assurer",
    "q.l34#18.o2" to "Appeler les coéquipiers pour préparer le système de sauvetage",
    "q.l34#18.o3" to "Appliquer la procédure de sauvetage en cordée",
    "q.l34#18.e" to "Le blocage est la seule chose qui ne peut pas attendre ; viennent ensuite l'assurance et le système de sauvetage. La procédure détaillée figure dans la leçon sur l'auto-sauvetage et le sauvetage en cordée.",

    "q.l34#19.p" to "L'espacement habituel entre deux personnes d'une cordée sur glacier est ______–10 m.",
    "q.l34#19.a0" to "8",
    "q.l34#19.e" to "8–10 m est la plage courante. On raccourcit en zone dense, mais pas au point qu'une chute emporte toute la cordée.",

    "q.l34#20.p" to "Pour juger la solidité d'un pont de neige, outre la couleur et l'affaissement, il faut ______ au piolet.",
    "q.l34#20.a0" to "sonder",
    "q.l34#20.a1" to "tâter",
    "q.l34#20.a2" to "faire une pression",
    "q.l34#20.e" to "Le sondage se fait avant que quiconque monte sur le pont. On enfonce légèrement la pointe pour sentir l'épaisseur de neige et le vide éventuel en dessous.",

    "q.l34#21.p" to "Le franchissement d'une zone de crevasses dense se place de préférence ______, quand les ponts de neige sont les plus solides.",
    "q.l34#21.a0" to "tôt le matin",
    "q.l34#21.a1" to "le matin",
    "q.l34#21.a2" to "avant l'aube",
    "q.l34#21.e" to "Le froid rend les ponts plus durs et plus solides ; après la fonte de l'après-midi, la résistance baisse nettement.",

    "q.l34#22.p" to "Associez chaque type de crevasse à sa position typique.",
    "q.l34#22.l0" to "Crevasse transversale",
    "q.l34#22.l1" to "Crevasse longitudinale",
    "q.l34#22.l2" to "Crevasse oblique",
    "q.l34#22.l3" to "Séracs et zone de séracs",
    "q.l34#22.r0" to "Aux changements de pente (haut de pente, pied de pente, ressaut)",
    "q.l34#22.r1" to "Dans les bandes d'étirement entre le glacier et le terrain sur les côtés",
    "q.l34#22.r2" to "Là où le glacier tourne ou change de largeur",
    "q.l34#22.r3" to "Sous une cascade de glace raide, avec un risque élevé de chute de blocs",
    "q.l34#22.e" to "La cause d'une crevasse est l'étirement. Retenir cela permet d'anticiper où le tronçon suivant va casser.",

    "q.l34#23.p" to "Associez chaque signe sur un pont de neige à la réaction correspondante.",
    "q.l34#23.l0" to "Surface affaissée",
    "q.l34#23.l1" to "Couleur sombre ou bleutée",
    "q.l34#23.l2" to "Fissures rayonnantes",
    "q.l34#23.l3" to "Sonne creux dessous",
    "q.l34#23.r0" to "Baisser la priorité de passage, chercher d'abord un contournement",
    "q.l34#23.r1" to "Signale un manteau mince : ne pas sonder seul dessus",
    "q.l34#23.r2" to "La structure est déjà atteinte : passage interdit",
    "q.l34#23.r3" to "Reculer immédiatement et changer d'itinéraire",
    "q.l34#23.e" to "Les quatre signes vont du moins au plus grave. Dès que l'un apparaît, il faut penser « contourner » avant « passer plus vite ».",

    "q.l34#24.p" to "Associez chaque rôle à sa fonction (cordée de trois).",
    "q.l34#24.l0" to "Le premier (ouvreur, traceur)",
    "q.l34#24.l1" to "Le deuxième (au milieu)",
    "q.l34#24.l2" to "Le dernier",
    "q.l34#24.r0" to "Juger l'itinéraire et les ponts de neige, tenir le rythme",
    "q.l34#24.r1" to "Faire le lien entre l'avant et l'arrière, transmettre les consignes",
    "q.l34#24.r2" to "Gérer le rab de corde, surveiller l'arrière et l'état du bout",
    "q.l34#24.e" to "La répartition d'une cordée de trois se dit avant de partir. Le milieu n'est pas « la place la plus sûre » : c'est le relais d'information.",

    "q.l34#25.p" to "Quelqu'un veut « mettre un coup de pied pour voir si le pont tient ». Que faites-vous ?",
    "q.l34#25.o0" to "L'arrêter et passer au sondage au piolet ou à la sonde, ou contourner directement",
    "q.l34#25.o1" to "Le laisser essayer, on est encordés de toute façon",
    "q.l34#25.o2" to "Le laisser passer seul en premier",
    "q.l34#25.o3" to "Courir pour réduire le temps de charge",
    "q.l34#25.e" to "Une personne est une charge concentrée de plusieurs dizaines de kilos : un pas peut suffire à percer. On sonde avec un outil, pas avec son poids.",

    "q.l34#26.p" to "La température monte à midi et la zone de crevasses prévue est encore à deux heures. Que faites-vous ?",
    "q.l34#26.o0" to "Réévaluer : attendre le rafraîchissement du soir ou prendre l'itinéraire de repli",
    "q.l34#26.o1" to "Continuer comme prévu",
    "q.l34#26.o2" to "Accélérer pour passer vite",
    "q.l34#26.o3" to "Attendre sur place jusqu'à demain",
    "q.l34#26.e" to "La résistance des ponts est fonction du temps. Le programme doit être construit autour de la plage la plus solide, pas l'inverse : on n'adapte pas la montagne au plan.",

    "q.l34#27.p" to "Pourquoi une zone de séracs n'est-elle pas un bon point d'attente pour une cordée ?",
    "q.l34#27.o0" to "Un sérac tombe en bloc entier : attendre allonge le temps d'exposition",
    "q.l34#27.o1" to "Parce qu'il y a du vent",
    "q.l34#27.o2" to "Parce que le sol est irrégulier",
    "q.l34#27.o3" to "Parce qu'il n'y a pas de réseau",
    "q.l34#27.e" to "Le risque de crevasse se partage par l'encordement ; le risque de chute de glace ne se réduit qu'en diminuant le temps d'exposition. Les deux se traitent dans des directions opposées.",

    "q.l34#28.p" to "Quelle est la bonne approche du rythme sur glacier ?",
    "q.l34#28.o0" to "Un pas régulier et constant, en gardant l'espacement, est plus sûr que des à-coups",
    "q.l34#28.o1" to "Plus vite, plus sûr",
    "q.l34#28.o2" to "Plus lent, plus sûr",
    "q.l34#28.o3" to "Chacun à son rythme, selon sa forme",
    "q.l34#28.e" to "Les à-coups font sans cesse varier la tension de la corde et créent des chocs. Sur glacier, l'unité de rythme est à la fois une question de sécurité et d'efficacité.",

    "q.l34#29.p" to "Quand on monte sur un glacier pour la première fois, que faut-il travailler en priorité ?",
    "q.l34#29.o0" to "La progression encordée, le contrôle de l'espacement et la position de blocage, sur un terrain sûr",
    "q.l34#29.o1" to "Courir plus vite",
    "q.l34#29.o2" to "Franchir une crevasse seul",
    "q.l34#29.o3" to "Le travail en hauteur",
    "q.l34#29.e" to "La position de blocage et la sensation d'espacement doivent devenir des réflexes sur terrain sûr ; sinon, au moment de la vraie chute, il est trop tard.",
    // ---------- l35 Ensevelissement : fenêtre de survie et ordre sur place ----------
    "q.l35#0.p" to "Quelle est la première cause de décès lors d'un ensevelissement par avalanche ?",
    "q.l35#0.o0" to "L'asphyxie (65–100 %)",
    "q.l35#0.o1" to "Les traumatismes",
    "q.l35#0.o2" to "L'hypothermie",
    "q.l35#0.o3" to "L'hémorragie",
    "q.l35#0.e" to "Ce point décide directement de l'ordre des gestes : d'abord les voies aériennes et la ventilation, ensuite la circulation et le réchauffement.",

    "q.l35#1.p" to "Ensevelissement complet et ensevelissement partiel : quels taux de survie donne la synthèse de 2023 ?",
    "q.l35#1.o0" to "Environ 48 % et 96 %",
    "q.l35#1.o1" to "Environ 80 % et 90 %",
    "q.l35#1.o2" to "Environ 20 % et 60 %",
    "q.l35#1.o3" to "Environ 50 % dans les deux cas",
    "q.l35#1.e" to "Les deux chiffres diffèrent de plus du double : avoir la tête dehors ou être entièrement recouvert, ce ne sont pas du tout les mêmes situations.",

    "q.l35#2.p" to "La « phase de survie » de la courbe correspond à peu près à quelle durée après l'ensevelissement ?",
    "q.l35#2.o0" to "Les 18 premières minutes",
    "q.l35#2.o1" to "Les 5 premières minutes",
    "q.l35#2.o2" to "De 18 à 35 minutes",
    "q.l35#2.o3" to "Au-delà de 90 minutes",
    "q.l35#2.e" to "Pendant cette phase, les décès viennent surtout des traumatismes et les voies aériennes sont généralement libres. C'est pourquoi les 18 minutes sont sans cesse rappelées.",

    "q.l35#3.p" to "Quelle est la caractéristique de la « phase d'asphyxie » sur la courbe ?",
    "q.l35#3.o0" to "La survie chute brutalement : c'est la fenêtre de secours la plus tendue",
    "q.l35#3.o1" to "La courbe est plate",
    "q.l35#3.o2" to "La survie remonte",
    "q.l35#3.o3" to "Elle n'a rien à voir avec l'hypothermie",
    "q.l35#3.e" to "La chute entre 18 et 35 minutes vient de l'obstruction des voies aériennes par la neige et de l'épuisement de l'oxygène de la poche d'air. La valeur du secours par les coéquipiers tient presque entièrement dans cet intervalle.",

    "q.l35#4.p" to "La « phase de latence » (environ 35 à 90 minutes) est relativement plate. Pourquoi ?",
    "q.l35#4.o0" to "Ceux qui ont une poche d'air et des voies libres entrent en protection hypothermique, avec un métabolisme ralenti",
    "q.l35#4.o1" to "La neige fond",
    "q.l35#4.o2" to "Les secours arrivent",
    "q.l35#4.o3" to "Les traumatismes guérissent",
    "q.l35#4.e" to "Ici l'hypothermie protège au lieu de menacer. C'est aussi pourquoi on ne peut pas assimiler « enseveli longtemps » à « aucune chance ».",

    "q.l35#5.p" to "Quelle part des décès par avalanche est due à l'hypothermie ?",
    "q.l35#5.o0" to "0–4 %",
    "q.l35#5.o1" to "20–30 %",
    "q.l35#5.o2" to "50 %",
    "q.l35#5.o3" to "Presque la totalité",
    "q.l35#5.e" to "La proportion est faible, mais des cas existent. Cela rappelle l'ordre : d'abord ventiler, ensuite réchauffer, jamais l'inverse.",

    "q.l35#6.p" to "Dans les 0 à 2 minutes après l'avalanche, quelle est l'action prioritaire ?",
    "q.l35#6.o0" to "Vérifier le risque d'avalanche secondaire, désigner un guetteur, noter l'heure et le dernier point vu",
    "q.l35#6.o1" to "Commencer à creuser immédiatement",
    "q.l35#6.o2" to "Prendre des photos",
    "q.l35#6.o3" to "Appeler la famille",
    "q.l35#6.e" to "Sans guetteur, l'équipe de secours peut devenir la deuxième victime ; sans relevé d'heure, la règle des 60 minutes devient inapplicable.",

    "q.l35#7.p" to "Quel est l'objectif de la phase de 2 à 10 minutes ?",
    "q.l35#7.o0" to "Entrer en contact avec la personne le plus vite possible, pas dégager toute la neige",
    "q.l35#7.o1" to "Creuser un couloir réglementaire",
    "q.l35#7.o2" to "Ranger le matériel",
    "q.l35#7.o3" to "Attendre les secours professionnels",
    "q.l35#7.e" to "Atteindre le visage permet de commencer à ventiler plusieurs minutes avant le dégagement complet, et dans la phase d'asphyxie ces minutes sont une question de vie ou de mort.",

    "q.l35#8.p" to "Une fois le visage atteint, quel est le bon ordre des 60 premières secondes ?",
    "q.l35#8.o0" to "Dégager la neige et les morceaux de glace de la bouche et du nez, puis vérifier les signes vitaux, puis ventiler immédiatement en l'absence de respiration",
    "q.l35#8.o1" to "Sortir d'abord le corps, puis dégager le visage",
    "q.l35#8.o2" to "Photographier d'abord, puis secourir",
    "q.l35#8.o3" to "Faire boire de l'eau chaude",
    "q.l35#8.e" to "Dégager les voies aériennes avant tout le reste. Tirer la personne directement risque d'aggraver une lésion rachidienne et d'enfoncer de la neige dans la bouche.",

    "q.l35#9.p" to "« 25 % de survie à 45 minutes, contre 18 % à 40 minutes » : comment le comprendre ?",
    "q.l35#9.o0" to "C'est une fluctuation due au faible effectif et à la proportion variable de poches d'air, pas un rebond de la courbe",
    "q.l35#9.o1" to "Cela signifie que 45 minutes est plus sûr",
    "q.l35#9.o2" to "Cela signifie qu'il faut attendre 45 minutes",
    "q.l35#9.o3" to "Les données sont fausses",
    "q.l35#9.e" to "Enseigner une tendance, pas une promesse sur un point isolé. Prendre une fluctuation pour une loi mène à des conclusions absurdes.",

    "q.l35#10.p" to "Toutes les victimes d'un ensevelissement complet paraissent normales après le dégagement. Que faire ?",
    "q.l35#10.o0" to "Les envoyer quand même à l'hôpital pour observation",
    "q.l35#10.o1" to "Les renvoyer directement au camp",
    "q.l35#10.o2" to "Continuer la sortie du jour",
    "q.l35#10.o3" to "Les faire descendre à pied",
    "q.l35#10.e" to "Les conséquences du manque d'oxygène et de l'hypothermie peuvent être différées. L'observation et l'évaluation demandent du matériel et du temps, ce qu'un camp ne permet pas.",

    "q.l35#11.p" to "Quelles informations faut-il absolument relever sur un site d'avalanche ?",
    "q.l35#11.o0" to "L'heure du témoignage ou la dernière heure connue",
    "q.l35#11.o1" to "Le dernier point vu",
    "q.l35#11.o2" to "Le nombre de personnes ensevelies",
    "q.l35#11.o3" to "Le nom des sauveteurs",
    "q.l35#11.e" to "Les trois premiers décident directement de la zone de recherche et des choix médicaux. Le nom des sauveteurs relève du compte rendu et n'influence pas les décisions sur place.",

    "q.l35#12.p" to "Quels aspects faut-il traiter en même temps après le dégagement ?",
    "q.l35#12.o0" to "Protection du rachis, sans mouvements brusques",
    "q.l35#12.o1" to "Isolation de tout le corps, retrait des vêtements mouillés, isolation du sol",
    "q.l35#12.o2" to "Surveillance continue du rythme cardiaque et de la température centrale",
    "q.l35#12.o3" to "Faire lever la victime pour qu'elle bouge",
    "q.l35#12.e" to "Les trois premiers sont le traitement standard. Faire bouger la victime aggrave l'hypothermie et une éventuelle lésion rachidienne.",

    "q.l35#13.p" to "Quels facteurs ne doivent pas servir à décider si l'on réanime ?",
    "q.l35#13.o0" to "La profondeur d'ensevelissement",
    "q.l35#13.o1" to "La présence d'une poche d'air",
    "q.l35#13.o2" to "La densité de la neige",
    "q.l35#13.o3" to "Le fait que les voies aériennes soient totalement remplies",
    "q.l35#13.e" to "Les trois premiers changent le temps de dégagement, pas la décision médicale. Seuls l'état des voies aériennes, le temps et la température entrent dans le triage.",

    "q.l35#14.p" to "Remettez dans l'ordre les dix premières minutes sur un site d'avalanche.",
    "q.l35#14.o0" to "Vérifier le risque d'avalanche secondaire et de chutes de pierres, désigner un guetteur",
    "q.l35#14.o1" to "Noter l'heure et le dernier point vu, appeler les secours",
    "q.l35#14.o2" to "Rechercher à l'ARVA puis localiser à la sonde",
    "q.l35#14.o3" to "Commencer à creuser, avec pour objectif d'atteindre le visage au plus vite",
    "q.l35#14.e" to "La logique de cet ordre : d'abord éviter que le secours devienne un second accident, ensuite donner une base aux décisions qui suivront.",

    "q.l35#15.p" to "Remettez dans l'ordre les gestes après avoir atteint le visage.",
    "q.l35#15.o0" to "Dégager la neige et les morceaux de glace de la bouche et du nez, évaluer les voies aériennes",
    "q.l35#15.o1" to "Vérifier les signes vitaux dans la minute",
    "q.l35#15.o2" to "Ventiler immédiatement en l'absence de respiration",
    "q.l35#15.o3" to "Trier selon la règle des 60 minutes et organiser l'évacuation",
    "q.l35#15.e" to "La ventilation passe avant le dégagement complet et avant le transport. C'est l'ordre que l'on inverse le plus souvent en pratique.",

    "q.l35#16.p" to "L'asphyxie est la première cause de décès, avec ______–100 % des morts.",
    "q.l35#16.a0" to "65",
    "q.l35#16.e" to "Cette plage de 65–100 % vient de neuf études. Elle explique pourquoi « ventiler d'abord » est une règle absolue.",

    "q.l35#17.p" to "Les « ______ minutes d'or » constamment rappelées dans la courbe de survie désignent la fenêtre avant le début de la phase d'asphyxie.",
    "q.l35#17.a0" to "18",
    "q.l35#17.a1" to "dix-huit",
    "q.l35#17.e" to "18 minutes est le point de chute statistique. Ce n'est pas un nombre magique, mais il suffit comme objectif d'entraînement.",

    "q.l35#18.p" to "L'hypothermie ne représente que ______–4 % des décès par avalanche.",
    "q.l35#18.a0" to "0",
    "q.l35#18.e" to "0–4 %. La proportion est faible, mais elle explique les rares cas de survie après un ensevelissement très long.",

    "q.l35#19.p" to "Associez chaque phase de la courbe de survie à sa caractéristique.",
    "q.l35#19.l0" to "Phase de survie (0–18 minutes)",
    "q.l35#19.l1" to "Phase d'asphyxie (18–35 minutes)",
    "q.l35#19.l2" to "Phase de latence (35–90 minutes)",
    "q.l35#19.l3" to "Phase prolongée (au-delà de 90 minutes)",
    "q.l35#19.r0" to "Les décès viennent surtout des traumatismes, les voies aériennes sont généralement libres",
    "q.l35#19.r1" to "La survie chute brutalement, la fenêtre de secours est la plus tendue",
    "q.l35#19.r2" to "Ceux qui ont une poche d'air entrent en protection hypothermique, la courbe s'aplatit",
    "q.l35#19.r3" to "L'hypothermie domine, avec quelques survies après des enfouissements très longs",
    "q.l35#19.e" to "Quatre phases, quatre structures de mortalité. Raconter la courbe en quatre étapes est plus utile que retenir un pourcentage isolé.",

    "q.l35#20.p" to "Associez chaque cause de décès à sa proportion.",
    "q.l35#20.l0" to "Asphyxie",
    "q.l35#20.l1" to "Traumatismes",
    "q.l35#20.l2" to "Hypothermie",
    "q.l35#20.r0" to "65–100 %",
    "q.l35#20.r1" to "5–29 %",
    "q.l35#20.r2" to "0–4 %",
    "q.l35#20.e" to "Ces proportions sont la source des priorités : ventilation, puis hémostase et immobilisation, puis réchauffement.",

    "q.l35#21.p" to "Une équipe commence à creuser sans avoir désigné de guetteur. Quel est le risque principal ?",
    "q.l35#21.o0" to "Une avalanche secondaire ensevelit aussi les sauveteurs",
    "q.l35#21.o1" to "Creuser trop lentement",
    "q.l35#21.o2" to "Manquer de corde",
    "q.l35#21.o3" to "Ne rien noter",
    "q.l35#21.e" to "Une avalanche survient rarement une seule fois. Le guetteur est la seule personne capable de dire stop quand la deuxième arrive.",

    "q.l35#22.p" to "Pourquoi ne faut-il pas « tirer la personne dès qu'on la touche » ?",
    "q.l35#22.o0" to "Cela peut aggraver une lésion rachidienne et enfoncer de la neige dans la bouche et le nez",
    "q.l35#22.o1" to "Cela abîme les vêtements",
    "q.l35#22.o2" to "Cela retarde les photos",
    "q.l35#22.o3" to "Cela effraie la victime",
    "q.l35#22.e" to "On dégage d'abord le visage et les voies aériennes, on vérifie la position de la tête et du cou, puis le thorax et le corps. Dans le mauvais ordre, on peut sauver quelqu'un en le laissant paraplégique.",

    "q.l35#23.p" to "Si vous êtes seul sur place, faut-il creuser d'abord ou appeler d'abord ?",
    "q.l35#23.o0" to "Creuser d'abord : la fenêtre de survie est plus courte que n'importe quel délai d'intervention, on signalera ensuite si possible",
    "q.l35#23.o1" to "Téléphoner d'abord",
    "q.l35#23.o2" to "Retourner au camp chercher du monde",
    "q.l35#23.o3" to "Filmer d'abord",
    "q.l35#23.e" to "Seul, attendre les secours équivaut presque à renoncer. Le moment pour lancer un signal se trouvera plus tard ; creuser ne peut pas attendre.",

    "q.l35#24.p" to "Pourquoi l'heure de l'ensevelissement doit-elle être notée à la minute près ?",
    "q.l35#24.o0" to "Parce qu'elle détermine la règle de triage appliquée ensuite à la réanimation",
    "q.l35#24.o1" to "Pour le rapport",
    "q.l35#24.o2" to "Pour l'assurance",
    "q.l35#24.o3" to "Pour les statistiques",
    "q.l35#24.e" to "60 minutes est la ligne de partage du triage, et sur place on ne peut souvent l'estimer qu'à partir de l'heure du témoignage. Dix minutes d'écart et le raisonnement part sur une autre branche.",

    "q.l35#25.p" to "Pourquoi « enseveli profondément » ne signifie-t-il pas « sans espoir » ?",
    "q.l35#25.o0" to "La profondeur change le temps de dégagement, alors que la décision médicale dépend du temps, des voies aériennes et de la température",
    "q.l35#25.o1" to "Parce que la neige fond",
    "q.l35#25.o2" to "Parce qu'il y a du monde",
    "q.l35#25.o3" to "Parce que les personnes profondément enfouies sont plus froides",
    "q.l35#25.e" to "Prendre la profondeur pour un critère médical conduit à abandonner trop tôt. La profondeur ne change que la durée du dégagement, pas ce qu'il faut faire.",
    // ---------- l36 Réanimation sous avalanche : règle des 60 minutes et voies aériennes ----------
    "q.l36#0.p" to "Quelle est la ligne de décision temporelle de l'ICAR MedCom dans la version 2023 ?",
    "q.l36#0.o0" to "60 minutes",
    "q.l36#0.o1" to "35 minutes",
    "q.l36#0.o2" to "90 minutes",
    "q.l36#0.o3" to "120 minutes",
    "q.l36#0.e" to "La version 2013 utilisait 35 minutes ; celle de 2023 retient 60 minutes. Tout support de cours doit préciser l'année et la référence.",

    "q.l36#1.p" to "Ensevelissement de 25 minutes, aucun signe vital, voies aériennes partiellement encombrées de neige meuble (sans être totalement remplies). Que faire ?",
    "q.l36#1.o0" to "Traiter comme une asphyxie : dégager la bouche et le nez, ventiler au plus vite, commencer les compressions",
    "q.l36#1.o1" to "Traiter comme une obstruction et renoncer à la réanimation",
    "q.l36#1.o2" to "Réchauffer d'abord",
    "q.l36#1.o3" to "Attendre l'équipe professionnelle",
    "q.l36#1.e" to "Jusqu'à 60 minutes, on traite toujours comme une asphyxie, que les voies soient libres ou non. De la neige meuble n'est pas une obstruction : l'obstruction exige un remplissage complet.",

    "q.l36#2.p" to "Ensevelissement de 70 minutes, aucun signe vital, voies aériennes libres, température centrale non mesurable. Que faire ?",
    "q.l36#2.o0" to "Traiter comme un arrêt cardiaque hypothermique : commencer la RCP et évacuer",
    "q.l36#2.o1" to "Traiter comme une asphyxie et ne pas réanimer",
    "q.l36#2.o2" to "Attendre une mesure de température avant de décider",
    "q.l36#2.o3" to "Se limiter au réchauffement",
    "q.l36#2.e" to "Voies libres et plus de 60 minutes : la probabilité d'un arrêt hypothermique est suffisante pour réanimer. En hypothermie, « pas réchauffé » ne veut pas dire « mort ».",

    "q.l36#3.p" to "Ensevelissement de 70 minutes, aucun signe vital, bouche et nez totalement remplis de neige tassée, aucune mesure de température possible. Que faire ?",
    "q.l36#3.o0" to "Traiter comme un arrêt cardiaque asphyxique et ne pas commencer la RCP",
    "q.l36#3.o1" to "Commencer immédiatement les compressions",
    "q.l36#3.o2" to "Dégager d'abord, puis juger",
    "q.l36#3.o3" to "Donner deux insufflations puis arrêter",
    "q.l36#3.e" to "C'est le cas explicitement listé en 2023 comme « on peut ne pas commencer la réanimation ». Si la température est mesurable et inférieure à 30 °C, on tente au contraire de réanimer.",

    "q.l36#4.p" to "Température centrale mesurée à 28 °C, voies aériennes libres, aucun signe vital, ensevelissement de 80 minutes. Que faire ?",
    "q.l36#4.o0" to "Tenter la réanimation et évacuer vers un hôpital capable de réchauffement par circulation extracorporelle",
    "q.l36#4.o1" to "Renoncer à la réanimation",
    "q.l36#4.o2" to "Se limiter au réchauffement",
    "q.l36#4.o3" to "Attendre que la température remonte pour juger",
    "q.l36#4.e" to "Moins de 30 °C et voies libres : il faut tenter, quelle que soit la durée de l'ensevelissement. Ce type de victime relève d'un réchauffement de niveau ECLS.",

    "q.l36#5.p" to "Comment définit-on l'« obstruction des voies aériennes » en sauvetage d'avalanche ?",
    "q.l36#5.o0" to "Bouche et nez totalement remplis de neige tassée ou de débris",
    "q.l36#5.o1" to "Un peu de neige dans la bouche",
    "q.l36#5.o2" to "La présence de glaires",
    "q.l36#5.o3" to "Un saignement de nez",
    "q.l36#5.e" to "La définition doit être stricte, car elle décide de l'engagement de la réanimation. En cas de doute, on considère les voies libres : c'est le choix par défaut qui penche vers la vie.",

    "q.l36#6.p" to "Concernant la poche d'air, quelle affirmation est correcte ?",
    "q.l36#6.o0" to "La survie est meilleure avec une poche d'air, mais la poche ne décide pas si l'on réanime",
    "q.l36#6.o1" to "Sans poche d'air, il ne faut pas secourir",
    "q.l36#6.o2" to "Avec une poche d'air, la survie est certaine",
    "q.l36#6.o3" to "La poche d'air détermine l'obstruction",
    "q.l36#6.e" to "La version 2023 est explicite : la poche d'air, la densité de la neige et la profondeur ne doivent pas modifier la conduite. Elles jouent sur le temps, pas sur la décision.",

    "q.l36#7.p" to "Quand peut-on commencer les compressions thoraciques ?",
    "q.l36#7.o0" to "Sans attendre le dégagement complet : dès que le thorax est accessible",
    "q.l36#7.o1" to "Il faut attendre que tout le corps soit dégagé",
    "q.l36#7.o2" to "Il faut attendre l'arrivée à l'hôpital",
    "q.l36#7.o3" to "Il faut attendre une mesure de température",
    "q.l36#7.e" to "« Attendre d'être sorti pour masser » fait perdre plusieurs minutes pour rien. La version 2023 précise que des compressions efficaces restent possibles même en position anormale, partiellement enseveli.",

    "q.l36#8.p" to "Pourquoi ventiler le plus tôt possible ?",
    "q.l36#8.o0" to "Ces victimes meurent en immense majorité d'asphyxie : le manque d'oxygène est le premier problème",
    "q.l36#8.o1" to "Parce que c'est plus pratique",
    "q.l36#8.o2" to "Pour rassurer la famille",
    "q.l36#8.o3" to "Pour économiser l'oxygène",
    "q.l36#8.e" to "Ventiler d'abord, la circulation ensuite. C'est aussi la base physiologique de la règle « jusqu'à 60 minutes, quelles que soient les voies aériennes ».",

    "q.l36#9.p" to "Quels sont en général les critères d'arrêt de la réanimation ?",
    "q.l36#9.o0" to "Lésion mortelle, corps totalement gelé, obstruction des voies aériennes au-delà de 60 minutes, kaliémie très élevée",
    "q.l36#9.o1" to "La demande de la famille",
    "q.l36#9.o2" to "La tombée de la nuit",
    "q.l36#9.o3" to "Le manque de matériel",
    "q.l36#9.e" to "Ces critères viennent de la version 2023 et des recommandations ICAR d'arrêt de la réanimation. La décision revient à du personnel formé, pas à celui qui creuse.",

    "q.l36#10.p" to "Où est l'erreur dans « regarde d'abord la profondeur, puis décide si on réanime » ?",
    "q.l36#10.o0" to "La profondeur change le temps de dégagement, elle n'entre pas dans la décision médicale",
    "q.l36#10.o1" to "La profondeur ne peut pas être mesurée",
    "q.l36#10.o2" to "La profondeur est toujours faible",
    "q.l36#10.o3" to "La profondeur détermine la survie",
    "q.l36#10.e" to "Prendre un problème d'ingénierie pour un critère médical conduit à abandonner trop tôt. La décision ne regarde que le temps, les voies aériennes et la température.",

    "q.l36#11.p" to "Selon la version 2023, quels éléments entrent dans le triage ?",
    "q.l36#11.o0" to "La durée de l'ensevelissement",
    "q.l36#11.o1" to "La liberté des voies aériennes",
    "q.l36#11.o2" to "La possibilité de mesurer la température centrale et sa valeur",
    "q.l36#11.o3" to "La profondeur de l'ensevelissement",
    "q.l36#11.e" to "Les trois premiers forment l'arbre de décision. Le quatrième ne change que la durée du dégagement, pas le triage.",

    "q.l36#12.p" to "Quels sont les points clés de la prise en charge d'un arrêt cardiaque hypothermique ?",
    "q.l36#12.o0" to "Manipuler avec douceur, éviter les secousses",
    "q.l36#12.o1" to "Isolation thermique sur tout le corps",
    "q.l36#12.o2" to "Surveillance continue du rythme et de la température centrale",
    "q.l36#12.o3" to "Réchauffer sur place jusqu'à 35 °C avant de transporter",
    "q.l36#12.e" to "Un réchauffement efficace est impossible sur place : vouloir « réchauffer avant de partir » fait perdre du temps. L'objectif est d'atteindre au plus vite un centre disposant d'ECLS.",

    "q.l36#13.p" to "Concernant les voies aériennes et la ventilation, quelles pratiques sont correctes ?",
    "q.l36#13.o0" to "Dégager la neige et les morceaux de glace de la bouche et du nez",
    "q.l36#13.o1" to "En cas de doute sur l'obstruction, considérer les voies comme libres",
    "q.l36#13.o2" to "Ventiler avant d'envisager les compressions",
    "q.l36#13.o3" to "Attendre le dégagement complet pour évaluer les voies aériennes",
    "q.l36#13.e" to "Les trois premiers visent tous à ventiler tôt. Le dernier fait perdre les minutes les plus décisives.",

    "q.l36#14.p" to "Remettez dans l'ordre la prise en charge d'un ensevelissement de 60 minutes ou moins sans signe vital.",
    "q.l36#14.o0" to "Dégager la bouche et le nez, évaluer les voies aériennes",
    "q.l36#14.o1" to "Ventiler immédiatement",
    "q.l36#14.o2" to "Commencer les compressions thoraciques",
    "q.l36#14.o3" to "Réchauffer, protéger le rachis et organiser l'évacuation",
    "q.l36#14.e" to "La ventilation passe avant les compressions : c'est la grande différence entre un arrêt asphyxique par avalanche et un arrêt cardiaque d'origine cardiaque.",

    "q.l36#15.p" to "Remettez dans l'ordre le triage d'un ensevelissement de plus de 60 minutes.",
    "q.l36#15.o0" to "Confirmer que la durée dépasse bien 60 minutes",
    "q.l36#15.o1" to "Évaluer si les voies aériennes sont totalement remplies",
    "q.l36#15.o2" to "Tenter de mesurer la température centrale",
    "q.l36#15.o3" to "Décider de réanimer ou non selon la branche correspondante",
    "q.l36#15.e" to "L'ordre est temps, puis voies aériennes, puis température. Si une information manque, on retient la branche qui penche vers la vie.",

    "q.l36#16.p" to "La ligne de décision de réanimation de l'ICAR MedCom 2023 est de ______ minutes d'ensevelissement.",
    "q.l36#16.a0" to "60",
    "q.l36#16.e" to "L'ancienne valeur de 35 minutes est abrogée. Supports de cours et banque de questions doivent être alignés sur 60 minutes.",

    "q.l36#17.p" to "Si la température centrale est inférieure à ______ °C et les voies aériennes libres, il faut tenter la réanimation quelle que soit la durée de l'ensevelissement.",
    "q.l36#17.a0" to "30",
    "q.l36#17.e" to "30 °C est un critère parallèle. Il intègre la fenêtre de « protection hypothermique » dans la décision.",

    "q.l36#18.p" to "L'hypothermie ne représente que 0–4 % des décès par avalanche : l'ordre des gestes est donc d'abord ______, puis de réchauffer.",
    "q.l36#18.a0" to "ventiler",
    "q.l36#18.a1" to "les voies aériennes",
    "q.l36#18.a2" to "assurer les voies aériennes",
    "q.l36#18.e" to "Ventiler avant de réchauffer : cet ordre est plus strict en sauvetage d'avalanche que dans l'hypothermie ordinaire.",

    "q.l36#19.p" to "Associez chaque situation d'ensevelissement à sa conduite (version 2023).",
    "q.l36#19.l0" to "60 minutes ou moins, aucun signe vital",
    "q.l36#19.l1" to "Plus de 60 minutes, voies libres, température non mesurable",
    "q.l36#19.l2" to "Plus de 60 minutes, voies obstruées, température non mesurable",
    "q.l36#19.l3" to "Température mesurable inférieure à 30 °C, voies libres",
    "q.l36#19.r0" to "Traiter comme une asphyxie et ventiler au plus vite",
    "q.l36#19.r1" to "Traiter comme un arrêt hypothermique et réanimer",
    "q.l36#19.r2" to "Traiter comme un arrêt asphyxique et ne pas commencer la réanimation",
    "q.l36#19.r3" to "Tenter la réanimation quelle que soit la durée et évacuer vers un centre ECLS",
    "q.l36#19.e" to "Ces quatre branches couvrent la grande majorité des situations réelles. Retenir les conditions des branches est plus fiable que retenir les conclusions.",

    "q.l36#20.p" to "Associez chaque critère d'arrêt de la réanimation à sa signification.",
    "q.l36#20.l0" to "Lésion mortelle",
    "q.l36#20.l1" to "Corps totalement gelé",
    "q.l36#20.l2" to "Voies obstruées et plus de 60 minutes",
    "q.l36#20.l3" to "Kaliémie très élevée",
    "q.l36#20.r0" to "La lésion elle-même est au-delà des ressources",
    "q.l36#20.r1" to "Le corps est gelé, le réchauffement n'a plus de sens",
    "q.l36#20.r2" to "Traiter comme un arrêt asphyxique et ne pas commencer la réanimation",
    "q.l36#20.r3" to "Signe d'une anoxie prolongée, pronostic très défavorable",
    "q.l36#20.e" to "Les quatre sont des preuves qu'il n'y a plus de réversibilité médicale possible. L'évaluation revient à du personnel formé, et la justification doit être consignée.",

    "q.l36#21.p" to "Sur place, quelqu'un affirme « au-delà de 35 minutes, on ne réanime plus ». Que répondez-vous ?",
    "q.l36#21.o0" to "C'était la référence de 2013 ; la version 2023 est passée à 60 minutes et a ajouté un critère de température",
    "q.l36#21.o1" to "Il a raison",
    "q.l36#21.o2" to "Cela dépend des cas",
    "q.l36#21.o3" to "C'est à lui de décider",
    "q.l36#21.e" to "Les 35 minutes restent très présentes dans la documentation chinoise. Mettre à jour la référence est l'un des apports les plus concrets de ce type de cours.",

    "q.l36#22.p" to "Cas : ensevelissement de 20 minutes, aucune respiration au dégagement, neige meuble dans la bouche sans remplissage complet. Que faire en priorité ?",
    "q.l36#22.o0" to "Dégager la bouche et le nez, ventiler, commencer les compressions et évacuer au plus vite",
    "q.l36#22.o1" to "Conclure à une obstruction et ne pas réanimer",
    "q.l36#22.o2" to "Réchauffer d'abord",
    "q.l36#22.o3" to "Attendre l'avis de l'équipe professionnelle",
    "q.l36#22.e" to "60 minutes ou moins et pas d'obstruction complète : on traite comme une asphyxie et on réanime à fond. De la neige meuble ne constitue pas une obstruction.",

    "q.l36#23.p" to "Cas : ensevelissement de 70 minutes, voies libres, température centrale 28 °C, aucun signe vital. Que faire en priorité ?",
    "q.l36#23.o0" to "Réanimer sans arrêt, manipuler avec douceur, isoler tout le corps et évacuer vers un hôpital capable de réchauffement ECLS",
    "q.l36#23.o1" to "Arrêter la réanimation",
    "q.l36#23.o2" to "Se limiter au réchauffement et à la surveillance",
    "q.l36#23.o3" to "Réchauffer jusqu'à 35 °C avant de transporter",
    "q.l36#23.e" to "Dans un arrêt hypothermique, l'essentiel est d'atteindre un lieu capable de réchauffer : la réanimation ne s'interrompt pas en route.",

    "q.l36#24.p" to "Pourquoi dit-on que « le cœur hypothermique est très sensible » ?",
    "q.l36#24.o0" to "Une manipulation brutale peut déclencher une fibrillation ventriculaire : d'où des déplacements doux et à l'horizontale",
    "q.l36#24.o1" to "Parce qu'il craint le froid",
    "q.l36#24.o2" to "Parce que la fréquence cardiaque est lente",
    "q.l36#24.o3" to "Parce que la pression artérielle est basse",
    "q.l36#24.e" to "C'est la raison pour laquelle le transport d'une victime hypothermique doit être « plat, stable et doux », un argument qui s'ajoute à la protection rachidienne en sauvetage d'avalanche.",

    "q.l36#25.p" to "Un membre craque émotionnellement pendant le sauvetage et insiste pour arrêter la réanimation. Que fait le chef de cordée ?",
    "q.l36#25.o0" to "Le retirer de la manœuvre mais poursuivre la réanimation, la décision restant fondée sur les critères par du personnel formé",
    "q.l36#25.o1" to "Arrêter immédiatement",
    "q.l36#25.o2" to "Le réprimander",
    "q.l36#25.o3" to "Le laisser continuer les compressions",
    "q.l36#25.e" to "L'émotion doit être accueillie, mais une décision médicale ne peut pas dépendre d'elle. Changer la personne plutôt qu'arrêter les gestes est la réponse la plus responsable.",
    // ---------- l37 Les trois outils : recherche ARVA et sondage ----------
    "q.l37#0.p" to "Dans quel ordre se déroulent les quatre phases d'une recherche d'avalanche ?",
    "q.l37#0.o0" to "Recherche de signal et d'indices, recherche grossière, recherche fine, sondage ponctuel",
    "q.l37#0.o1" to "Recherche grossière, recherche fine, sondage, recherche de signal",
    "q.l37#0.o2" to "Sondage, recherche fine, recherche grossière",
    "q.l37#0.o3" to "Recherche, dégagement, sondage",
    "q.l37#0.e" to "Les quatre phases sont une convergence progressive : de toute la pente, à quelques mètres, à un point de la surface, puis à une profondeur précise. Sauter une étape fait perdre du temps.",

    "q.l37#1.p" to "Quel espacement prend-on en général entre deux bandes de recherche ARVA ?",
    "q.l37#1.o0" to "Environ 40 m, et environ 20 m depuis le bord des débris",
    "q.l37#1.o1" to "10 m",
    "q.l37#1.o2" to "80 m",
    "q.l37#1.o3" to "Le plus large possible",
    "q.l37#1.e" to "40 m est la valeur par défaut en formation, pas la limite du matériel. Si le niveau de l'équipe est incertain, on descend à 30 m : mieux vaut quelques aller-retours de plus.",

    "q.l37#2.p" to "Avant de commencer la recherche, quelle est la chose à faire pour toute l'équipe ?",
    "q.l37#2.o0" to "Passer tous les ARVA en mode réception et éteindre téléphones et appareils photo",
    "q.l37#2.o1" to "Creuser d'abord un trou d'essai",
    "q.l37#2.o2" to "Prendre des photos",
    "q.l37#2.o3" to "Ranger la corde",
    "q.l37#2.e" to "S'il reste un appareil en émission, la recherche ne fonctionne pas ; les interférences électroniques réduisent la distance utile. Ces deux points se règlent avant tout le reste.",

    "q.l37#3.p" to "Pendant la phase de recherche de signal, que regarde-t-on en premier ?",
    "q.l37#3.o0" to "Les indices visibles à la surface (gants, pointes de bâtons, sangle de sac)",
    "q.l37#3.o1" to "Les chiffres de l'ARVA",
    "q.l37#3.o2" to "La structure du manteau neigeux",
    "q.l37#3.o3" to "La direction du vent",
    "q.l37#3.e" to "Un indice en surface peut réduire la zone à quelques dizaines de mètres. Le nez sur l'ARVA fait justement manquer ces indices.",

    "q.l37#4.p" to "À quelle distance la recherche grossière doit-elle ramener la lecture ?",
    "q.l37#4.o0" to "3–5 m",
    "q.l37#4.o1" to "20 m",
    "q.l37#4.o2" to "0,5 m",
    "q.l37#4.o3" to "10–15 m",
    "q.l37#4.e" to "La recherche fine commence après 3–5 m. C'est le moment où l'on passe de la course à la marche, et où la précision devient importante.",

    "q.l37#5.p" to "En recherche grossière, la distance affichée augmente. Qu'est-ce que cela signifie ?",
    "q.l37#5.o0" to "On va dans la mauvaise direction : il faut revenir sur ses pas",
    "q.l37#5.o1" to "Le signal est trop fort",
    "q.l37#5.o2" to "L'appareil est en panne",
    "q.l37#5.o3" to "La victime s'est déplacée",
    "q.l37#5.e" to "L'ARVA affiche une distance : si elle augmente, on s'éloigne. Ce jugement doit être rapide, sans rester sur place à vérifier.",

    "q.l37#6.p" to "Quel est le bon geste en recherche fine ?",
    "q.l37#6.o0" to "Approcher l'ARVA de la surface, faire des croisements, trouver le point de lecture minimale et le marquer",
    "q.l37#6.o1" to "Tourner sur soi-même debout",
    "q.l37#6.o2" to "Descendre la pente en ligne droite",
    "q.l37#6.o3" to "Planter la sonde au hasard",
    "q.l37#6.e" to "Rester près de la surface réduit l'erreur due à la réfraction du signal dans la neige. Marquer le point minimal donne à la sonde un point de départ clair.",

    "q.l37#7.p" to "Lors du sondage ponctuel, la sonde doit être à 90 degrés par rapport à quoi ?",
    "q.l37#7.o0" to "À la surface de la neige (au plan de la pente)",
    "q.l37#7.o1" to "À l'horizontale",
    "q.l37#7.o2" to "À 45 degrés de la pente",
    "q.l37#7.o3" to "Peu importe l'angle",
    "q.l37#7.e" to "Sur une pente, « vertical vers le bas » fait traverser le manteau en biais et la profondeur lue est amplifiée par l'angle. En secours par les coéquipiers, on plante à 90 degrés de la surface.",

    "q.l37#8.p" to "Une première sonde n'a rien donné. Que fait-on ensuite ?",
    "q.l37#8.o0" to "Étendre la recherche sur une grille de 25 cm de côté",
    "q.l37#8.o1" to "Prendre une sonde plus longue",
    "q.l37#8.o2" to "Creuser directement à la pelle",
    "q.l37#8.o3" to "Abandonner ce point",
    "q.l37#8.e" to "25 cm (environ 10 pouces) est la grille standard. Plus large, on rate le corps ; plus serré, on perd du temps.",

    "q.l37#9.p" to "La sonde bute sur du dur. Comment savoir si c'est une personne ?",
    "q.l37#9.o0" to "Chercher une résistance souple, élastique, « comme un corps », et comparer avec la profondeur du sol alentour",
    "q.l37#9.o1" to "Creuser dès que ça bute",
    "q.l37#9.o2" to "Regarder s'il y a du sang sur la sonde",
    "q.l37#9.o3" to "Écouter",
    "q.l37#9.e" to "Le rocher et la glace donnent une résistance dure et cassante ; un corps est élastique. De plus, une victime n'est en général pas plus profonde que le sol autour.",

    "q.l37#10.p" to "Une fois la victime touchée, que fait-on de la sonde ?",
    "q.l37#10.o0" to "On la laisse en place sans la retirer, comme repère de position et de profondeur",
    "q.l37#10.o1" to "On la retire immédiatement",
    "q.l37#10.o2" to "On l'enfonce plus profond",
    "q.l37#10.o3" to "On la passe à un coéquipier",
    "q.l37#10.e" to "La sonde laissée en place est la cible du pelleteur, et la référence pour savoir si l'on creuse au bon endroit.",

    "q.l37#11.p" to "Quand la profondeur dépasse la longueur de la sonde, que fait-on ?",
    "q.l37#11.o0" to "Dégager environ 1 m, relocaliser à l'ARVA, puis sonder à nouveau",
    "q.l37#11.o1" to "Continuer à sonder en force",
    "q.l37#11.o2" to "Renoncer",
    "q.l37#11.o3" to "Changer de personne",
    "q.l37#11.e" to "Sonder en force ne sert à rien puisqu'on ne peut pas atteindre le fond. Raccourcir la distance puis relocaliser est la seule procédure efficace.",

    "q.l37#12.p" to "Pourquoi les sondes d'une recherche organisée restent-elles verticales (et non perpendiculaires à la surface) ?",
    "q.l37#12.o0" to "Pour rendre comparables les profondeurs lues par chaque sauveteur et former un plan de sondage cohérent",
    "q.l37#12.o1" to "Parce que c'est moins fatigant",
    "q.l37#12.o2" to "Parce que c'est plus rapide",
    "q.l37#12.o3" to "Parce que la norme l'exige",
    "q.l37#12.e" to "Une ligne de sondage organisée est une surface : elle a besoin de profondeurs comparables. Le secours par les coéquipiers vise un seul point, d'où l'angle perpendiculaire à la surface, plus précis.",

    "q.l37#13.p" to "Que comprend le contrôle de l'ARVA avant le départ ?",
    "q.l37#13.o0" to "Batterie suffisamment chargée",
    "q.l37#13.o1" to "Un test d'émission",
    "q.l37#13.o2" to "Savoir passer en réception, marquer et masquer",
    "q.l37#13.o3" to "Le porter sur soi, pas au fond du sac",
    "q.l37#13.e" to "S'il manque un de ces quatre points, l'appareil sera inutile au moment décisif. Le fond du sac est l'erreur la plus fréquente : sac enseveli ou perdu, plus d'ARVA.",

    "q.l37#14.p" to "Que vérifie-t-on sur la sonde ?",
    "q.l37#14.o0" to "La longueur, choisie selon l'enneigement local",
    "q.l37#14.o1" to "Le câble et le verrouillage en bon état",
    "q.l37#14.o2" to "Qu'elle se déplie et se verrouille d'une seule main",
    "q.l37#14.o3" to "Qu'elle soit la plus légère possible",
    "q.l37#14.e" to "Pour une équipe de secours, on recommande au moins 3 m (UIAA 157) ; en usage personnel, 240–320 cm. La légèreté est un plus, mais la solidité et la fiabilité du verrouillage comptent davantage.",

    "q.l37#15.p" to "Plusieurs personnes sont ensevelies. Que faut-il faire ?",
    "q.l37#15.o0" to "Marquer ou masquer le premier signal",
    "q.l37#15.o1" to "Chercher ensuite le deuxième signal",
    "q.l37#15.o2" to "Ne pas s'acharner sur un signal au point de délaisser les autres zones",
    "q.l37#15.o3" to "Ne secourir que la personne la plus proche",
    "q.l37#15.e" to "En ensevelissement multiple, le grand risque est de n'en trouver qu'une. Les fonctions de marquage et de masquage existent précisément pour cela.",

    "q.l37#16.p" to "Remettez dans l'ordre une recherche complète.",
    "q.l37#16.o0" to "Toute l'équipe passe en réception et coupe les sources d'interférence",
    "q.l37#16.o1" to "Faire la recherche de signal le long des bandes",
    "q.l37#16.o2" to "Recherche grossière jusqu'à 3–5 m",
    "q.l37#16.o3" to "Recherche fine : trouver le point de lecture minimale et le marquer",
    "q.l37#16.o4" to "Sonder ponctuellement et laisser la sonde en place",
    "q.l37#16.e" to "Cinq étapes qui convergent de la surface vers le point. Vouloir en économiser une se paie double à l'étape suivante.",

    "q.l37#17.p" to "Remettez dans l'ordre les gestes du sondage ponctuel.",
    "q.l37#17.o0" to "Partir du point de lecture minimale, sonde à 90 degrés de la surface",
    "q.l37#17.o1" to "Si rien n'est touché, étendre sur une grille de 25 cm",
    "q.l37#17.o2" to "S'arrêter dès qu'une résistance élastique est rencontrée",
    "q.l37#17.o3" to "Laisser la sonde en repère et commencer à dégager",
    "q.l37#17.e" to "L'étape la plus souvent ratée est la dernière : beaucoup retirent la sonde dès qu'ils ont touché, et le dégagement perd sa référence.",

    "q.l37#18.p" to "L'espacement des bandes de recherche ARVA est d'environ ______ m.",
    "q.l37#18.a0" to "40",
    "q.l37#18.e" to "En cas de doute, on descend à 30 m. Une bande trop large fait manquer le signal : c'est la cause d'échec la plus fréquente.",

    "q.l37#19.p" to "Le côté de la grille de sondage ponctuel est de ______ cm.",
    "q.l37#19.a0" to "25",
    "q.l37#19.e" to "Environ 10 pouces. Une grille trop large rate le corps, une grille trop serrée fait perdre du temps.",

    "q.l37#20.p" to "En secours par les coéquipiers, la sonde s'enfonce à 90 degrés de ______.",
    "q.l37#20.a0" to "la surface de la neige",
    "q.l37#20.a1" to "la pente",
    "q.l37#20.e" to "Planter perpendiculairement à l'horizontale amplifie la profondeur lue par l'angle de la pente : c'est l'erreur de géométrie la plus fréquente chez les débutants.",

    "q.l37#21.p" to "Associez chaque phase de recherche à son objectif.",
    "q.l37#21.l0" to "Recherche de signal et d'indices",
    "q.l37#21.l1" to "Recherche grossière",
    "q.l37#21.l2" to "Recherche fine",
    "q.l37#21.l3" to "Sondage ponctuel",
    "q.l37#21.r0" to "Trouver le premier signal",
    "q.l37#21.r1" to "Ramener la distance à 3–5 m",
    "q.l37#21.r2" to "Trouver le point de surface le plus proche de la victime",
    "q.l37#21.r3" to "Confirmer la position et la profondeur à la sonde",
    "q.l37#21.e" to "Quatre objectifs qui convergent. Retenir les objectifs s'adapte mieux aux différents terrains que retenir les gestes.",

    "q.l37#22.p" to "Associez chaque équipement à son exigence clé.",
    "q.l37#22.l0" to "ARVA",
    "q.l37#22.l1" to "Sonde",
    "q.l37#22.l2" to "Pelle",
    "q.l37#22.l3" to "Casque",
    "q.l37#22.r0" to "Numérique à trois antennes, porté sur soi, savoir marquer et masquer",
    "q.l37#22.r1" to "Longueur adaptée à l'enneigement, verrouillage d'une main",
    "q.l37#22.r2" to "Lame métallique, manche fiable, sortie rapide",
    "q.l37#22.r3" to "Porté pendant toute la recherche et tout le dégagement",
    "q.l37#22.e" to "Le plus souvent oublié des quatre est le casque : des blocs de neige et des morceaux de glace continuent de tomber pendant le dégagement.",

    "q.l37#23.p" to "Quelqu'un s'arrête et s'acharne à confirmer le premier signal. Que faites-vous ?",
    "q.l37#23.o0" to "Lui rappeler de marquer ou masquer et de continuer à couvrir le reste de la zone",
    "q.l37#23.o1" to "Le laisser continuer",
    "q.l37#23.o2" to "S'arrêter avec lui",
    "q.l37#23.o3" to "Abandonner la recherche",
    "q.l37#23.e" to "En ensevelissement multiple, « trouver tous les signaux » passe avant « confirmer un point à l'extrême ».",

    "q.l37#24.p" to "Pourquoi demande-t-on d'éteindre téléphones et appareils photo pendant la recherche ?",
    "q.l37#24.o0" to "Les appareils électroniques interfèrent avec le signal et réduisent la distance de recherche utile",
    "q.l37#24.o1" to "Pour économiser la batterie",
    "q.l37#24.o2" to "Pour rester silencieux",
    "q.l37#24.o3" to "Pour empêcher les photos",
    "q.l37#24.e" to "L'interférence réduit la largeur utile des bandes et conduit indirectement à des zones non couvertes. C'est la consigne la plus souvent appliquée à moitié.",

    "q.l37#25.p" to "L'équipe ne compte que deux personnes : une qui cherche, une qui creuse. Cette répartition est-elle raisonnable ?",
    "q.l37#25.o0" to "Oui, mais dès que la sonde touche, les deux doivent se relayer au dégagement plutôt qu'un seul s'acharner",
    "q.l37#25.o1" to "Non, les deux doivent chercher ensemble",
    "q.l37#25.o2" to "Non, il faut attendre les secours",
    "q.l37#25.o3" to "Oui, et sans alternance",
    "q.l37#25.e" to "Le point clé d'un binôme est « dès que ça touche, on se relaie ». Un seul pelleteur s'épuise en quelques minutes et devient moins efficace.",

    "q.l37#26.p" to "Avant la recherche, on voit encore de la neige suspendue au-dessus de la zone de débris. Que fait-on ?",
    "q.l37#26.o0" to "Désigner d'abord un guetteur et choisir un itinéraire d'approche sûr, puis commencer la recherche",
    "q.l37#26.o1" to "Foncer directement",
    "q.l37#26.o2" to "Attendre que la neige s'arrête",
    "q.l37#26.o3" to "Renoncer à la recherche",
    "q.l37#26.e" to "Qu'un sauveteur soit enseveli par une seconde avalanche est un type d'accident réel. Le guetteur et l'itinéraire d'approche font partie de la recherche, ce ne sont pas des étapes en plus.",

    "q.l37#27.p" to "Que signifient les objectifs « contact en 10 minutes, dégagement en 18 minutes » ?",
    "q.l37#27.o0" to "Ce sont des repères internes à l'équipe, pour l'entraînement et le débriefing, pas des garanties",
    "q.l37#27.o1" to "Une promesse médicale",
    "q.l37#27.o2" to "Une obligation normative",
    "q.l37#27.o3" to "Une performance du matériel",
    "q.l37#27.e" to "Ces objectifs servent à savoir à quelle étape l'équipe est lente. Les prendre pour une promesse fait perdre le jugement le jour où on ne les atteint pas.",
    // ---------- l38 Dégagement et tapis roulant à neige ----------
    "q.l38#0.p" to "Quel est le premier principe du dégagement ?",
    "q.l38#0.o0" to "Toujours travailler depuis le côté aval",
    "q.l38#0.o1" to "Creuser depuis le dessus, à la verticale",
    "q.l38#0.o2" to "Creuser depuis le côté amont",
    "q.l38#0.o3" to "Creuser à plat depuis le côté",
    "q.l38#0.e" to "Travailler côté aval a trois avantages : la neige part vers le bas, le couloir a une pente, et le pelleteur n'est pas au-dessus de la victime.",

    "q.l38#1.p" to "Que décrit le repère classique du « 1,5 fois la profondeur » ?",
    "q.l38#1.o0" to "La distance à laquelle on recule depuis la sonde en descendant la pente",
    "q.l38#1.o1" to "La largeur du couloir",
    "q.l38#1.o2" to "La longueur de la sonde",
    "q.l38#1.o3" to "Le temps de dégagement",
    "q.l38#1.e" to "Cette distance sert à se donner de la place pour évacuer la neige. C'est une règle empirique, et la recherche récente propose une alternative.",

    "q.l38#2.p" to "Que préconise l'étude de 2023 sur le tapis roulant à neige concernant le point de départ ?",
    "q.l38#2.o0" to "À partir de trois personnes et si la place le permet, creuser directement depuis la sonde en suivant la ligne de plus grande pente",
    "q.l38#2.o1" to "Toujours reculer de 1,5 fois la profondeur",
    "q.l38#2.o2" to "Creuser depuis le dessus",
    "q.l38#2.o3" to "Creuser horizontalement depuis le côté",
    "q.l38#2.e" to "Décaler le point de départ allonge le temps pour atteindre la tête. La conclusion de l'étude suppose des effectifs suffisants : elle ne s'applique pas sans condition.",

    "q.l38#3.p" to "Dans quels cas seulement conseille-t-on de décaler le point de départ ?",
    "q.l38#3.o0" to "Ensevelissement très peu profond avec les pieds engagés à une profondeur proche, ou effectif insuffisant imposant une solution en solo",
    "q.l38#3.o1" to "Dans tous les cas",
    "q.l38#3.o2" to "Quand la neige est très dure",
    "q.l38#3.o3" to "Quand la nuit tombe",
    "q.l38#3.e" to "Dans ces deux situations, le décalage évite des transports inutiles. Dans les autres, creuser depuis la sonde est plus rapide.",

    "q.l38#4.p" to "Quelle est la largeur habituelle du couloir du tapis roulant ?",
    "q.l38#4.o0" to "1–2 m",
    "q.l38#4.o1" to "0,3 m",
    "q.l38#4.o2" to "3–4 m",
    "q.l38#4.o3" to "Le plus étroit possible",
    "q.l38#4.e" to "Trop étroit, l'évacuation est inefficace ; trop large, le volume à creuser explose. 1–2 m est l'équilibre entre efficacité et charge de travail.",

    "q.l38#5.p" to "En dessous de quel angle la neige retombe-t-elle vers la sonde ?",
    "q.l38#5.o0" to "26 degrés",
    "q.l38#5.o1" to "10 degrés",
    "q.l38#5.o2" to "45 degrés",
    "q.l38#5.o3" to "60 degrés",
    "q.l38#5.e" to "26 degrés est la valeur seuil donnée par l'étude. Si la pente ne suffit pas, la neige évacuée revient : le travail est perdu.",

    "q.l38#6.p" to "Laquelle des trois techniques d'évacuation est la plus efficace ?",
    "q.l38#6.o0" to "Le balayage (paddling)",
    "q.l38#6.o1" to "L'écopage (scooping)",
    "q.l38#6.o2" to "La découpe en blocs (cutting)",
    "q.l38#6.o3" to "Les trois se valent",
    "q.l38#6.e" to "Balayer pousse la neige dehors avec un geste continu et rapide. La découpe ne convient qu'à la neige dure, puisqu'il faut d'abord la débiter en blocs.",

    "q.l38#7.p" to "À quoi sert de désigner un chef de chantier pendant le dégagement ?",
    "q.l38#7.o0" to "Il surveille la direction, l'état de la neige au-dessus et la position de la victime, pour que tout le monde ne travaille pas tête baissée",
    "q.l38#7.o1" to "À surveiller le travail",
    "q.l38#7.o2" to "À faire des photos",
    "q.l38#7.o3" to "À économiser de la main-d'œuvre",
    "q.l38#7.e" to "Dès que toute l'équipe a la tête baissée, on creuse de travers et on ignore une seconde avalanche. Le chef de chantier est le seul à lever les yeux.",

    "q.l38#8.p" to "Une fois le visage atteint, quel ordre adopte-t-on ?",
    "q.l38#8.o0" to "Dégager la bouche et le nez pour vérifier les voies aériennes, puis le thorax et les bras, enfin les jambes et le corps",
    "q.l38#8.o1" to "Dégager d'abord les jambes",
    "q.l38#8.o2" to "Tirer d'abord par les épaules",
    "q.l38#8.o3" to "Dégager d'abord le sac",
    "q.l38#8.e" to "Il faut que la cage thoracique puisse se dilater pour ventiler. Commencer par les jambes retarde la ventilation, et tirer par les épaules peut léser le rachis.",

    "q.l38#9.p" to "Sur quoi repose l'idée qu'« une seule personne peut y arriver » ?",
    "q.l38#9.o0" to "Avec une méthode de tapis roulant adaptée à des ressources limitées, une personne atteint une victime à 1,5 m en moins de 18 minutes dans les conditions de l'étude",
    "q.l38#9.o1" to "Parce que chacun a du potentiel",
    "q.l38#9.o2" to "Parce que la neige est légère",
    "q.l38#9.o3" to "Parce que la victime s'auto-secourra",
    "q.l38#9.e" to "Les vitesses d'environ 13,2 cm/min en neige dure et 25,3 cm/min en neige tendre sont des données d'étude : elles justifient de travailler la solution en solo.",

    "q.l38#10.p" to "Quelles sont les vitesses de dégagement en neige dure et en neige tendre ?",
    "q.l38#10.o0" to "Environ 13 cm/min en neige dure et 25 cm/min en neige tendre",
    "q.l38#10.o1" to "Environ 5 cm/min dans les deux cas",
    "q.l38#10.o2" to "Environ 50 cm/min dans les deux cas",
    "q.l38#10.o3" to "Plus vite en neige dure",
    "q.l38#10.e" to "Cet écart explique pourquoi l'état de la neige change l'estimation du temps de secours, et pourquoi la découpe en blocs ne sert qu'en neige dure.",

    "q.l38#11.p" to "Quelle est l'erreur la plus fréquente quand plusieurs personnes pelletent ?",
    "q.l38#11.o0" to "Tout le monde s'entasse sur un seul point, sans relais ni rotation",
    "q.l38#11.o1" to "Creuser trop large",
    "q.l38#11.o2" to "Creuser trop vite",
    "q.l38#11.o3" to "Utiliser une pelle",
    "q.l38#11.e" to "S'entasser gêne tout le monde et ne tient pas dans la durée. Un rythme avec rotation est bien plus rapide qu'une personne qui s'acharne.",

    "q.l38#12.p" to "Quels rôles faut-il attribuer lors d'un dégagement organisé ?",
    "q.l38#12.o0" to "Un chef de chantier",
    "q.l38#12.o1" to "Des pelleteurs et des évacuateurs de neige",
    "q.l38#12.o2" to "Un guetteur de sécurité",
    "q.l38#12.o3" to "Une personne qui note l'heure et la position",
    "q.l38#12.e" to "Ces quatre rôles confient à quelqu'un la direction, l'effort, la sécurité et le temps. S'il en manque un, un maillon échappe au contrôle.",

    "q.l38#13.p" to "Quelles pratiques font revenir la neige déjà évacuée ?",
    "q.l38#13.o0" to "Creuser depuis le dessus ou depuis l'amont",
    "q.l38#13.o1" to "Un couloir trop plat (en dessous d'environ 26 degrés)",
    "q.l38#13.o2" to "Empiler la neige au-dessus de la sonde",
    "q.l38#13.o3" to "Placer le couloir dans l'axe de la ligne de plus grande pente",
    "q.l38#13.e" to "Les trois premiers font retomber la neige. Le quatrième est justement la bonne pratique.",

    "q.l38#14.p" to "Concernant le « point de départ du dégagement », quelles affirmations sont correctes ?",
    "q.l38#14.o0" to "Le repère classique est 1,5 fois la profondeur, avec une attaque latérale côté aval",
    "q.l38#14.o1" to "La simplification d'Avalanche.org est de reculer d'un pas en dessous de 1 m de profondeur, de deux pas au-delà",
    "q.l38#14.o2" to "L'ISSW 2023 préconise, avec des effectifs suffisants, de creuser depuis la sonde en suivant la ligne de plus grande pente",
    "q.l38#14.o3" to "Repère et conclusions de recherche sont totalement contradictoires : il faut choisir l'un ou l'autre",
    "q.l38#14.e" to "Les trois formulations sont « un principe plus deux générations d'expérience ». Enseigner dans l'ordre principe, repère, mise à jour évite que le repère devienne une superstition.",

    "q.l38#15.p" to "Remettez dans l'ordre un dégagement standard.",
    "q.l38#15.o0" to "Vérifier le plan de travail côté aval et le risque d'avalanche secondaire",
    "q.l38#15.o1" to "Ouvrir un couloir en V depuis le point de départ, en direction de la sonde",
    "q.l38#15.o2" to "Organiser l'évacuation en chaîne et les rotations",
    "q.l38#15.o3" to "Une fois le visage atteint, dégager d'abord la bouche et le nez",
    "q.l38#15.e" to "La logique de l'ordre : d'abord la sécurité, ensuite l'efficacité, enfin la priorité aux voies aériennes.",

    "q.l38#16.p" to "Remettez dans l'ordre les gestes après avoir atteint le visage.",
    "q.l38#16.o0" to "Dégager la neige et les morceaux de glace de la bouche et du nez, vérifier les voies aériennes",
    "q.l38#16.o1" to "Dégager la neige autour du thorax et des bras pour permettre la dilatation",
    "q.l38#16.o2" to "Dégager les jambes et le reste du corps",
    "q.l38#16.o3" to "Appliquer les règles de réanimation et organiser l'évacuation",
    "q.l38#16.e" to "Cet ordre est l'inverse de « dégager complètement puis secourir », mais c'est le bon : la fenêtre de ventilation ne dure que quelques minutes.",

    "q.l38#17.p" to "L'angle seuil du couloir du tapis roulant à neige est d'environ ______ degrés.",
    "q.l38#17.a0" to "26",
    "q.l38#17.e" to "En dessous, les blocs de neige retombent vers la sonde et l'efficacité de l'évacuation s'effondre.",

    "q.l38#18.p" to "Le repère classique conseille de commencer à creuser à environ ______ fois la profondeur d'ensevelissement, en reculant depuis la sonde.",
    "q.l38#18.a0" to "1,5",
    "q.l38#18.a1" to "1.5",
    "q.l38#18.e" to "1,5 fois est une règle empirique. Avec des effectifs suffisants, il faut d'abord envisager de creuser depuis la sonde en suivant la ligne de plus grande pente.",

    "q.l38#19.p" to "L'objectif du secours par les coéquipiers est un contact en ______ minutes et un dégagement en 18 minutes.",
    "q.l38#19.a0" to "10",
    "q.l38#19.e" to "10 et 18 sont des repères internes d'entraînement et de débriefing, pour situer l'étape où l'équipe perd du temps.",

    "q.l38#20.p" to "Associez chaque technique d'évacuation à sa condition d'emploi.",
    "q.l38#20.l0" to "Balayage (paddling)",
    "q.l38#20.l1" to "Écopage (scooping)",
    "q.l38#20.l2" to "Découpe en blocs (cutting blocks)",
    "q.l38#20.l3" to "Chaîne (conveyor)",
    "q.l38#20.r0" to "La plus efficace, convient à la plupart des neiges meubles",
    "q.l38#20.r1" to "Vient ensuite, convient pour sortir la neige du couloir",
    "q.l38#20.r2" to "La plus lente, réservée à la neige dure",
    "q.l38#20.r3" to "Mode d'organisation d'ensemble quand on est plusieurs",
    "q.l38#20.e" to "L'ordre d'efficacité impose « balayer d'abord, écoper ensuite, découper seulement en neige dure ». La chaîne n'est pas une technique, c'est une organisation.",

    "q.l38#21.p" to "Associez chaque erreur fréquente à sa conséquence.",
    "q.l38#21.l0" to "Creuser depuis l'amont",
    "q.l38#21.l1" to "Couloir trop plat",
    "q.l38#21.l2" to "Tirer le corps dès qu'on atteint la victime",
    "q.l38#21.l3" to "Retirer la sonde après avoir touché",
    "q.l38#21.r0" to "Les blocs retombent sur le visage : lent et dangereux",
    "q.l38#21.r1" to "La neige revient, il faut la déplacer plusieurs fois",
    "q.l38#21.r2" to "Risque d'aggraver une lésion rachidienne et d'enfoncer de la neige dans la bouche",
    "q.l38#21.r3" to "Perte des repères de position et de profondeur",
    "q.l38#21.e" to "Ces quatre erreurs sont toutes fréquentes, et toutes évitables en s'entraînant à l'avance.",

    "q.l38#22.p" to "Neige très dure, équipe de trois personnes seulement : comment choisir le point de départ ?",
    "q.l38#22.o0" to "Creuser depuis la sonde en suivant la ligne de plus grande pente, en ouvrant à la découpe dans les sections dures",
    "q.l38#22.o1" to "Reculer de 3 fois la profondeur",
    "q.l38#22.o2" to "Creuser depuis le dessus",
    "q.l38#22.o3" to "Attendre du matériel",
    "q.l38#22.e" to "Avec assez de bras, on suit la ligne de plus grande pente ; la neige dure ne change que la technique (la découpe), pas le principe.",

    "q.l38#23.p" to "Pourquoi « tout le monde pellète à fond ensemble » n'est-il pas plus rapide ?",
    "q.l38#23.o0" to "On se gêne, on ne tient pas la durée, et personne ne surveille la neige au-dessus",
    "q.l38#23.o1" to "Parce qu'on a trop chaud à plusieurs",
    "q.l38#23.o2" to "Parce qu'il n'y a pas assez de pelles",
    "q.l38#23.o3" to "Parce que personne ne commande",
    "q.l38#23.e" to "Le pelletage est un effort très intense qui épuise en quelques minutes. Rotation, direction et chaîne transforment la main-d'œuvre en vitesse.",

    "q.l38#24.p" to "Pendant le sauvetage, un gros bloc de neige dure se trouve à côté de la victime. Que fait-on ?",
    "q.l38#24.o0" to "Dégager d'abord le passage des voies aériennes, sans retarder la ventilation pour déplacer le bloc",
    "q.l38#24.o1" to "Déplacer d'abord le bloc",
    "q.l38#24.o2" to "Le casser au piolet",
    "q.l38#24.o3" to "Contourner",
    "q.l38#24.e" to "Le gros bloc peut attendre. La fenêtre des voies aériennes ne dure que quelques minutes : elle passe avant le « nettoyage du site ».",

    "q.l38#25.p" to "Il n'y a qu'une seule pelle sur place. Que fait-on de mieux ?",
    "q.l38#25.o0" to "Faire creuser la personne la plus en forme, les autres poussant la neige à la main et avec les skis, en rotation",
    "q.l38#25.o1" to "Une personne creuse jusqu'au bout",
    "q.l38#25.o2" to "Attendre une deuxième pelle",
    "q.l38#25.o3" to "Utiliser un sac à la place",
    "q.l38#25.e" to "La bonne méthode en solo est justement le « tapis roulant à ressources limitées » : une personne creuse, les autres évacuent la neige.",

    "q.l38#26.p" to "Au débriefing, le contact a pris 14 minutes. Quelle étape faut-il d'abord examiner ?",
    "q.l38#26.o0" to "La recherche et la localisation : laquelle des quatre phases a été lente",
    "q.l38#26.o1" to "Le dégagement",
    "q.l38#26.o2" to "L'appel aux secours",
    "q.l38#26.o3" to "L'achat du matériel",
    "q.l38#26.e" to "Le temps de contact dépend de la recherche et de la localisation ; le dégagement détermine le temps d'extraction. Les deux indicateurs doivent être lus séparément.",
    // ---------- m12 Systèmes de corde avancés et avantage mécanique ----------
    "q.m12#16.p" to "Quel est l'avantage mécanique théorique d'un système 3:1 ?",
    "q.m12#16.o0" to "Tirer 1 m de corde fait monter la charge d'environ 1/3 de mètre",
    "q.m12#16.o1" to "La charge est divisée par deux",
    "q.m12#16.o2" to "La vitesse ne change pas",
    "q.m12#16.o3" to "Pas besoin de nœud autobloquant",
    "q.m12#16.e" to "L'avantage mécanique est le nombre de brins porteurs. 3:1 signifie que l'effort à fournir vaut environ un tiers de la charge, hors frottement.",

    "q.m12#17.p" to "En sauvetage réel, quelle est en général l'efficacité d'un système 5:1 ?",
    "q.m12#17.o0" to "Inférieure à la théorie, à cause des pertes par frottement dans les poulies et la corde",
    "q.m12#17.o1" to "Supérieure à la théorie",
    "q.m12#17.o2" to "Exactement égale à la théorie",
    "q.m12#17.o3" to "Indépendante du frottement",
    "q.m12#17.e" to "Chaque poulie a des pertes : l'efficacité réelle n'est souvent que de 60 à 70 % de la valeur théorique. Il faut garder une marge dans la conception.",

    "q.m12#18.p" to "Quand on utilise un mousqueton au lieu d'une poulie comme point de renvoi, quel est le coût principal ?",
    "q.m12#18.o0" to "Le frottement augmente nettement et l'efficacité baisse",
    "q.m12#18.o1" to "La résistance est insuffisante",
    "q.m12#18.o2" to "Le harnais s'use",
    "q.m12#18.o3" to "On ne peut pas verrouiller",
    "q.m12#18.e" to "Un mousqueton renvoie mais ne réduit pas le frottement : une partie de la force de traction est absorbée. Si une poulie est disponible, on la préfère.",

    "q.m12#19.p" to "À quoi sert le « nœud autobloquant unidirectionnel » dans un système de sauvetage ?",
    "q.m12#19.o0" to "Il bloque après la traction et empêche la charge de redescendre",
    "q.m12#19.o1" to "Il augmente la résistance",
    "q.m12#19.o2" to "Il réduit le frottement",
    "q.m12#19.o3" to "Il relie deux cordes",
    "q.m12#19.e" to "Sans lui, la charge repart à chaque fois qu'on lâche. Le nœud autobloquant est ce qui transforme des tractions intermittentes en déplacement cumulé.",

    "q.m12#20.p" to "Pourquoi prévoir un « nœud autobloquant de secours » dans un système de sauvetage ?",
    "q.m12#20.o0" to "Le nœud principal peut glisser ou lâcher : le secours est la dernière protection",
    "q.m12#20.o1" to "Pour l'esthétique",
    "q.m12#20.o2" to "Pour augmenter la force de traction",
    "q.m12#20.o3" to "Pour économiser de la corde",
    "q.m12#20.e" to "La fiabilité d'un nœud autobloquant dépend du diamètre et de l'état de la corde. Dans un système critique, deux nœuds sont la norme.",

    "q.m12#21.p" to "Pour tirer une victime, le système doit rester autant que possible…",
    "q.m12#21.o0" to "Au plus près du terrain, pour éviter qu'elle heurte la paroi ou une corniche",
    "q.m12#21.o1" to "Le plus haut possible",
    "q.m12#21.o2" to "Le plus vite possible",
    "q.m12#21.o3" to "En montée verticale",
    "q.m12#21.e" to "Les blessures lors d'un tir viennent souvent des chocs, pas de la traction. Le tracé et la position des points d'assurance comptent autant que la force.",

    "q.m12#22.p" to "Quel est le coût d'un système 6:1 (système composé) par rapport à un 3:1 ?",
    "q.m12#22.o0" to "Plus de matériel, un montage plus lent, une plus grande longueur de corde consommée",
    "q.m12#22.o1" to "Moins d'effort et plus rapide",
    "q.m12#22.o2" to "Aucun coût",
    "q.m12#22.o3" to "Impossible à récupérer",
    "q.m12#22.e" to "Plus l'avantage mécanique est élevé, plus le montage est complexe et plus il faut de corde. En sauvetage, la rapidité compte souvent plus que l'économie d'effort.",

    "q.m12#23.p" to "Quand il faut « transférer » au milieu d'un système, quelle est l'exigence minimale ?",
    "q.m12#23.o0" to "Qu'à tout instant au moins un dispositif porte, sans moment sans connexion",
    "q.m12#23.o1" to "Aller vite",
    "q.m12#23.o2" to "Être deux",
    "q.m12#23.o3" to "Utiliser la même corde",
    "q.m12#23.e" to "Les transferts sont un point de sur-accident. Chaque fois qu'on « démonte l'ancien pour construire le nouveau », il faut d'abord établir le nouveau.",

    "q.m12#24.p" to "Quand la corde passe sur une arête vive dans un système, que fait-on ?",
    "q.m12#24.o0" to "Ajouter une protection ou changer le tracé, pour éviter d'entailler la gaine",
    "q.m12#24.o1" to "La laisser passer directement",
    "q.m12#24.o2" to "La tendre davantage",
    "q.m12#24.o3" to "La remplacer par une sangle",
    "q.m12#24.e" to "Une corde en tension entaillée perd brutalement de sa résistance. Une protection coûte très peu, alors que le prix peut être une corde, voire une chute.",

    "q.m12#25.p" to "Pourquoi les ancrages d'un système de sauvetage sont-ils plus exigeants que ceux d'un relais ordinaire ?",
    "q.m12#25.o0" to "Parce qu'ils encaissent une charge statique plus des variations dynamiques, et qu'il n'y a souvent qu'un seul système",
    "q.m12#25.o1" to "Parce que c'est plus important",
    "q.m12#25.o2" to "Parce qu'il y a plus de monde",
    "q.m12#25.o3" to "À cause de la longueur de corde",
    "q.m12#25.e" to "En sauvetage, il n'y a pas de second relais pour rattraper. La défaillance d'un ancrage signifie « deux personnes tombent ensemble ».",

    "q.m12#26.p" to "Pour estimer la force de traction nécessaire, que faut-il ajouter à l'avantage mécanique ?",
    "q.m12#26.o0" to "Le poids de la victime et du matériel, le frottement corde-poulie, la résistance du terrain",
    "q.m12#26.o1" to "La météo",
    "q.m12#26.o2" to "Le temps",
    "q.m12#26.o3" to "Le poids des coéquipiers",
    "q.m12#26.e" to "La « traction théorique » est souvent sous-estimée. Avec le frottement et le terrain, la force réelle peut être le double de la valeur théorique.",

    "q.m12#27.p" to "Une fois le système monté, que faut-il faire en premier ?",
    "q.m12#27.o0" to "Un essai à vide, pour vérifier le tracé, les nœuds et les ancrages",
    "q.m12#27.o1" to "Tirer la personne immédiatement",
    "q.m12#27.o2" to "Prendre des photos",
    "q.m12#27.o3" to "Ranger la corde",
    "q.m12#27.e" to "Un essai à vide révèle 80 % des erreurs de montage. Dix secondes ici peuvent éviter une défaillance du système.",

    // ---------- m13 Auto-sauvetage et sauvetage en cordée ----------
    "q.m13#14.p" to "Pour remonter seul sur nœuds autobloquants (remontée au prusik), quel est le bon ordre ?",
    "q.m13#14.o0" to "Se lever (pousser le nœud du haut), s'asseoir (transférer le poids), pousser le nœud du bas, recommencer",
    "q.m13#14.o1" to "Pousser les deux nœuds en même temps",
    "q.m13#14.o2" to "Ne pousser que le nœud du haut",
    "q.m13#14.o3" to "Tirer avec les bras",
    "q.m13#14.e" to "Le cycle « se lever, s'asseoir, pousser » transfère le poids entre les deux nœuds. Pousser les deux ensemble fait glisser tout de suite.",

    "q.m13#15.p" to "Lors d'une remontée seul, à quoi sert l'étrier ?",
    "q.m13#15.o0" to "À reporter le poids sur les jambes et soulager les bras",
    "q.m13#15.o1" to "À augmenter le frottement",
    "q.m13#15.o2" to "À relier le harnais",
    "q.m13#15.o3" to "À marquer la hauteur",
    "q.m13#15.e" to "Tirer uniquement aux bras épuise en quelques dizaines de mètres. L'étrier fait participer les jambes : c'est ce qui décide si l'on sort ou non.",

    "q.m13#16.p" to "Lors d'un sauvetage en cordée, quelle est la première chose à faire ?",
    "q.m13#16.o0" to "Bloquer et assurer, pour empêcher celui qui est tombé de continuer à glisser",
    "q.m13#16.o1" to "Descendre immédiatement dans la crevasse",
    "q.m13#16.o2" to "Appeler les secours",
    "q.m13#16.o3" to "Prendre des photos",
    "q.m13#16.e" to "Le blocage est la seule chose qui ne peut pas attendre. Une fois la position assurée, on parle de communication, de système et de traction.",

    "q.m13#17.p" to "Quand une personne est suspendue dans une crevasse, quelles atteintes faut-il craindre le plus ?",
    "q.m13#17.o0" to "L'hypothermie, la compression par la corde et les traumatismes liés aux chocs",
    "q.m13#17.o1" to "Les coups de soleil",
    "q.m13#17.o2" to "Le mal des montagnes",
    "q.m13#17.o3" to "La déshydratation",
    "q.m13#17.e" to "Il fait très froid dans une crevasse, et la suspension gêne la circulation. Le sauvetage doit être rapide : il ne s'agit pas seulement de remonter la personne.",

    "q.m13#18.p" to "Pourquoi faut-il d'abord donner à la victime un moyen de « s'auto-assurer » ?",
    "q.m13#18.o0" to "Pour qu'elle ne dépende plus de la corde principale et libérer les mains du sauveteur pour construire le système",
    "q.m13#18.o1" to "Parce qu'on ne fait pas confiance à la corde",
    "q.m13#18.o2" to "Parce que la norme l'exige",
    "q.m13#18.o3" to "Parce qu'on manque de matériel",
    "q.m13#18.e" to "L'auto-assurance (nœud autobloquant ou piolet) stabilise la position, et donne aussi à la victime quelque chose à faire, ce qui réduit la panique.",

    "q.m13#19.p" to "Quand la victime ne peut pas agir seule, comment la sortir correctement d'une crevasse ?",
    "q.m13#19.o0" to "Monter un système 3:1 ou 5:1 et la remonter depuis le haut",
    "q.m13#19.o1" to "Tirer la corde à la main",
    "q.m13#19.o2" to "Lui demander de grimper",
    "q.m13#19.o3" to "Enrouler la corde autour de la taille",
    "q.m13#19.e" to "Tirer à la main est presque impossible et fait perdre tout contrôle. La traction sur système est la seule méthode fiable.",

    "q.m13#20.p" to "D'où vient la pression temporelle pendant un sauvetage ?",
    "q.m13#20.o0" to "De la vitesse de refroidissement, de l'évolution de la météo et de l'épuisement de l'équipe",
    "q.m13#20.o1" to "Uniquement de la forme physique",
    "q.m13#20.o2" to "Uniquement de la météo",
    "q.m13#20.o3" to "Uniquement de l'hypothermie",
    "q.m13#20.e" to "Les trois agissent ensemble. Un plan de sauvetage doit se demander « en combien de temps peut-on finir », pas seulement « peut-on finir ».",

    "q.m13#21.p" to "Quel est le moyen de communication le moins fiable en sauvetage ?",
    "q.m13#21.o0" to "Crier par-dessus un petit ressaut de neige",
    "q.m13#21.o1" to "La radio",
    "q.m13#21.o2" to "Les signaux par la corde",
    "q.m13#21.o3" to "Le sifflet",
    "q.m13#21.e" to "Le vent, la longueur de corde et le terrain absorbent la voix. Convenir à l'avance de signaux par la corde ou au sifflet est bien plus fiable que de crier sur place.",

    "q.m13#22.p" to "Pourquoi les gestes d'auto-sauvetage doivent-ils être « répétés sur terrain sûr jusqu'à devenir automatiques » ?",
    "q.m13#22.o0" to "En chute réelle, l'attention est envahie par la peur : seuls les gestes automatiques s'exécutent",
    "q.m13#22.o1" to "Pour l'examen",
    "q.m13#22.o2" to "Pour la vitesse",
    "q.m13#22.o3" to "Pour l'esthétique",
    "q.m13#22.e" to "C'est la logique commune de toute formation au sauvetage : automatiser les gestes pour libérer de la capacité d'observation et de jugement.",

    "q.m13#23.p" to "Dans un sauvetage en cordée, quelle est la tâche principale du deuxième membre ?",
    "q.m13#23.o0" to "Aider au blocage, préparer le système, surveiller les risques au-dessus",
    "q.m13#23.o1" to "Prendre des photos",
    "q.m13#23.o2" to "Continuer d'avancer",
    "q.m13#23.o3" to "Ranger la corde",
    "q.m13#23.e" to "C'est là tout l'intérêt d'une cordée de trois : un bloque, un construit, un surveille. À deux, il faut tout assumer en même temps.",

    "q.m13#24.p" to "Si la victime est inconsciente, quelle est la priorité du sauvetage ?",
    "q.m13#24.o0" to "La sortir au plus vite et commencer les premiers secours, tout en appelant du renfort extérieur",
    "q.m13#24.o1" to "Monter d'abord un système 5:1",
    "q.m13#24.o2" to "Attendre les secours",
    "q.m13#24.o3" to "Commencer par documenter",
    "q.m13#24.e" to "L'inconscience signifie une fenêtre très courte. Ici, la rapidité passe avant l'économie d'effort : on utilise le système le plus simple si nécessaire.",

    "q.m13#25.p" to "Après un sauvetage, quelle étape est la plus souvent négligée ?",
    "q.m13#25.o0" to "Le débriefing du système et du déroulé, en notant les problèmes",
    "q.m13#25.o1" to "Ranger la corde",
    "q.m13#25.o2" to "Redescendre",
    "q.m13#25.o3" to "Manger",
    "q.m13#25.e" to "L'écart entre exercice et réalité apparaît au débriefing : quelle étape a été lente, quel nœud a été mal fait, quelle consigne personne n'a entendue.",

    "q.m13#26.p" to "Pourquoi le système de sauvetage doit-il être « indépendant de la corde principale » ?",
    "q.m13#26.o0" to "La corde principale peut être endommagée par les éclats de glace ou les arêtes, et elle est déjà en charge",
    "q.m13#26.o1" to "Parce que la norme l'exige",
    "q.m13#26.o2" to "Parce qu'elle est plus longue",
    "q.m13#26.o3" to "Parce qu'elle est plus légère",
    "q.m13#26.e" to "Suspendre le sauvetage à une corde abîmée et déjà chargée revient à empiler deux risques l'un sur l'autre.",

    "q.m13#27.p" to "En zone de crevasses, que doit décider l'équipe à l'avance ?",
    "q.m13#27.o0" to "Qui bloque, qui monte le système, comment on communique",
    "q.m13#27.o1" to "Qui marche devant",
    "q.m13#27.o2" to "Qui porte le sac le plus lourd",
    "q.m13#27.o3" to "Qui prend les photos",
    "q.m13#27.e" to "La répartition se fixe avant le départ. Dans les trente premières secondes d'une chute, personne n'a le temps de discuter de qui fait quoi.",

    // ---------- m14 Jugement du danger et décision ----------
    "q.m14#17.p" to "Quelle est la manifestation typique du « coût irrécupérable » dans une décision en montagne ?",
    "q.m14#17.o0" to "On a déjà mis tellement d'argent et de temps que ce serait gâché de renoncer",
    "q.m14#17.o1" to "La météo est mal prévue",
    "q.m14#17.o2" to "Le matériel manque",
    "q.m14#17.o3" to "Les coéquipiers sont trop lents",
    "q.m14#17.e" to "Plus on a investi, plus il est difficile de renoncer. Or le coût déjà payé ne sera pas récupéré en continuant : cela n'ajoute que de nouveaux risques.",

    "q.m14#18.p" to "Dans quelles conditions le « groupe pensant » apparaît-il le plus facilement ?",
    "q.m14#18.o0" to "Une forte cohésion, l'absence d'avis contraire et une prise de position trop précoce du chef",
    "q.m14#18.o1" to "Une équipe très divisée",
    "q.m14#18.o2" to "Un petit effectif",
    "q.m14#18.o3" to "Une mauvaise météo",
    "q.m14#18.e" to "La cohésion est une bonne chose, mais elle étouffe la contestation. Faire parler le plus jeune en premier, ou désigner un « avocat du diable », sont des réponses courantes.",

    "q.m14#19.p" to "Qu'appelle-t-on le « biais de confirmation » ?",
    "q.m14#19.o0" to "Ne chercher que les informations qui confirment son propre jugement et ignorer les preuves contraires",
    "q.m14#19.o1" to "Ne pas retenir les informations",
    "q.m14#19.o2" to "Être excessivement prudent",
    "q.m14#19.o3" to "Trop dépendre des autres",
    "q.m14#19.e" to "Si l'on veut « passer aujourd'hui », on ne remarque que les signes favorables de la météo. Chercher activement le contre-exemple est le seul remède.",

    "q.m14#20.p" to "Pourquoi utiliser des listes de contrôle pour les décisions importantes ?",
    "q.m14#20.o0" to "Sous la fatigue et la pression, on oublie des points ; la liste transforme « se souvenir » en « confirmer un à un »",
    "q.m14#20.o1" to "Pour garder une trace",
    "q.m14#20.o2" to "Pour paraître professionnel",
    "q.m14#20.o3" to "Parce que la norme l'exige",
    "q.m14#20.e" to "Une liste ne remplace pas le jugement : elle garantit que toutes les informations nécessaires au jugement sont réunies.",

    "q.m14#21.p" to "Quel est un exemple d'« effet d'ancrage » en course ?",
    "q.m14#21.o0" to "Prendre « 6 heures jusqu'au camp » comme référence et ignorer l'état réel du terrain",
    "q.m14#21.o1" to "Faire confiance au guide",
    "q.m14#21.o2" to "Lire la carte",
    "q.m14#21.o3" to "Mesurer la température",
    "q.m14#21.e" to "Dès qu'un ancrage existe, tous les jugements suivants s'ajustent autour de lui. Il faut se baser sur la progression réelle, pas sur la valeur prévue.",

    "q.m14#22.p" to "Quelle est la valeur de consigner une décision (heure, base, conclusion) ?",
    "q.m14#22.o0" to "Le débriefing s'appuie sur des faits et l'équipe partage une lecture commune des mêmes événements",
    "q.m14#22.o1" to "Pour le rapport",
    "q.m14#22.o2" to "Pour l'assurance",
    "q.m14#22.o3" to "Pour écrire un livre",
    "q.m14#22.e" to "Sans trace, le débriefing devient « chacun sa version ». Écrire la chronologie permet de voir à quel moment on aurait pu décider plus tôt.",

    "q.m14#23.p" to "Quel risque concret crée le « halo de l'expert » ?",
    "q.m14#23.o0" to "Personne n'ose contester une erreur évidente, et l'erreur est exécutée sans obstacle",
    "q.m14#23.o1" to "L'expert se fatigue",
    "q.m14#23.o2" to "L'expert coûte cher",
    "q.m14#23.o3" to "L'expert ne connaît pas l'itinéraire",
    "q.m14#23.e" to "Le halo bloque la remontée d'information. L'état le plus dangereux dans une équipe n'est pas que personne ne sache, mais que personne n'ose parler.",

    // ---------- m17 Camp de haute altitude et gestion du matériel ----------
    "q.m17#16.p" to "À quoi sert la « rotation du matériel » entre les camps d'altitude ?",
    "q.m17#16.o0" to "À ce que chaque camp dispose de juste ce qu'il faut, sans accumulation ici ni rupture là",
    "q.m17#16.o1" to "À alléger les charges",
    "q.m17#16.o2" to "À faciliter les statistiques",
    "q.m17#16.o3" to "À respecter les règles",
    "q.m17#16.e" to "En expédition, le matériel est distribué par étapes. Sans tableau de rotation, le résultat le plus fréquent est de manquer de gaz au camp d'altitude juste avant l'assaut.",

    "q.m17#17.p" to "Comment estimer le carburant d'un camp ?",
    "q.m17#17.o0" to "Personnes × jours × consommation par personne et par jour (la fonte de neige est le poste le plus lourd)",
    "q.m17#17.o1" to "Par nombre de cartouches",
    "q.m17#17.o2" to "Au poids",
    "q.m17#17.o3" to "À l'expérience",
    "q.m17#17.e" to "Faire fondre de la neige pour l'eau est le premier poste de dépense en altitude. L'estimation se fait sur le temps le plus froid, pas sur les conditions idéales.",

    "q.m17#18.p" to "Par quoi renforce-t-on une tente par vent fort ?",
    "q.m17#18.o0" to "L'angle des haubans, les points de fixation au vent et l'ensevelissement de la jupe à neige",
    "q.m17#18.o1" to "La couleur de la tente",
    "q.m17#18.o2" to "La fermeture de la chambre intérieure",
    "q.m17#18.o3" to "L'épaisseur du tapis de sol",
    "q.m17#18.e" to "Une tente se détruit rarement par la toile : c'est presque toujours un point de fixation qui lâche d'abord. Doubler les haubans au vent et lester la jupe avec des blocs de neige est la pratique courante.",

    "q.m17#19.p" to "Quels sont l'avantage et le risque d'un igloo creusé dans une pente de neige ?",
    "q.m17#19.o0" to "Très bon abri contre le vent et bonne isolation ; mais risque d'effondrement et de monoxyde de carbone",
    "q.m17#19.o1" to "Économise la tente ; mais il y fait trop froid",
    "q.m17#19.o2" to "Pratique ; mais interdit",
    "q.m17#19.o3" to "Aucun risque",
    "q.m17#19.e" to "Un igloo exige un évent et un jugement sur l'épaisseur du toit. Mettre un réchaud dans un igloo fermé est le scénario classique d'intoxication au monoxyde de carbone.",

    "q.m17#20.p" to "Quand on utilise un réchaud sous la tente, de quoi faut-il surtout se protéger ?",
    "q.m17#20.o0" to "De l'intoxication au monoxyde de carbone et de l'incendie",
    "q.m17#20.o1" to "De l'humidité",
    "q.m17#20.o2" to "Du froid, à part le manque d'oxygène",
    "q.m17#20.o3" to "De la déformation de la tente",
    "q.m17#20.e" to "Le monoxyde de carbone est incolore et inodore, et ses symptômes ressemblent à ceux du mal des montagnes. Il faut ventiler, et si possible cuisiner dans l'absidiole ou dehors.",

    "q.m17#21.p" to "Quel est le principe de gestion des déchets en camp d'altitude ?",
    "q.m17#21.o0" to "Tout redescendre : ni enfouissement ni incinération en camp d'altitude",
    "q.m17#21.o1" to "Enterrer dans la neige",
    "q.m17#21.o2" to "Brûler",
    "q.m17#21.o3" to "Laisser pour l'équipe suivante",
    "q.m17#21.e" to "La décomposition est extrêmement lente en altitude : enfouis ou brûlés, les déchets réapparaissent à la fonte. Les redescendre est la seule pratique conforme.",

    "q.m17#22.p" to "Comment gagner en efficacité quand on fait fondre de la neige ?",
    "q.m17#22.o0" to "Mettre un peu d'eau d'abord, puis la neige, à feu vif, sans chauffer à sec",
    "q.m17#22.o1" to "Remplir directement de neige",
    "q.m17#22.o2" to "Feu doux et long",
    "q.m17#22.o3" to "Faire fondre à l'eau froide",
    "q.m17#22.e" to "Chauffer à sec brûle le fond de la casserole et n'est pas efficace du tout. « Un fond d'eau plus feu vif » économise nettement carburant et temps.",

    "q.m17#23.p" to "Comment organiser les nuits en camp d'altitude ?",
    "q.m17#23.o0" to "Tourner selon le plan, sans enchaîner plusieurs nuits au camp le plus haut",
    "q.m17#23.o1" to "Dormir le plus haut possible",
    "q.m17#23.o2" to "Toujours dormir au camp le plus haut",
    "q.m17#23.o3" to "Au hasard",
    "q.m17#23.e" to "La rotation concilie acclimatation et récupération. Enchaîner les nuits en altitude accumule la fatigue et ralentit finalement tout le monde.",

    // ---------- m18 Sommets cibles : Muztagh Ata et Ama Dablam ----------
    "q.m18#16.p" to "Quelle est l'altitude et la situation du Muztagh Ata ?",
    "q.m18#16.o0" to "7 509 m, Akto au Xinjiang, bord est du Pamir",
    "q.m18#16.o1" to "6 812 m, Népal",
    "q.m18#16.o2" to "7 134 m, Kirghizistan",
    "q.m18#16.o3" to "8 163 m, Népal",
    "q.m18#16.e" to "Le « père des glaciers de glace » est l'un des premiers choix du niveau 7 000 m en Chine : pentes de neige interminables, exigence forte d'acclimatation et de condition physique.",

    "q.m18#17.p" to "Où se situe la principale difficulté du Muztagh Ata ?",
    "q.m18#17.o0" to "L'acclimatation en altitude et l'endurance sur de longues pentes de neige, non la difficulté technique",
    "q.m18#17.o1" to "Des parois rocheuses verticales",
    "q.m18#17.o2" to "Une densité élevée de crevasses",
    "q.m18#17.o3" to "De la cascade de glace technique",
    "q.m18#17.e" to "Sa difficulté technique est relativement modérée, mais « long, haut et froid » amplifie tout déficit de condition physique et d'acclimatation.",

    "q.m18#18.p" to "Dans quel pays ou région se trouve le pic Lénine ?",
    "q.m18#18.o0" to "À la frontière entre le Kirghizistan et le Tadjikistan",
    "q.m18#18.o1" to "Au Népal",
    "q.m18#18.o2" to "Au Xinjiang chinois",
    "q.m18#18.o3" to "Au Pakistan",
    "q.m18#18.e" to "Dans le Pamir, le pic Lénine est souvent choisi comme premier 7 000 m, mais il faut tout de même affronter l'altitude et un terrain glaciaire.",

    "q.m18#19.p" to "Quelle est l'altitude de l'Ama Dablam ?",
    "q.m18#19.o0" to "6 812 m",
    "q.m18#19.o1" to "7 509 m",
    "q.m18#19.o2" to "7 126 m",
    "q.m18#19.o3" to "6 189 m",
    "q.m18#19.e" to "Moins de 7 000 m, mais son terrain mixte rocher-neige en forte pente et son exposition marquée situent sa difficulté technique au niveau des 7 000 m et plus.",

    "q.m18#20.p" to "De quoi l'Ama Dablam sert-elle souvent de « pierre de touche » ?",
    "q.m18#20.o0" to "De la préparation technique et mentale pour le niveau 8 000 m",
    "q.m18#20.o1" to "De première montagne enneigée",
    "q.m18#20.o2" to "D'itinéraire de ski",
    "q.m18#20.o3" to "De sentier de randonnée",
    "q.m18#20.e" to "Son exposition et sa combinaison technique testent la capacité à « exécuter le bon geste sous pression ».",

    "q.m18#21.p" to "Quelle est en général la fenêtre de saison pour un sommet de 7 000 m ?",
    "q.m18#21.o0" to "Plus étroite que pour un 5 000 ou 6 000 m : le vent d'altitude et les chutes de neige la déterminent",
    "q.m18#21.o1" to "Ouverte toute l'année",
    "q.m18#21.o2" to "Uniquement en hiver",
    "q.m18#21.o3" to "Identique à celle de basse altitude",
    "q.m18#21.e" to "Plus on monte, plus la fenêtre dépend du vent d'altitude et de la mousson. Une fenêtre étroite impose d'être plus tranchant sur « attendre » et sur « renoncer ».",

    "q.m18#22.p" to "Pour choisir un objectif de 7 000 m, quelle capacité faut-il d'abord vérifier ?",
    "q.m18#22.o0" to "Avoir déjà accompli de façon régulière, à 6 000 m, de longues progressions sur neige et une bonne autonomie",
    "q.m18#22.o1" to "La difficulté en escalade rocheuse",
    "q.m18#22.o2" to "Les performances en course à pied",
    "q.m18#22.o3" to "La quantité de matériel",
    "q.m18#22.e" to "Le seuil du 7 000 m est la tolérance et l'autonomie, pas un geste technique précis. On regarde d'abord son propre historique à 6 000 m.",

    "q.m18#23.p" to "Pour ces sommets, les permis et la logistique demandent en général…",
    "q.m18#23.o0" to "De demander les permis plusieurs semaines à l'avance et d'organiser guide, portage et ravitaillement des camps",
    "q.m18#23.o1" to "De tout faire sur place",
    "q.m18#23.o2" to "Aucun permis",
    "q.m18#23.o3" to "Simplement un billet",
    "q.m18#23.e" to "Plus l'itinéraire est isolé, plus la chaîne logistique est longue. Traiter permis et logistique comme « une partie de la préparation technique » coûte bien moins cher qu'une réparation de dernière minute.",
    // ---------- m19 Limites physiologiques à 8 000 m et manque d'oxygène ----------
    "q.m19#19.p" to "La « zone de la mort » désigne en général les altitudes au-dessus de…",
    "q.m19#19.o0" to "8 000 m",
    "q.m19#19.o1" to "6 000 m",
    "q.m19#19.o2" to "7 000 m",
    "q.m19#19.o3" to "5 000 m",
    "q.m19#19.e" to "Au-dessus de 8 000 m, la pression atmosphérique vaut environ un tiers de celle du niveau de la mer : le corps ne peut plus maintenir d'équilibre et ne fait que consommer.",

    "q.m19#20.p" to "À 8 000 m, pourquoi le « repos » ne permet-il pas vraiment de récupérer ?",
    "q.m19#20.o0" to "L'apport d'oxygène ne suffit pas à la réparation : le corps reste en bilan négatif",
    "q.m19#20.o1" to "Parce qu'il fait trop froid",
    "q.m19#20.o2" to "Parce qu'on dort mal",
    "q.m19#20.o3" to "À cause de la déshydratation",
    "q.m19#20.e" to "C'est la base physiologique du « moins on reste, mieux c'est ». Toute la tactique s'organise autour de la réduction de l'exposition.",

    "q.m19#21.p" to "Quelle est la manifestation la plus dangereuse du déclin cognitif en altitude ?",
    "q.m19#21.o0" to "On ne s'aperçoit pas soi-même que son jugement se dégrade",
    "q.m19#21.o1" to "Une mauvaise mémoire",
    "q.m19#21.o2" to "Une baisse des réflexes",
    "q.m19#21.o3" to "Un manque de concentration",
    "q.m19#21.e" to "Le manque d'oxygène affaiblit d'abord la capacité à s'auto-évaluer. D'où l'intérêt d'externaliser les décisions : listes écrites, relecture par un autre.",

    // ---------- m20 Système d'oxygène et approvisionnement ----------
    "q.m20#20.p" to "Pourquoi la « capacité utilisable » d'une bouteille d'oxygène diffère-t-elle de sa capacité nominale ?",
    "q.m20#20.o0" to "La pression résiduelle empêche d'utiliser la dernière partie, et le froid abaisse la pression",
    "q.m20#20.o1" to "À cause d'une fuite",
    "q.m20#20.o2" to "Parce qu'elle est mal étiquetée",
    "q.m20#20.o3" to "À cause de l'usure du masque",
    "q.m20#20.e" to "Les calculs se font sur la capacité utilisable. Prendre la valeur nominale pour de l'utilisable est une cause fréquente d'« oxygène épuisé avant le sommet ».",

    "q.m20#21.p" to "Quel est le coût d'une augmentation du débit d'oxygène ?",
    "q.m20#21.o0" to "L'autonomie diminue proportionnellement et il faut davantage de bouteilles de secours",
    "q.m20#21.o1" to "Aucun coût",
    "q.m20#21.o2" to "Le masque s'abîme",
    "q.m20#21.o3" to "La bouteille gèle",
    "q.m20#21.e" to "Débit et autonomie sont inversement proportionnels. Augmenter le débit impose de recalculer le besoin total et les réserves.",

    // ---------- m21 Les 14 sommets de 8 000 m (1) : Himalaya ----------
    "q.m21#18.p" to "Quelle est la dernière altitude officielle de l'Everest ?",
    "q.m21#18.o0" to "8 848,86 m (mesure conjointe Chine-Népal de 2020)",
    "q.m21#18.o1" to "8 848 m",
    "q.m21#18.o2" to "8 850 m",
    "q.m21#18.o3" to "8 846 m",
    "q.m21#18.e" to "8 848,86 m est la valeur publiée conjointement en 2020. Les 8 848 m des anciens manuels restent la valeur classique : les deux circulent.",

    "q.m21#19.p" to "Quelle est la position du Lhotse par rapport à l'Everest ?",
    "q.m21#19.o0" to "Immédiatement au sud de l'Everest, souvent gravi sur le même itinéraire",
    "q.m21#19.o1" to "Au nord de l'Everest",
    "q.m21#19.o2" to "À l'ouest du Népal",
    "q.m21#19.o3" to "Dans le Karakoram",
    "q.m21#19.e" to "Les deux sommets partagent une partie de l'itinéraire par le col Sud : « Everest plus Lhotse » est donc souvent organisé dans une même expédition.",

    "q.m21#20.p" to "Où se trouve le Kangchenjunga ?",
    "q.m21#20.o0" to "À la frontière entre le Népal et l'Inde",
    "q.m21#20.o1" to "À la frontière entre la Chine et le Népal",
    "q.m21#20.o2" to "Au Pakistan",
    "q.m21#20.o3" to "Au Bhoutan",
    "q.m21#20.e" to "Troisième plus haut sommet du monde, à la frontière entre le Népal et l'Inde (Sikkim) : permis et logistique y sont relativement complexes.",

    "q.m21#21.p" to "Quelle est la caractéristique de l'Annapurna I ?",
    "q.m21#21.o0" to "Une mortalité relativement élevée, un itinéraire raide et des risques marqués d'avalanche et de chutes de pierres",
    "q.m21#21.o1" to "C'est le plus facile",
    "q.m21#21.o2" to "C'est le plus haut",
    "q.m21#21.o3" to "Il se gravit toute l'année",
    "q.m21#21.e" to "C'est l'un des plus risqués des 8 000 m. Le chiffre rappelle que l'ordre des altitudes n'est pas l'ordre des difficultés.",

    // ---------- m22 Les 14 sommets de 8 000 m (2) : Karakoram et vue d'ensemble ----------
    "q.m22#17.p" to "Quelle est l'altitude officielle du K2 et son surnom ?",
    "q.m22#17.o0" to "8 611 m, « la montagne sauvage »",
    "q.m22#17.o1" to "8 586 m, « la panthère des neiges »",
    "q.m22#17.o2" to "8 126 m, « la montagne nue »",
    "q.m22#17.o3" to "8 080 m, « le sommet caché »",
    "q.m22#17.e" to "Le K2 est le deuxième plus haut sommet du monde, et sa difficulté technique comme sa mortalité figurent durablement parmi les plus élevées des 8 000 m.",

    "q.m22#18.p" to "Quel est le surnom du Nanga Parbat et son risque principal ?",
    "q.m22#18.o0" to "« La montagne nue », avec un dénivelé énorme qui engendre des risques d'avalanche et de chutes de pierres",
    "q.m22#18.o1" to "« Le père des glaciers »",
    "q.m22#18.o2" to "« Le sommet caché »",
    "q.m22#18.o3" to "« La montagne qui tue »",
    "q.m22#18.e" to "Sa face sud est l'un des plus grands dénivelés rocheux du monde. Itinéraire exposé, météo changeante, retrait difficile.",

    "q.m22#19.p" to "Quelles sont les altitudes du Gasherbrum I et du Gasherbrum II ?",
    "q.m22#19.o0" to "8 080 m et 8 035 m",
    "q.m22#19.o1" to "8 051 m et 8 080 m",
    "q.m22#19.o2" to "8 611 m et 8 586 m",
    "q.m22#19.o3" to "8 188 m et 8 167 m",
    "q.m22#19.e" to "GI 8 080, GII 8 035. Les deux sont souvent comparés, mais leurs itinéraires et leurs difficultés diffèrent beaucoup.",

    "q.m22#20.p" to "Quelle est l'altitude du Broad Peak ?",
    "q.m22#20.o0" to "8 051 m",
    "q.m22#20.o1" to "8 035 m",
    "q.m22#20.o2" to "8 080 m",
    "q.m22#20.o3" to "8 126 m",
    "q.m22#20.e" to "Broad Peak, 8 051 m, est souvent considéré comme l'un des 8 000 m les moins techniques, mais il comporte toujours de longues pentes de neige et le risque d'altitude.",

    "q.m22#21.p" to "Combien de sommets de 8 000 m compte le Pakistan ?",
    "q.m22#21.o0" to "Cinq",
    "q.m22#21.o1" to "Trois",
    "q.m22#21.o2" to "Quatre",
    "q.m22#21.o3" to "Deux",
    "q.m22#21.e" to "K2, Nanga Parbat, Gasherbrum I et II, Broad Peak : cinq au total.",

    // ---------- l19 Plan d'ascension et décision de retrait ----------
    "q.l19#16.p" to "Quelle « information négative » un plan d'ascension exécutable doit-il contenir ?",
    "q.l19#16.o0" to "Dans quelles conditions on renonce, par où on descend, jusqu'où on redescend",
    "q.l19#16.o1" to "Uniquement l'itinéraire de sommet",
    "q.l19#16.o2" to "Uniquement la liste de matériel",
    "q.l19#16.o3" to "Uniquement le budget",
    "q.l19#16.e" to "Un plan qui ne décrit que « comment réussir » perd toute force contraignante sous la pression. Les conditions de retrait doivent être écrites à l'avance.",

    "q.l19#17.p" to "À quoi sert un « itinéraire de repli » dans un plan ?",
    "q.l19#17.o0" to "À garder une option exécutable quand l'itinéraire principal devient impraticable",
    "q.l19#17.o1" to "À faire joli",
    "q.l19#17.o2" to "À économiser de l'argent",
    "q.l19#17.o3" to "À respecter les règles",
    "q.l19#17.e" to "Un itinéraire de repli évite de forcer le passage quand le plan initial est contrarié. Sans plan B, le plan A devient le seul pari.",

    "q.l19#18.p" to "Pourquoi les décisions de retrait doivent-elles avoir des « déclencheurs fixés à l'avance » ?",
    "q.l19#18.o0" to "Sous la fatigue et la pression de l'objectif, on relâche sans cesse les critères",
    "q.l19#18.o1" to "Parce qu'on ne s'en souvient pas",
    "q.l19#18.o2" to "Parce que la norme l'exige",
    "q.l19#18.o3" to "Parce que le guide le demande",
    "q.l19#18.e" to "Un déclencheur doit être concret : telle heure, telle vitesse de vent, telle visibilité, tel symptôme chez telle personne. Un critère flou équivaut à aucun critère.",

    "q.l19#19.p" to "Quand certains veulent redescendre et d'autres continuer, quelle est la réponse la plus raisonnable ?",
    "q.l19#19.o0" to "Revenir aux déclencheurs convenus et juger sur les faits, pas sur les envies",
    "q.l19#19.o1" to "Voter",
    "q.l19#19.o2" to "Suivre le chef",
    "q.l19#19.o3" to "Se séparer",
    "q.l19#19.e" to "Transformer le désaccord en « comparaison aux critères » évite qu'il devienne un conflit interpersonnel. Les critères se fixent avant le départ, pas sur place.",

    "q.l19#20.p" to "Jusqu'où faut-il reconnaître l'itinéraire de retrait à l'avance ?",
    "q.l19#20.o0" to "Connaître les virages clés, les points de rappel et l'emplacement des camps de repli",
    "q.l19#20.o1" to "Connaître la direction générale",
    "q.l19#20.o2" to "Ce n'est pas nécessaire",
    "q.l19#20.o3" to "On verra sur place",
    "q.l19#20.e" to "Le retrait se fait souvent par mauvais temps. Quand la visibilité est mauvaise, « la direction générale » revient à ne pas avoir d'information.",

    "q.l19#21.p" to "Comment prévoir la « marge de temps » dans un plan ?",
    "q.l19#21.o0" to "Garder 20 à 30 % de marge par étape et une journée distincte pour les retards météo",
    "q.l19#21.o1" to "Ne pas en prévoir",
    "q.l19#21.o2" to "Une seule journée",
    "q.l19#21.o3" to "Calculer sur l'allure la plus rapide",
    "q.l19#21.e" to "La marge est le budget de l'imprévu. Un programme sans jeu s'effondre dès le premier changement.",

    // ---------- l20 Urgence et procédure de secours ----------
    "q.l20#16.p" to "Dans un message d'appel aux secours, quelle information est la plus souvent oubliée ?",
    "q.l20#16.o0" to "La différence entre les coordonnées actuelles et la « dernière position connue »",
    "q.l20#16.o1" to "Le nom",
    "q.l20#16.o2" to "Le nombre de personnes",
    "q.l20#16.o3" to "La météo",
    "q.l20#16.e" to "« Où je suis maintenant » et « où je me suis confirmé pour la dernière fois » sont deux informations différentes, et la seconde détermine la zone de recherche.",

    "q.l20#17.p" to "Pourquoi un secours héliporté est-il souvent difficile en altitude ?",
    "q.l20#17.o0" to "L'air raréfié réduit la portance et la charge utile, et les fenêtres météo sont courtes",
    "q.l20#17.o1" to "À cause du coût",
    "q.l20#17.o2" to "Parce qu'il n'y a pas de couloir aérien",
    "q.l20#17.o3" to "Parce que les pilotes refusent",
    "q.l20#17.e" to "C'est pourquoi « l'hélicoptère n'est pas un plan de secours ». Il faut posséder sa propre capacité d'auto-sauvetage et d'attente.",

    "q.l20#18.p" to "Qui doit lancer la demande de secours ?",
    "q.l20#18.o0" to "Le contact désigné à l'avance, qui la lance après le délai prévu par le protocole",
    "q.l20#18.o1" to "N'importe qui la voit",
    "q.l20#18.o2" to "La victime elle-même",
    "q.l20#18.o3" to "Attendre le lendemain",
    "q.l20#18.e" to "Un contact désigné évite le « tout le monde croyait que quelqu'un l'avait fait ». Le protocole doit préciser l'heure, qui appelle et qui est appelé.",

    "q.l20#19.p" to "Quel est en général l'ordre de priorité des premiers secours sur place ?",
    "q.l20#19.o0" to "Hémostase et voies aériennes, puis isolation thermique, puis immobilisation, puis évacuation",
    "q.l20#19.o1" to "L'évacuation d'abord",
    "q.l20#19.o2" to "L'immobilisation d'abord",
    "q.l20#19.o3" to "L'antalgie d'abord",
    "q.l20#19.e" to "On traite d'abord ce qui tue en quelques minutes, ensuite ce qui s'aggrave en quelques heures. En altitude, l'isolation thermique remonte dans l'ordre.",

    "q.l20#20.p" to "En attendant les secours, que doit surtout faire l'équipe ?",
    "q.l20#20.o0" to "Monter un abri, se protéger du froid, marquer sa position et économiser ses forces",
    "q.l20#20.o1" to "Continuer à chercher un chemin",
    "q.l20#20.o2" to "Se disperser pour chercher",
    "q.l20#20.o3" to "Utiliser tout le matériel",
    "q.l20#20.e" to "L'objectif de l'attente est de « tenir jusqu'à l'arrivée des secours », pas de « résoudre seul ». Les forces sont la ressource la plus précieuse.",

    "q.l20#21.p" to "Lors de la passation à l'équipe de secours, quelle information est la plus utile ?",
    "q.l20#21.o0" to "La chronologie, l'évolution de l'état, les gestes déjà faits, le matériel restant",
    "q.l20#21.o1" to "Les impressions",
    "q.l20#21.o2" to "Le paysage de l'itinéraire",
    "q.l20#21.o3" to "La marque du matériel",
    "q.l20#21.e" to "La chronologie et le relevé des gestes déterminent la suite du jugement médical. Une passation écrite est plus fiable qu'une description orale.",

    // ---------- m23 Examen final complet (1) ----------
    "q.m23#18.p" to "Situation : à 7 500 m, un coéquipier présente une ataxie, et il ne reste que 2 heures d'oxygène. Que faire en premier ?",
    "q.m23#18.o0" to "Redescendre immédiatement en donnant de l'oxygène, et prévenir le camp de base pour préparer le relais",
    "q.m23#18.o1" to "Se reposer d'abord pour observer",
    "q.m23#18.o2" to "Donner d'abord des médicaments",
    "q.m23#18.o3" to "Continuer jusqu'au camp et traiter là-bas",
    "q.m23#18.e" to "L'ataxie évoque un HACE. La descente est la seule mesure dont l'efficacité est certaine ; l'oxygène sert à gagner du temps.",

    "q.m23#19.p" to "Situation : le jour du sommet, on découvre que la corde fixe a été usée jusqu'à l'effilochage par l'équipe précédente. Que faire ?",
    "q.m23#19.o0" to "Ne plus utiliser ce tronçon : changer d'itinéraire ou renoncer",
    "q.m23#19.o1" to "Continuer en faisant attention",
    "q.m23#19.o2" to "Prévenir seulement ceux qui suivent",
    "q.m23#19.o3" to "Noter et continuer",
    "q.m23#19.e" to "On ne peut pas estimer la résistance d'une corde usée. La corde fixe est la ligne de vie de tout le monde : « faire attention » ne compense pas.",

    "q.m23#20.p" to "Situation : à 6 500 m, l'équipe est prise dans une tempête avec 5 m de visibilité. Quel est le choix le plus raisonnable ?",
    "q.m23#20.o0" to "Monter un abri à proximité et attendre, ou revenir au GPS en suivant une trace déjà enregistrée",
    "q.m23#20.o1" to "Continuer à chercher le chemin",
    "q.m23#20.o2" to "Se disperser pour chercher",
    "q.m23#20.o3" to "S'asseoir sur place en attendant que ça se lève",
    "q.m23#20.e" to "Par temps blanc, « chercher le chemin » revient presque toujours à dévier. S'arrêter pour s'abriter, ou revenir sur une trace enregistrée, sont les deux seules options viables.",

    "q.m23#21.p" to "Situation : toute l'équipe veut continuer, seule une personne sent que ce n'est pas juste, sans pouvoir l'expliquer. Que doit-elle faire ?",
    "q.m23#21.o0" to "Dire clairement « je ne le sens pas » et demander à l'équipe de revérifier ensemble les informations clés",
    "q.m23#21.o1" to "Suivre la majorité",
    "q.m23#21.o2" to "Se taire et suivre",
    "q.m23#21.o3" to "Rentrer seule",
    "q.m23#21.e" to "L'intuition est souvent un signal qu'on a remarqué sans le formuler. L'exprimer permet à l'équipe de vérifier les faits ensemble.",

    // ---------- m24 Examen final complet (2) ----------
    "q.m24#18.p" to "Situation : le jour du sommet, 4 heures de retard sur le plan, le vent forcit, un membre ralentit. Quel est le jugement le plus raisonnable ?",
    "q.m24#18.o0" to "Redescendre selon les conditions de demi-tour prévues, en consignant le déclencheur",
    "q.m24#18.o1" to "Continuer jusqu'au sommet puis voir",
    "q.m24#18.o2" to "Laisser la personne lente rentrer seule",
    "q.m24#18.o3" to "Accélérer pour rattraper le temps",
    "q.m24#18.e" to "Quand trois signaux apparaissent ensemble, la raison de « continuer » vient en général de la pression de l'objectif, pas des faits. Les conditions de demi-tour existent pour ce cas.",

    "q.m24#19.p" to "Situation : un coéquipier présente une dyspnée au repos alors que sa saturation reste à 80 %. Que faire ?",
    "q.m24#19.o0" to "Traiter comme un HAPE : repos, oxygène, préparation de la descente",
    "q.m24#19.o1" to "Continuer à observer",
    "q.m24#19.o2" to "Faire boire davantage",
    "q.m24#19.o3" to "Donner un antalgique",
    "q.m24#19.e" to "Les symptômes priment sur les chiffres. Une dyspnée au repos est le signal central du HAPE, et la descente en est le traitement le plus sûr.",

    "q.m24#20.p" to "Situation : sur un tronçon de corde fixe, un ancrage paraît douteux et l'équipe est déjà à mi-parcours. Que faire ?",
    "q.m24#20.o0" to "Arrêter l'usage du tronçon, ajouter une redondance ou changer d'itinéraire, et mettre d'abord les personnes en sécurité",
    "q.m24#20.o1" to "Passer rapidement",
    "q.m24#20.o2" to "Prévenir seulement ceux qui suivent",
    "q.m24#20.o3" to "Continuer à l'utiliser",
    "q.m24#20.e" to "« On est déjà à mi-parcours » n'est pas une raison de continuer. La défaillance d'un ancrage a des conséquences systémiques, pas individuelles.",

    "q.m24#21.p" to "Situation : la course est terminée. Que vaut-il le plus la peine de conserver ?",
    "q.m24#21.o0" to "Un débriefing écrit avec la chronologie, les bases des décisions et les points d'erreur",
    "q.m24#21.o1" to "Les photos",
    "q.m24#21.o2" to "La liste de matériel",
    "q.m24#21.o3" to "Les factures",
    "q.m24#21.e" to "Le débriefing transforme le vécu en expérience. Écrire « à quel moment on aurait pu décider plus tôt » rend la prochaine décision plus précoce possible.",

    // ---------- m25 Psychologie en altitude et habitudes de décision ----------
    "q.m25#12.p" to "Après un retrait, quel débriefing faut-il mener ?",
    "q.m25#12.o0" to "Revenir sur les bases du jugement de l'époque : quelles informations ont été ignorées, à quel moment on aurait pu décider plus tôt",
    "q.m25#12.o1" to "Ne retenir que la conclusion",
    "q.m25#12.o2" to "L'attribuer à la chance",
    "q.m25#12.o3" to "Ne plus en parler",
    "q.m25#12.e" to "Le but d'un débriefing n'est pas de désigner un coupable, mais de transformer « la prochaine fois, on le verra plus tôt » en expérience concrète. Écrire la chronologie est plus utile qu'écrire ses impressions.",
